window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["bc14"]={"id":"bc14","title":"14. 激素和信号转导","sub":"朱圣庚《生物化学》第4版 · 第14章","sub2":"第14章 · 全量PPT/笔记页 + 本页考点 + 课后题","modules":[{"i":0,"name":"第14章 激素和信号转导","slides":[{"i":0,"sec":"老师PPT逐页","title":"激素章节标题页","notes":"本章为朱圣庚《生物化学》第4版第14章“激素和信号转导”的章节标题页。全章从激素的定义与分类出发，逐步展开内分泌信号传递、激素合成与分泌，并以甲状腺激素、肾上腺素和垂体激素为重点实例。后续页面进入具体分类与通路，本页本身不含结构或代谢内容。","points":["本章主题是激素与细胞信号转导","先讲概念、分类和分泌调控，再讲具体激素","重点实例为甲状腺激素、肾上腺素和垂体激素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full1.jpg","imageExplain":"页面中央是章节大标题，可留意标题下的章节编号与“激素和信号转导”字样，确认这是全章入口而非内容页。","check":{"kind":"mcq","id":"bc14_check_0","q":"本章标题页指出，全章重点展开的具体激素实例是哪些？","a":"A","e":"本章标题页说明全章以甲状腺激素、肾上腺素和垂体激素为重点实例。","src":"本页自测","o":["A. 甲状腺激素、肾上腺素和垂体激素","B. 胰岛素、胰高血糖素和降钙素","C. 雌激素、孕激素和雄激素","D. 前列腺素、血栓烷和白三烯"],"oe":["A正确：标题页明确列出这三类重点实例。","B错误：胰岛素、胰高血糖素和降钙素属于后续提及内容，不是标题页强调的重点实例。","C错误：性激素在类固醇激素部分出现，但标题页未将其列为重点实例。","D错误：前列腺素等是脂肪酸衍生物，不是本章标题页强调的重点实例。"]}},{"i":1,"sec":"老师PPT逐页","title":"激素的定义与发现","notes":"激素是生物体内特殊组织或腺体产生、直接分泌到体液中、经体液运送到特定作用部位、引起特殊激动效应的一群微量有机化合物。定义包含产生部位、分泌方式、运输途径、靶部位和微量高效五个要素。1904年Bayliss与Starling提出激素概念，最早由促胰液素的研究确立。","points":["激素由特定组织或腺体产生","直接分泌入体液并随体液运输","只作用于特定靶部位","极微量即可产生显著效应","Bayliss与Starling于1904年提出概念"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full2.jpg","imageExplain":"概述页应关注定义句中“特殊组织或腺体产生—分泌入体液—运输到作用部位—微量有机化合物”这条主线，以及1904年Bayliss与Starling的出处。","check":{"kind":"mcq","id":"bc14_check_1","q":"关于激素概念的确立，下列哪项符合本章表述？","a":"A","e":"激素概念由Bayliss与Starling于1904年在促胰液素研究中提出。","src":"本页自测","o":["A. 1904年由Bayliss与Starling通过促胰液素研究提出","B. 1902年由Pavlov通过胃液分泌研究提出","C. 1921年由Banting与Best通过胰岛素研究提出","D. 1953年由Sanger通过胰岛素测序提出"],"oe":["A正确：时间、人物与促胰液素背景均与本章一致。","B错误：Pavlov以消化生理和条件反射闻名，并非激素概念提出者。","C错误：Banting与Best与胰岛素提取有关，不是激素概念的提出者。","D错误：Sanger完成胰岛素氨基酸序列测定，与激素概念提出无关。"]}},{"i":2,"sec":"老师PPT逐页","title":"内分泌信号传递方式","notes":"内分泌细胞将激素分泌入血液，激素随血流运送到远隔的靶细胞，与靶细胞膜上或胞内的特异性受体结合而发挥作用。这种方式体现远距离运输和靶细胞特异性两个特点。它与旁分泌、自分泌和神经分泌共同构成细胞间信号传递的不同模式。","points":["激素经血液运输","靶细胞具有特异性受体","作用距离远、起效相对缓慢","与旁分泌、自分泌、神经分泌相区别"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full3.jpg","imageExplain":"图中应从内分泌腺出发画出激素进入血管、随血流到达远处靶细胞的箭头，并标出靶细胞上的受体，突出“远距离+特异性”。","check":{"kind":"mcq","id":"bc14_check_2","q":"内分泌信号传递方式的两个核心特点是？","a":"A","e":"内分泌方式是激素入血、随血流到达远隔靶细胞，并与靶细胞特异性受体结合。","src":"本页自测","o":["A. 经血液远距离运输，并作用于有特异性受体的靶细胞","B. 经组织液短距离扩散，作用于所有邻近细胞","C. 经神经纤维直接支配，作用于无受体的细胞","D. 由细胞自身分泌并只作用于自身"],"oe":["A正确：同时体现远距离运输和靶细胞特异性。","B错误：短距离扩散更接近旁分泌，且并非作用于所有邻近细胞。","C错误：神经分泌经神经纤维，且靶细胞仍需受体。","D错误：只作用于自身是自分泌的特征。"]}},{"i":3,"sec":"老师PPT逐页","title":"激素的分类体系","notes":"激素可按来源分为动物激素与植物激素，动物激素又分脊椎动物激素和无脊椎动物激素。按化学本质可分为氨基酸衍生物激素、肽和蛋白质激素、类固醇激素以及脂肪酸衍生物激素。无脊椎动物还有甲壳类激素和昆虫激素等特殊类别。","points":["按来源分动物激素与植物激素","脊椎动物与无脊椎动物激素有别","按化学本质分四大类","无脊椎动物另有甲壳类、昆虫激素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full4.jpg","imageExplain":"分类图是树状结构，先分动物/植物，再在动物下分脊椎/无脊椎，并列出氨基酸衍生物、肽与蛋白质、类固醇、脂肪酸衍生物四支。","check":{"kind":"mcq","id":"bc14_check_3","q":"按化学本质划分，下列哪项不属于本章所列的激素类别？","a":"D","e":"本章按化学本质列出氨基酸衍生物、肽和蛋白质、类固醇以及脂肪酸衍生物四类，没有核酸衍生物激素。","src":"本页自测","o":["A. 氨基酸衍生物激素","B. 肽和蛋白质激素","C. 类固醇激素","D. 核酸衍生物激素"],"oe":["A正确：氨基酸衍生物激素是所列类别之一。","B正确：肽和蛋白质激素是所列类别之一。","C正确：类固醇激素是所列类别之一。","D错误：激素分类中不含核酸衍生物激素这一类。"]}},{"i":4,"sec":"老师PPT逐页","title":"按溶解性能分类","notes":"按溶解性能激素分为脂溶性激素和水溶性激素。脂溶性激素如类固醇激素和甲状腺激素，可穿过细胞膜与胞内或核受体结合。水溶性激素如肽类、蛋白质和儿茶酚胺，主要与细胞膜表面受体结合，通过第二信使传递信号。","points":["脂溶性：类固醇、甲状腺激素","水溶性：肽类、蛋白质、儿茶酚胺","脂溶性可进入细胞作用于核受体","水溶性多经膜受体和第二信使"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full5.jpg","imageExplain":"对比图中应画出脂溶性激素穿过磷脂双层进入胞内、水溶性激素停留在膜外结合膜受体的两条不同路径。","check":{"kind":"mcq","id":"bc14_check_4","q":"按溶解性能分类，下列属于脂溶性激素的是？","a":"A","e":"脂溶性激素包括类固醇激素和甲状腺激素，可穿过细胞膜与胞内或核受体结合。","src":"本页自测","o":["A. 类固醇激素和甲状腺激素","B. 胰岛素和胰高血糖素","C. 肾上腺素和去甲肾上腺素","D. 促甲状腺激素和促肾上腺皮质激素"],"oe":["A正确：二者均为本章归入脂溶性的激素。","B错误：胰岛素和胰高血糖素是蛋白质/多肽激素，属水溶性。","C错误：肾上腺素和去甲肾上腺素是儿茶酚胺，属水溶性。","D错误：TSH和ACTH是肽类/糖蛋白激素，属水溶性。"]}},{"i":5,"sec":"老师PPT逐页","title":"激素作用的五个特点","notes":"激素的产生部位不是所有细胞，而是某些特定组织细胞；作用部位不在产生部位，需经体液运输到靶器官或靶细胞。激素量少而作用大，主要调节新陈代谢、协调机体各部位功能。其分泌量随内外环境变化而增减，并直接或间接受到神经系统控制。","points":["产生于特定组织细胞而非所有细胞","作用部位远离产生部位","量少作用大、微量高效","调节代谢并协调机体功能","分泌受内外环境和神经系统调控"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full6.jpg","imageExplain":"五点并列的文字页应抓住“产生部位≠作用部位”这一核心，并注意末句激素调控常是局部的、受神经直接或间接控制。","check":{"kind":"mcq","id":"bc14_check_5","q":"下列哪项不是本章所述激素作用的特点？","a":"D","e":"激素由特定内分泌细胞产生，经体液运输到远隔靶细胞，量少作用大；靶细胞并不大量合成激素。","src":"本页自测","o":["A. 由特定组织细胞产生而非所有细胞","B. 作用部位远离产生部位","C. 微量即可产生显著效应","D. 由靶细胞大量合成后局部释放"],"oe":["A正确：这是激素产生的特点。","B正确：激素需经体液运输到靶器官或靶细胞。","C正确：激素量少而作用大，属微量高效。","D错误：激素由内分泌细胞产生，不是由靶细胞合成后局部释放。"]}},{"i":6,"sec":"老师PPT逐页","title":"激素分泌的调控中枢","notes":"激素分泌的最高调控涉及下丘脑与脑垂体。下丘脑位于间脑底部，通过释放因子和抑制因子调控腺垂体，腺垂体再分泌促激素影响外周靶腺。神经垂体则储存并释放下丘脑合成的催产素和升压素。","points":["下丘脑是内分泌调控的高级中枢","腺垂体受下丘脑释放/抑制因子控制","神经垂体储存并释放后叶激素","形成下丘脑—垂体—靶腺的调控链"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full7.jpg","imageExplain":"示意图应显示下丘脑在上、垂体借垂体柄相连，并分别标出腺垂体与神经垂体两条不同的调控去向。","check":{"kind":"mcq","id":"bc14_check_6","q":"关于下丘脑与垂体后叶的关系，正确的是？","a":"A","e":"催产素和升压素由下丘脑合成，经神经垂体储存并释放。","src":"本页自测","o":["A. 神经垂体储存并释放下丘脑合成的催产素和升压素","B. 神经垂体自身合成催产素和升压素","C. 下丘脑通过垂体门脉调控神经垂体","D. 神经垂体分泌促激素作用于外周靶腺"],"oe":["A正确：后叶激素的来源与储存释放部位表述正确。","B错误：神经垂体不合成这两种激素，合成部位在下丘脑。","C错误：垂体门脉联系主要针对腺垂体，不是神经垂体。","D错误：神经垂体不分泌促激素，促激素由腺垂体分泌。"]}},{"i":7,"sec":"老师PPT逐页","title":"垂体的解剖位置与分部","notes":"头部矢状切面显示下丘脑位于间脑底部，垂体借垂体柄悬垂于其下方，位于蝶鞍内。垂体分为前叶（腺垂体）和后叶（神经垂体）两部分。前叶腺体组织分泌多种促激素，后叶为神经组织，储存下丘脑运来的激素。","points":["下丘脑位于间脑底部","垂体经垂体柄与下丘脑相连","前叶为腺垂体、后叶为神经垂体","两叶来源与功能不同"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full8.jpg","imageExplain":"矢状切面图中应辨认垂体柄、蝶鞍以及前叶腺垂体和后叶神经垂体的相对位置，注意后叶与下丘脑的神经连接。","check":{"kind":"mcq","id":"bc14_check_7","q":"关于垂体的解剖与分部，下列哪项正确？","a":"A","e":"垂体借垂体柄悬垂于下丘脑下方，前叶是腺垂体，后叶是神经垂体。","src":"本页自测","o":["A. 垂体借垂体柄与下丘脑相连，前叶为腺垂体、后叶为神经垂体","B. 垂体位于颅腔内，前叶为神经组织、后叶为腺体组织","C. 垂体独立于下丘脑，通过血液与下丘脑无联系","D. 垂体后叶分泌多种促激素，前叶只储存激素"],"oe":["A正确：解剖连接与前后叶性质均正确。","B错误：前后叶性质说反了。","C错误：垂体经垂体柄与下丘脑相连，并非无联系。","D错误：促激素由腺垂体（前叶）分泌，后叶储存下丘脑运来的激素。"]}},{"i":8,"sec":"老师PPT逐页","title":"下丘脑对垂体前叶与后叶的调控","notes":"对前叶，下丘脑释放因子和抑制因子经垂体门脉血液送到腺垂体，促进或抑制其释放促激素。对后叶，下丘脑神经元的轴突直接延伸到神经垂体，在此释放加压素和催产素进入静脉而分布全身。两条通路一为血管联系，一为神经联系。","points":["前叶靠垂体门脉的体液调控","后叶靠下丘脑神经元轴突直接支配","后叶释放加压素与催产素","两种连接方式本质不同"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full9.jpg","imageExplain":"图中要区分两条通路：一条是释放因子经门脉血管到腺垂体，另一条是下丘脑神经元轴突直达神经垂体末梢释放激素入血。","check":{"kind":"mcq","id":"bc14_check_8","q":"下丘脑对垂体前叶的调控主要通过什么途径？","a":"A","e":"前叶靠垂体门脉的体液调控，下丘脑释放因子和抑制因子经门脉血送到腺垂体。","src":"本页自测","o":["A. 释放因子和抑制因子经垂体门脉血液送达腺垂体","B. 下丘脑神经元轴突直接延伸到腺垂体释放激素","C. 通过神经垂体转运输送释放因子","D. 通过外周靶腺激素直接刺激腺垂体"],"oe":["A正确：这是下丘脑调控腺垂体的血管联系途径。","B错误：轴突直接延伸是下丘脑对神经垂体的神经联系。","C错误：神经垂体不是释放因子转运到腺垂体的通路。","D错误：外周靶腺激素反馈作用于下丘脑和垂体，但不是下丘脑调控前叶的主要途径。"]}},{"i":9,"sec":"老师PPT逐页","title":"神经内分泌三长轴","notes":"下丘脑—垂体—靶腺构成三条长轴：HPT轴即下丘脑—垂体—甲状腺轴，主要调节代谢；HPA轴即下丘脑—垂体—肾上腺皮质轴，是应激轴；HPG轴即下丘脑—垂体—性腺轴，主管生殖。三条轴都是三级级联调控。","points":["HPT轴：代谢调节","HPA轴：应激反应","HPG轴：生殖功能","均为下丘脑—垂体—靶腺三级结构"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full10.jpg","imageExplain":"三长轴图应分别标出HPT、HPA、HPG三列，每列自上而下为下丘脑、垂体、甲状腺/肾上腺皮质/性腺，并注明代谢、应激、生殖。","check":{"kind":"mcq","id":"bc14_check_9","q":"HPA轴指的是哪条调控轴，其主要功能是什么？","a":"A","e":"HPA轴是下丘脑—垂体—肾上腺皮质轴，属于应激轴。","src":"本页自测","o":["A. 下丘脑—垂体—肾上腺皮质轴，主要参与应激反应","B. 下丘脑—垂体—甲状腺轴，主要调节代谢","C. 下丘脑—垂体—性腺轴，主管生殖","D. 下丘脑—垂体—胰岛轴，调节血糖"],"oe":["A正确：HPA的解剖组成与应激功能均正确。","B错误：该描述对应HPT轴。","C错误：该描述对应HPG轴。","D错误：HPA轴不指胰岛轴。"]}},{"i":10,"sec":"老师PPT逐页","title":"神经内分泌三短轴","notes":"三条短轴不经过独立的外周靶腺，而是下丘脑直接调控垂体激素。下丘脑—生长激素轴促进生长发育，下丘脑—催乳素轴促进泌乳，下丘脑—促黑素轴调节黑色素生成。短轴体现下丘脑对垂体前叶的直接释放因子调控。","points":["短轴无独立外周靶腺","生长激素轴管生长发育","催乳素轴管泌乳","促黑素轴管黑色素生成"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full11.jpg","imageExplain":"短轴图只有下丘脑和垂体两级，应看到生长激素、催乳素、促黑素三条并列支路，末端直接指向生理效应而非某个靶腺。","check":{"kind":"mcq","id":"bc14_check_10","q":"与三条长轴相比，神经内分泌短轴的主要特点是？","a":"A","e":"短轴没有独立的外周靶腺，是下丘脑直接调控垂体激素的轴。","src":"本页自测","o":["A. 不经过独立的外周靶腺，由下丘脑直接调控垂体激素","B. 必须经过肾上腺皮质作为外周靶腺","C. 由垂体后叶直接调控下丘脑","D. 只调节生殖功能"],"oe":["A正确：短轴的核心特点是不经独立外周靶腺。","B错误：经过肾上腺皮质的是HPA长轴。","C错误：短轴方向是下丘脑调控垂体，而非后叶调控下丘脑。","D错误：短轴包括生长激素轴、催乳素轴和促黑素轴，并非只调节生殖。"]}},{"i":11,"sec":"老师PPT逐页","title":"下丘脑—垂体—靶腺调控链","notes":"下丘脑释放因子或抑制因子作用于腺垂体，腺垂体分泌促激素，促激素再作用于外周腺体使其分泌腺体激素，最终作用于靶细胞。神经垂体则直接释放催产素和升压素。这条链条说明激素分泌具有逐级放大和反馈调节的基础。","points":["下丘脑释放/抑制因子为第一级","腺垂体促激素为第二级","外周腺体激素为第三级","神经垂体通路绕过腺垂体"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full12.jpg","imageExplain":"层级图应从上到下依次标出下丘脑、腺垂体、靶腺、靶细胞，并把催产素和升压素单列为神经垂体的直接输出。","check":{"kind":"mcq","id":"bc14_check_11","q":"在下丘脑—垂体—靶腺调控链中，第二级激素是？","a":"A","e":"第一级为下丘脑释放/抑制因子，第二级为腺垂体促激素，第三级为外周腺体激素。","src":"本页自测","o":["A. 腺垂体分泌的促激素","B. 下丘脑释放因子或抑制因子","C. 外周腺体分泌的腺体激素","D. 神经垂体释放的催产素"],"oe":["A正确：促激素处于调控链第二级。","B错误：下丘脑释放/抑制因子是第一级。","C错误：外周腺体激素是第三级。","D错误：神经垂体释放催产素走的是绕过腺垂体的直接通路。"]}},{"i":12,"sec":"老师PPT逐页","title":"神经内分泌四级级联","notes":"神经内分泌四级级联：①环境/中枢神经系统接收应激、光照、进食等信号；②下丘脑释放TRH/CRH/GnRH/GHRH等释放激素；③腺垂体分泌TSH/ACTH/LH/FSH/GH等促激素；④靶腺（甲状腺、肾上腺皮质、性腺、胰岛等）分泌T3/T4、皮质醇、性激素等，作用于终末靶组织。神经垂体不经过腺垂体，直接释放ADH和催产素。靶腺激素可负反馈抑制下丘脑/垂体。","points":["1级：环境/中枢→下丘脑","2级：下丘脑释放激素","3级：腺垂体促激素","4级：靶腺激素→终末组织","旁路：神经垂体直接释放ADH/OT","负反馈：靶腺激素抑制上位"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/four-level-cascade.png","imageExplain":"按箭头从上往下：环境/中枢→下丘脑释放激素→腺垂体促激素→靶腺激素→终末靶组织；右侧为神经垂体ADH/催产素旁路；红线为负反馈。","check":{"kind":"mcq","id":"bc14_check_12","q":"神经内分泌四级级联的正确顺序是？","a":"A","e":"级联由环境刺激启动，经CNS、下丘脑、垂体前叶、靶腺，最终作用于终末靶组织。","src":"本页自测","o":["A. 环境→中枢神经系统→下丘脑→垂体前叶→靶腺→终末靶组织","B. 环境→垂体前叶→下丘脑→中枢神经系统→靶腺","C. 下丘脑→环境→中枢神经系统→垂体前叶→靶腺","D. 靶腺→垂体前叶→下丘脑→中枢神经系统→环境"],"oe":["A正确：顺序与环境启动、逐级向下的调控方向一致。","B错误：下丘脑应在垂体前叶之前。","C错误：环境刺激应位于最上游。","D错误：该顺序把调控方向完全颠倒。"]},"tableTitle":"四级级联逐级看","table":[["层级","部位","分泌/信号","例子"],["1","环境/CNS","神经信号","应激、光照"],["2","下丘脑","释放激素","TRH、CRH、GnRH"],["3","腺垂体","促激素","TSH、ACTH、LH/FSH"],["4","靶腺","靶腺激素","T3/T4、皮质醇、性激素"],["旁路","神经垂体","直接释放","ADH、催产素"]]},{"i":13,"sec":"老师PPT逐页","title":"激素的化学本质三大类","notes":"按化学本质激素分为含氮激素、类固醇激素和脂肪酸衍生物激素。含氮激素包括肽和蛋白质激素以及氨基酸衍生物激素，是数量最多的一类。类固醇激素以胆固醇为骨架，脂肪酸衍生物则来自花生四烯酸等脂肪酸。","points":["含氮激素：肽/蛋白质与氨基酸衍生物","类固醇激素以胆固醇为骨架","脂肪酸衍生物来自花生四烯酸","含氮激素种类最多"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full14.jpg","imageExplain":"三类并列的框架图应把含氮激素再细分为肽与蛋白质、氨基酸衍生物两支，并与类固醇、脂肪酸衍生物并列比较。","check":{"kind":"mcq","id":"bc14_check_13","q":"按化学本质的三大类划分，含氮激素包括哪些？","a":"A","e":"含氮激素包括肽和蛋白质激素以及氨基酸衍生物激素，是数量最多的一类。","src":"本页自测","o":["A. 肽和蛋白质激素以及氨基酸衍生物激素","B. 类固醇激素和脂肪酸衍生物激素","C. 仅肽和蛋白质激素","D. 仅类固醇激素"],"oe":["A正确：两类均属含氮激素且为本章表述。","B错误：类固醇和脂肪酸衍生物不属于含氮激素。","C错误：含氮激素还包括氨基酸衍生物激素。","D错误：类固醇激素不是含氮激素。"]}},{"i":14,"sec":"老师PPT逐页","title":"激素合成的两条途径","notes":"激素合成有两条基本途径：其一是由激素的结构基因经转录与翻译生成多肽或蛋白质激素；其二是通过细胞内已有的酶系催化前体物质合成，如类固醇激素和氨基酸衍生物激素。前者依赖基因表达，后者依赖酶促反应。","points":["基因转录翻译途径生成多肽/蛋白质激素","酶系催化途径生成类固醇等激素","两条途径分别对应不同化学本质","合成部位和调控方式也不同"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full15.jpg","imageExplain":"合成途径图应把“结构基因→转录→翻译”和“前体物→酶系催化”两条路线并列，分别指向多肽激素与类固醇/氨基酸衍生物激素。","check":{"kind":"mcq","id":"bc14_check_14","q":"类固醇激素和氨基酸衍生物激素的合成主要依赖哪条途径？","a":"A","e":"类固醇激素和氨基酸衍生物激素主要通过细胞内酶系催化前体物质合成。","src":"本页自测","o":["A. 由细胞内已有酶系催化前体物质合成","B. 由结构基因经转录和翻译直接生成","C. 在核糖体上组装多肽链","D. 经高尔基体加工分泌囊泡前体"],"oe":["A正确：这是酶促合成途径，适用于类固醇和氨基酸衍生物激素。","B错误：基因转录翻译途径主要生成多肽/蛋白质激素。","C错误：核糖体组装多肽属于蛋白质激素合成。","D错误：高尔基体加工囊泡前体是肽类激素的加工储存过程。"]}},{"i":15,"sec":"老师PPT逐页","title":"多肽激素的合成与囊泡储存","notes":"多肽激素由结构基因转录、翻译生成前体，在粗面内质网和高尔基体中加工、包装成分泌囊泡储存。需要时囊泡与细胞膜融合，以胞吐方式释放激素。储存形式便于快速应答并保护激素不被提前降解。","points":["多肽激素由结构基因编码","在内质网和高尔基体加工包装","储存于分泌囊泡中","经胞吐释放"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full16.jpg","imageExplain":"分泌细胞示意图应沿“核内基因→粗面内质网→高尔基体→分泌囊泡→胞吐”追踪多肽激素的合成与释放路线。","check":{"kind":"mcq","id":"bc14_check_15","q":"多肽激素合成后通常储存于何处，并以何种方式释放？","a":"A","e":"多肽激素在内质网和高尔基体加工后包装成分泌囊泡，需要时经胞吐释放。","src":"本页自测","o":["A. 储存于分泌囊泡，经胞吐释放","B. 储存于细胞核，经核孔释放","C. 储存于线粒体，经扩散释放","D. 储存于溶酶体，经吞噬释放"],"oe":["A正确：囊泡储存和胞吐释放符合本章描述。","B错误：激素不储存于细胞核经核孔释放。","C错误：线粒体不是多肽激素的储存释放部位。","D错误：溶酶体不是分泌囊泡，吞噬也不是激素释放方式。"]}},{"i":16,"sec":"老师PPT逐页","title":"胰岛素前体的加工成熟","notes":"胰岛素先在核糖体上合成前胰岛素原，切除信号肽后成为胰岛素原。胰岛素原再切除中间的C肽，形成由A链和B链组成的成熟胰岛素，两条链之间以二硫键相连。C肽被切除后与胰岛素共同分泌，可作为胰岛B细胞功能的指标。","points":["前胰岛素原先切除信号肽","胰岛素原再切除C肽","成熟胰岛素含A链和B链","A、B链由二硫键连接"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full17.jpg","imageExplain":"加工流程图应从前往后依次标出前胰岛素原、胰岛素原、C肽切除和A/B链二硫键，注意信号肽与C肽是两段被切掉的部分。","check":{"kind":"mcq","id":"bc14_check_16","q":"胰岛素原转变为成熟胰岛素时，被切除的部分是？","a":"A","e":"前胰岛素原先切除信号肽成为胰岛素原，胰岛素原再切除中间C肽生成由A、B链组成的成熟胰岛素。","src":"本页自测","o":["A. 中间的C肽","B. N端信号肽","C. A链","D. B链"],"oe":["A正确：C肽是胰岛素原成熟时被切除的连接片段。","B错误：信号肽在更早的前胰岛素原阶段已被切除。","C错误：A链保留在成熟胰岛素中。","D错误：B链保留在成熟胰岛素中。"]}},{"i":17,"sec":"老师PPT逐页","title":"氨基酸衍生物激素","notes":"氨基酸衍生物激素由单个氨基酸经酶促修饰生成。酪氨酸衍生物包括儿茶酚胺类（多巴、多巴胺、去甲肾上腺素、肾上腺素）和甲状腺激素；色氨酸衍生物则包括5-羟色胺和褪黑素。这类激素分子小，但生理作用很强。","points":["由单一氨基酸修饰而来","酪氨酸衍生儿茶酚胺和甲状腺激素","色氨酸衍生5-羟色胺与褪黑素","分子小、作用强"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full18.jpg","imageExplain":"生物合成分支图以酪氨酸为起点，应看到向多巴胺/去甲肾上腺素/肾上腺素和向甲状腺激素两条支路，并可标出色氨酸支路。","check":{"kind":"mcq","id":"bc14_check_17","q":"由色氨酸衍生而来的激素是？","a":"A","e":"色氨酸衍生物包括5-羟色胺和褪黑素；酪氨酸衍生儿茶酚胺和甲状腺激素。","src":"本页自测","o":["A. 5-羟色胺和褪黑素","B. 肾上腺素和去甲肾上腺素","C. 甲状腺素和三碘甲腺原氨酸","D. 多巴和多巴胺"],"oe":["A正确：二者为色氨酸衍生物。","B错误：肾上腺素和去甲肾上腺素是酪氨酸衍生的儿茶酚胺。","C错误：甲状腺素和T3也是酪氨酸衍生物。","D错误：多巴和多巴胺属于酪氨酸衍生的儿茶酚胺途径。"]}},{"i":18,"sec":"老师PPT逐页","title":"甲状腺激素在甲状腺球蛋白上合成","notes":"甲状腺激素并非游离合成，而是在甲状腺球蛋白分子上进行。甲状腺球蛋白中的酪氨酸残基被碘化生成一碘酪氨酸和二碘酪氨酸，再经偶联形成T4（甲状腺素）和T3（三碘甲状腺原氨酸），储存于滤泡胶质中。需要时经胞吞和蛋白酶水解释放入血。","points":["合成场所是甲状腺球蛋白","酪氨酸残基碘化成MIT和DIT","MIT/DIT偶联生成T4（甲状腺素）与T3（三碘甲状腺原氨酸）","激素储存于滤泡胶质"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full19.jpg","imageExplain":"甲状腺滤泡示意图应标出滤泡腔内的胶质（甲状腺球蛋白），并显示酪氨酸残基碘化、偶联成T4（甲状腺素）/T3（三碘甲状腺原氨酸）后储存于胶质的过程。","check":{"kind":"mcq","id":"bc14_check_18","q":"甲状腺激素合成的场所是？","a":"A","e":"甲状腺激素在甲状腺球蛋白分子上进行，酪氨酸残基碘化生成MIT和DIT，再偶联成T4（甲状腺素）和T3（三碘甲状腺原氨酸）。","src":"本页自测","o":["A. 甲状腺球蛋白分子上的酪氨酸残基","B. 游离酪氨酸在血液中直接碘化","C. 甲状腺滤泡旁细胞的线粒体","D. 肝脏中的白蛋白分子"],"oe":["A正确：甲状腺球蛋白是激素合成的载体和场所。","B错误：并非游离酪氨酸在血液中直接碘化。","C错误：滤泡旁细胞分泌降钙素，不合成甲状腺激素。","D错误：白蛋白不是甲状腺激素合成场所。"]}},{"i":19,"sec":"老师PPT逐页","title":"类固醇激素的生物合成","notes":"类固醇激素都以胆固醇为共同前体，先转变为孕烯醇酮，再生成孕酮这一中心中间体。由孕酮分出三支：一支生成皮质醇等糖皮质激素，一支生成醛固酮等盐皮质激素，还有一支经睾酮生成雌二醇等性激素。不同腺体表达不同酶系，因而产物不同。","points":["胆固醇是共同前体","孕烯醇酮和孕酮是中心中间体","皮质醇、醛固酮为肾上腺皮质激素","睾酮、雌二醇为性激素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full20.jpg","imageExplain":"合成路线图以胆固醇为顶端，经孕烯醇酮、孕酮后分为糖皮质激素、盐皮质激素和性激素三支，注意各支的关键酶和终产物。","check":{"kind":"mcq","id":"bc14_check_19","q":"所有类固醇激素生物合成的共同前体是？","a":"A","e":"类固醇激素都以胆固醇为共同前体，经孕烯醇酮、孕酮再分化为各类激素。","src":"本页自测","o":["A. 胆固醇","B. 花生四烯酸","C. 酪氨酸","D. 葡萄糖"],"oe":["A正确：胆固醇是类固醇激素的共同前体。","B错误：花生四烯酸是脂肪酸衍生物激素的前体。","C错误：酪氨酸是氨基酸衍生物激素的前体。","D错误：葡萄糖不是类固醇激素的直接共同前体。"]}},{"i":20,"sec":"老师PPT逐页","title":"脂肪酸衍生物激素","notes":"脂肪酸衍生物激素主要包括前列腺素类、血栓烷类和白三烯类，多由花生四烯酸经环加氧酶或脂加氧酶途径生成。它们多在局部产生并作用于邻近细胞，属于旁分泌或自分泌信号分子。这类物质半衰期短，作用局部而迅速。","points":["前列腺素、血栓烷、白三烯三类","前体多为花生四烯酸","经环加氧酶或脂加氧酶生成","多为局部作用的旁分泌激素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full21.jpg","imageExplain":"花生四烯酸代谢图应分出环加氧酶途径（前列腺素、血栓烷）和脂加氧酶途径（白三烯）两大分支，并标出各类终产物。","check":{"kind":"mcq","id":"bc14_check_20","q":"前列腺素类、血栓烷类和白三烯类激素的共同前体多为？","a":"A","e":"脂肪酸衍生物激素多由花生四烯酸经环加氧酶或脂加氧酶途径生成。","src":"本页自测","o":["A. 花生四烯酸","B. 胆固醇","C. 酪氨酸","D. 甲硫氨酸"],"oe":["A正确：花生四烯酸是这类脂肪酸衍生物的主要前体。","B错误：胆固醇是类固醇激素前体。","C错误：酪氨酸是儿茶酚胺和甲状腺激素前体。","D错误：甲硫氨酸主要提供甲基，不是这类激素的前体。"]}},{"i":21,"sec":"老师PPT逐页","title":"重要激素各论导引","notes":"进入各论后先讲氨基酸衍生物激素，以甲状腺激素和肾上腺素为代表。随后讲多肽与蛋白质激素，重点为垂体前叶、中叶和后叶激素以及下丘脑激素。最后简要提及胰岛、甲状旁腺等分泌的激素。","points":["先讲氨基酸衍生物激素","甲状腺激素与肾上腺素为重点","再讲垂体与下丘脑多肽激素","最后涉及胰岛和甲状旁腺"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full22.jpg","imageExplain":"各论导引页应看到按化学本质排列的讲授顺序：氨基酸衍生物→多肽/蛋白质→其他，便于建立后续内容的框架。","check":{"kind":"mcq","id":"bc14_check_21","q":"进入激素各论后，本章首先讲述的是哪一类激素？","a":"A","e":"各论先讲氨基酸衍生物激素，重点为甲状腺激素和肾上腺素。","src":"本页自测","o":["A. 氨基酸衍生物激素，以甲状腺激素和肾上腺素为代表","B. 类固醇激素，以醛固酮和皮质醇为代表","C. 脂肪酸衍生物激素，以前列腺素为代表","D. 垂体后叶激素，以催产素为代表"],"oe":["A正确：顺序和代表激素均符合导引页。","B错误：类固醇激素不是各论最先讲述的内容。","C错误：脂肪酸衍生物激素也不是最先讲述的内容。","D错误：垂体后叶激素安排在垂体部分之后。"]}},{"i":22,"sec":"老师PPT逐页","title":"甲状腺激素T4（甲状腺素）与T3（三碘甲状腺原氨酸）","notes":"甲状腺分泌甲状腺素（T4）和三碘甲腺原氨酸（T3）两种激素。T4是主要分泌形式，T3含量较少但生物活性更高。外周组织中T4可脱碘转变为T3，因此T3常被视为主要的活性形式。","points":["甲状腺分泌T4（甲状腺素）和T3（三碘甲状腺原氨酸）","T4（甲状腺素）为主要分泌形式","T3（三碘甲状腺原氨酸）活性高于T4（甲状腺素）","T4（甲状腺素）可在外周脱碘生成T3（三碘甲状腺原氨酸）"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full23.jpg","imageExplain":"甲状腺激素页应区分T4（甲状腺素）与T3（三碘甲状腺原氨酸）的名称、碘原子数和活性强弱，注意T4是储存与运输的主要形式而T3是高效活性形式。","check":{"kind":"mcq","id":"bc14_check_22","q":"关于甲状腺激素T4（甲状腺素）与T3（三碘甲状腺原氨酸），下列哪项正确？","a":"A","e":"甲状腺主要分泌T4（甲状腺素），T3（三碘甲状腺原氨酸）含量较少但活性更高，T4可在外周脱碘生成T3。","src":"本页自测","o":["A. T4是主要分泌形式，T3生物活性更高","B. T3是主要分泌形式，T4活性更高","C. T4和T3活性完全相同","D. T3不能由T4在外周转变而来"],"oe":["A正确：分泌形式与活性高低的表述均正确。","B错误：主要分泌形式是T4，活性更高的是T3。","C错误：二者活性不同，T3更高。","D错误：T4在外周脱碘可生成T3。"]}},{"i":23,"sec":"老师PPT逐页","title":"甲状腺激素的化学结构","notes":"T4（甲状腺素）即3,5,3′,5′-四碘甲腺原氨酸，T3（三碘甲状腺原氨酸）即3,5,3′-三碘甲腺原氨酸。两者都由两个碘化酪氨酸残基通过二苯醚键连接而成，骨架相同，差别只在碘原子数目和位置。碘是甲状腺激素发挥功能不可缺少的组成元素。","points":["T4（甲状腺素）含四个碘、T3（三碘甲状腺原氨酸）含三个碘","骨架为两个酪氨酸经醚键相连","差别在碘原子数目与位置","碘是激素结构的必需元素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full24.jpg","imageExplain":"结构式应数清两个苯环上的碘原子：T4（甲状腺素）在3、5、3′、5′位各有一个碘，T3（三碘甲状腺原氨酸）缺少5′位碘，并注意连接两环的醚键和丙氨酸侧链。","check":{"kind":"mcq","id":"bc14_check_23","q":"T4（甲状腺素）分子中碘原子的数目是？","a":"A","e":"T4（甲状腺素）即3,5,3′,5′-四碘甲腺原氨酸，含四个碘；T3（三碘甲状腺原氨酸）含三个碘。","src":"本页自测","o":["A. 4个","B. 3个","C. 2个","D. 1个"],"oe":["A正确：四碘甲腺原氨酸含4个碘。","B错误：3个碘对应T3。","C错误：2个碘不是T4的碘数。","D错误：1个碘不是T4的碘数。"]}},{"i":24,"sec":"老师PPT逐页","title":"甲状腺激素的生物合成","notes":"甲状腺球蛋白上的酪氨酸残基在活性碘作用下碘化，生成一碘酪氨酸和二碘酪氨酸。两分子二碘酪氨酸偶联形成T4（甲状腺素），一碘酪氨酸与二碘酪氨酸偶联形成T3（三碘甲状腺原氨酸）。已生成的T4在外周脱碘也可产生T3。","points":["酪氨酸碘化生成MIT和DIT","两分子DIT偶联成T4（甲状腺素）","MIT与DIT偶联成T3（三碘甲状腺原氨酸）","T4（甲状腺素）脱碘可生成T3（三碘甲状腺原氨酸）"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full25.jpg","imageExplain":"合成反应图应从酪氨酸出发，经活性碘生成MIT/DIT，再显示DIT+DIT→T4（甲状腺素）与MIT+DIT→T3（三碘甲状腺原氨酸）两种偶联方式。","check":{"kind":"mcq","id":"bc14_check_24","q":"甲状腺激素合成中，两分子二碘酪氨酸（DIT）偶联生成？","a":"A","e":"两分子DIT偶联形成T4（甲状腺素），MIT与DIT偶联形成T3（三碘甲状腺原氨酸）。","src":"本页自测","o":["A. T4","B. T3","C. MIT","D. 甲状腺球蛋白"],"oe":["A正确：DIT+DIT偶联生成T4。","B错误：T3由MIT与DIT偶联生成。","C错误：MIT是一碘酪氨酸，是碘化产物而非DIT偶联产物。","D错误：甲状腺球蛋白是合成载体，不是偶联产物。"]}},{"i":25,"sec":"老师PPT逐页","title":"甲状腺激素的生理功能","notes":"甲状腺激素促进糖、脂肪和蛋白质代谢，提高基础代谢率，并增加耗氧量和产热量。它还维持机体正常生长发育，尤其对神经系统和骨骼发育至关重要。甲状腺功能异常会同时影响代谢和生长。","points":["促进物质代谢、提高代谢率","增加耗氧量和产热量","维持正常生长发育","对神经和骨骼发育尤为重要"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full26.jpg","imageExplain":"功能页应把“代谢率/产热”和“生长发育”两条主线分开看，注意甲状腺激素既是代谢调节者也是发育必需激素。","check":{"kind":"mcq","id":"bc14_check_25","q":"下列哪项不属于甲状腺激素的生理功能？","a":"A","e":"甲状腺激素提高基础代谢率、增加耗氧量和产热量，而不是降低。","src":"本页自测","o":["A. 降低基础代谢率和耗氧量","B. 促进糖、脂肪和蛋白质代谢","C. 维持神经系统和骨骼的正常发育","D. 增加产热量"],"oe":["A正确：该说法与甲状腺激素作用相反，故为应选项。","B错误：促进物质代谢确是其功能。","C错误：维持神经和骨骼发育确是其重要功能。","D错误：增加产热量确是其功能。"]}},{"i":26,"sec":"老师PPT逐页","title":"肾上腺素与去甲肾上腺素的结构","notes":"肾上腺分为髓质和皮质两部分，髓质分泌肾上腺素和少量去甲肾上腺素。去甲肾上腺素主要由交感神经末梢分泌。两者都是儿茶酚胺，结构差别仅在于肾上腺素氨基上多一个甲基。","points":["肾上腺分髓质与皮质","髓质分泌肾上腺素和少量去甲肾上腺素","去甲肾上腺素主要来自交感神经末梢","二者差别在氨基是否甲基化"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full27.jpg","imageExplain":"结构式应并排比较肾上腺素与去甲肾上腺素，重点看侧链氨基上是否有甲基，其余儿茶酚骨架完全相同。","check":{"kind":"mcq","id":"bc14_check_26","q":"肾上腺素与去甲肾上腺素在结构上的主要差别是？","a":"A","e":"两者都是儿茶酚胺，差别仅在于肾上腺素氨基上多一个甲基。","src":"本页自测","o":["A. 肾上腺素氨基上多一个甲基","B. 去甲肾上腺素氨基上多一个甲基","C. 二者环状结构完全不同","D. 二者相差一个羧基"],"oe":["A正确：肾上腺素为甲基化形式，去甲肾上腺素没有该甲基。","B错误：方向说反，去甲肾上腺素不含该甲基。","C错误：二者骨架相同，并非环状结构完全不同。","D错误：差别是氨基甲基化，不是羧基。"]}},{"i":27,"sec":"老师PPT逐页","title":"肾上腺素的生物合成","notes":"肾上腺素由酪氨酸经多步酶促反应合成：酪氨酸羟化生成多巴，脱羧生成多巴胺，再羟化生成去甲肾上腺素。去甲肾上腺素最后由甲基转移酶催化，接受由甲硫氨酸供给的甲基生成肾上腺素。","points":["起始原料为酪氨酸","经多巴、多巴胺到去甲肾上腺素","最后一步为甲基化","甲基由甲硫氨酸（SAM）供给"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full28.jpg","imageExplain":"合成路线图应从酪氨酸开始，依次标出多巴、多巴胺、去甲肾上腺素，最后一步标出甲基转移和由Met供给的甲基。","check":{"kind":"mcq","id":"bc14_check_27","q":"肾上腺素合成的最后一步甲基化反应中，甲基的供体是？","a":"A","e":"去甲肾上腺素最后由甲基转移酶催化，甲基由甲硫氨酸供给（SAM）。","src":"本页自测","o":["A. 甲硫氨酸（经SAM）","B. 胆固醇","C. 花生四烯酸","D. 葡萄糖"],"oe":["A正确：甲硫氨酸经SAM提供甲基。","B错误：胆固醇不是该甲基化反应的甲基供体。","C错误：花生四烯酸与甲基供体无关。","D错误：葡萄糖不提供该反应所需甲基。"]}},{"i":28,"sec":"老师PPT逐页","title":"肾上腺素的糖代谢作用","notes":"肾上腺素主要促进肝糖原分解，使血糖升高；同时也促进肌糖原分解，使乳酸增加。去甲肾上腺素也有类似作用，但作用较弱。这体现了肾上腺素在应激时快速动员能源的作用。","points":["促进肝糖原分解、升高血糖","促进肌糖原分解、增加乳酸","去甲肾上腺素作用较弱","有利于应激时快速供能"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full29.jpg","imageExplain":"代谢作用图应从肝糖原指向血糖、从肌糖原指向乳酸两条箭头，比较肾上腺素与去甲肾上腺素作用强弱。","check":{"kind":"mcq","id":"bc14_check_28","q":"肾上腺素对糖代谢的主要作用是？","a":"A","e":"肾上腺素主要促进肝糖原分解升高血糖，也促进肌糖原分解使乳酸增加。","src":"本页自测","o":["A. 促进肝糖原分解，使血糖升高","B. 促进肝糖原合成，使血糖降低","C. 抑制肌糖原分解，减少乳酸","D. 促进葡萄糖转化为脂肪储存"],"oe":["A正确：升血糖是肾上腺素糖代谢作用的核心。","B错误：它促进分解而非合成，作用是升血糖。","C错误：它促进肌糖原分解，使乳酸增加。","D错误：这不是其急性应激时的主要糖代谢作用。"]}},{"i":29,"sec":"老师PPT逐页","title":"肾上腺素的心血管作用","notes":"肾上腺素使血管收缩，并刺激心脏使心肌收缩力增强、心率加快，从而使血压升高。它对心脏的作用较大，临床上被用作升压药和抗休克药物。应激时血流加快，血氧和血糖升高，符合“战斗或逃跑”的生理需要。","points":["收缩血管、增强心肌收缩力","加快心率、升高血压","对心脏作用大，可作升压抗休克药","应激时加快血流、提高血氧血糖"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full30.jpg","imageExplain":"心血管效应图应标出血管收缩、心肌收缩力增强和心率加快三项，并注明最终结果是血压升高，注意其对心脏作用突出。","check":{"kind":"mcq","id":"bc14_check_29","q":"关于肾上腺素的心血管作用，下列哪项正确？","a":"A","e":"肾上腺素收缩血管，增强心肌收缩力、加快心率，使血压升高，临床可作升压抗休克药。","src":"本页自测","o":["A. 收缩血管、增强心肌收缩力、加快心率并使血压升高","B. 舒张血管、减弱心肌收缩力并降低血压","C. 只作用于血管，对心脏无影响","D. 主要作用是减慢心率"],"oe":["A正确：完整概括其心血管效应。","B错误：与肾上腺素实际作用相反。","C错误：它对心脏作用很大，并非只作用于血管。","D错误：它加快而非减慢心率。"]}},{"i":30,"sec":"老师PPT逐页","title":"肾上腺素与去甲肾上腺素比较","notes":"肾上腺素对心脏作用大，生理上可作强心剂使心跳加速，代谢上强烈升高血糖。去甲肾上腺素对血管作用大，可作加压剂使血管收缩，其升糖作用较弱，约为肾上腺素的二十分之一。两者作用侧重明显不同。","points":["肾上腺素强心、升糖作用强","去甲肾上腺素缩血管、加压作用强","二者升糖能力相差约20倍","临床应用侧重不同"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full31.jpg","imageExplain":"对比表应横向比较两种激素在“生理作用”和“代谢作用”两栏的差异，重点记住肾上腺素偏心脏与血糖、去甲肾上腺素偏血管与血压。","check":{"kind":"mcq","id":"bc14_check_30","q":"去甲肾上腺素的升糖作用约为肾上腺素的多少？","a":"A","e":"去甲肾上腺素升糖作用较弱，约为肾上腺素的二十分之一。","src":"本页自测","o":["A. 约1/20","B. 约1/2","C. 约2倍","D. 约20倍"],"oe":["A正确：本章明确给出约1/20。","B错误：1/2高估了其升糖能力。","C错误：去甲肾上腺素升糖作用弱于肾上腺素。","D错误：方向完全相反。"]}},{"i":31,"sec":"老师PPT逐页","title":"多肽与蛋白质激素概述","notes":"多肽和蛋白质激素包括垂体（腺垂体和神经垂体）、下丘脑、胰腺、甲状腺、甲状旁腺、胃肠和胸腺等分泌的激素。这类激素种类多、作用广泛，是激素中数量最大的一类。它们多通过膜受体和第二信使发挥效应。","points":["来源广泛：垂体、下丘脑、胰腺等","是数量最多的一类激素","多经膜受体和第二信使起作用","包括促激素和代谢调节激素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full32.jpg","imageExplain":"概述图应以垂体为中心向外辐射，标出下丘脑、胰腺、甲状腺、甲状旁腺、胃肠和胸腺等分泌来源。","check":{"kind":"mcq","id":"bc14_check_31","q":"多肽和蛋白质激素发挥效应时多采用的方式是？","a":"A","e":"多肽和蛋白质激素多通过膜受体和第二信使发挥效应。","src":"本页自测","o":["A. 与膜受体结合并通过第二信使传递信号","B. 直接穿过细胞膜与核受体结合","C. 在细胞内与DNA直接结合","D. 不需要受体即可进入细胞核"],"oe":["A正确：这是水溶性肽类激素的典型作用方式。","B错误：直接穿过膜与核受体结合主要是脂溶性激素。","C错误：肽类激素一般不在细胞内直接结合DNA。","D错误：激素作用需要受体，不能无受体进入核内。"]}},{"i":32,"sec":"老师PPT逐页","title":"垂体前叶激素的七种成分","notes":"垂体前叶分泌七种主要激素：生长激素GH（生长激素）、促甲状腺素TSH（促甲状腺激素）、促黄体生成素LH（黄体生成素）、促卵泡激素FSH（促卵泡激素）、催乳激素LTH（催乳激素）、促肾上腺皮质激素ACTH（促肾上腺皮质激素）和脂肪酸释放激素LPH。其中TSH、LH、FSH、ACTH属于促激素，作用于外周靶腺。GH和LTH直接作用于组织。","points":["GH（生长激素）、TSH（促甲状腺激素）、LH（黄体生成素）、FSH（促卵泡激素）、LTH（催乳激素）、ACTH（促肾上腺皮质激素）、LPH七种","TSH（促甲状腺激素）、LH（黄体生成素）、FSH（促卵泡激素）、ACTH（促肾上腺皮质激素）为促激素","GH（生长激素）和LTH（催乳激素）直接作用于组织","垂体前叶是内分泌调控的枢纽"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full33.jpg","imageExplain":"垂体前叶激素清单应把七种激素与各自靶腺或靶组织对应起来，注意哪些是促激素、哪些直接作用于组织。","check":{"kind":"mcq","id":"bc14_check_32","q":"下列垂体前叶激素中，不属于促激素的是？","a":"A","e":"TSH（促甲状腺激素）、LH（黄体生成素）、FSH（促卵泡激素）、ACTH（促肾上腺皮质激素）为促激素，GH（生长激素）直接作用于组织，不是促激素。","src":"本页自测","o":["A. 生长激素GH","B. 促甲状腺素TSH","C. 促黄体生成素LH","D. 促肾上腺皮质激素ACTH"],"oe":["A正确：GH直接作用于组织，不属促激素。","B错误：TSH是促激素，靶腺为甲状腺。","C错误：LH是促激素，属促性腺激素。","D错误：ACTH是促激素，靶腺为肾上腺皮质。"]}},{"i":33,"sec":"老师PPT逐页","title":"生长激素与催乳激素的本质","notes":"生长激素GH（生长激素）和催乳激素LTH（催乳激素）的化学本质都是蛋白质。GH为单链多肽，LTH也是单链蛋白质，二者在一段氨基酸序列上具有同源性。这种结构相似提示它们可能由同一祖先基因演化而来。","points":["GH（生长激素）与LTH（催乳激素）均为蛋白质","二者均为单链结构","存在一段同源氨基酸序列","可能由共同祖先基因演化"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full34.jpg","imageExplain":"结构比较图应将GH（生长激素）与LTH（催乳激素）两条单链并排，标出同源序列区段，突出二者化学本质同为蛋白质。","check":{"kind":"mcq","id":"bc14_check_33","q":"生长激素与催乳激素的化学本质是？","a":"A","e":"GH（生长激素）和LTH（催乳激素）均为蛋白质，且都是单链结构并存在一段同源序列。","src":"本页自测","o":["A. 二者均为蛋白质","B. 二者均为类固醇","C. 二者均为糖蛋白","D. 生长激素为类固醇，催乳激素为肽"],"oe":["A正确：二者化学本质都是蛋白质。","B错误：它们不是类固醇激素。","C错误：糖蛋白类促激素指TSH、FSH、LH，不包括GH和LTH。","D错误：GH也不是类固醇。"]}},{"i":34,"sec":"老师PPT逐页","title":"生长激素的功能与疾病","notes":"生长激素促进蛋白质和RNA的生成，调节糖和脂肪代谢，并刺激软骨生长，其中刺激软骨生长是最主要的作用。幼年时GH（生长激素）过多引起巨人症，成年后过多引起肢端肥大症；幼年缺乏则导致侏儒症。GH的促生长作用部分通过生长介素实现。","points":["促进蛋白质和RNA合成","调节糖脂代谢","刺激软骨生长为最主要作用","过多致巨人症/肢端肥大，缺乏致侏儒"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full35.jpg","imageExplain":"功能页应把GH（生长激素）的三项作用与对应的病理状态联系起来：幼年过多→巨人症、成年过多→肢端肥大、幼年缺乏→侏儒。","check":{"kind":"mcq","id":"bc14_check_34","q":"幼年时期生长激素分泌过多会导致？","a":"A","e":"幼年GH（生长激素）过多引起巨人症，成年后过多引起肢端肥大症，幼年缺乏导致侏儒症。","src":"本页自测","o":["A. 巨人症","B. 肢端肥大症","C. 侏儒症","D. 呆小症"],"oe":["A正确：幼年过多对应巨人症。","B错误：肢端肥大症发生于成年后GH过多。","C错误：侏儒症由幼年GH缺乏引起。","D错误：呆小症与甲状腺激素缺乏有关。"]}},{"i":35,"sec":"老师PPT逐页","title":"催乳激素的功能","notes":"催乳激素LTH（催乳激素）是约200个氨基酸组成的单链蛋白质，其序列中有一段与生长激素相似。它的主要功能是刺激乳腺分泌乳汁，并刺激黄体分泌孕酮。因此LTH既参与泌乳，也参与黄体功能的维持。","points":["单链蛋白约200个氨基酸","与GH（生长激素）存在序列相似性","刺激乳腺分泌乳汁","刺激黄体分泌孕酮"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full36.jpg","imageExplain":"LTH（催乳激素）页面应抓住两项靶作用：乳腺（泌乳）和黄体（分泌孕酮），并注意其与GH（生长激素）的序列同源关系。","check":{"kind":"mcq","id":"bc14_check_35","q":"下列哪项不属于催乳激素的功能？","a":"A","e":"LTH（催乳激素）主要刺激乳腺泌乳并刺激黄体分泌孕酮，不促进精子生成。","src":"本页自测","o":["A. 促进精子生成","B. 刺激乳腺分泌乳汁","C. 刺激黄体分泌孕酮","D. 参与黄体功能的维持"],"oe":["A正确：促进精子生成是雄激素的作用，不是催乳激素功能。","B错误：刺激乳腺分泌乳汁确是LTH功能。","C错误：刺激黄体分泌孕酮确是LTH功能。","D错误：维持黄体功能与LTH有关。"]}},{"i":36,"sec":"老师PPT逐页","title":"糖蛋白类促激素","notes":"促甲状腺素TSH（促甲状腺激素）、促卵泡激素FSH（促卵泡激素）和促黄体生成素LH（黄体生成素）的化学本质都是糖蛋白。它们属于促激素，其中FSH和LH又称促性腺激素。糖蛋白激素通常由α和β两个亚基组成，β亚基决定特异性。","points":["TSH（促甲状腺激素）、FSH（促卵泡激素）、LH（黄体生成素）均为糖蛋白","FSH（促卵泡激素）和LH（黄体生成素）为促性腺激素","糖蛋白激素多含α、β两个亚基","β亚基决定激素特异性"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full37.jpg","imageExplain":"糖蛋白激素图应把TSH（促甲状腺激素）、FSH（促卵泡激素）、LH（黄体生成素）并列，标出共同的α亚基和各自不同的β亚基，说明特异性由β亚基决定。","check":{"kind":"mcq","id":"bc14_check_36","q":"糖蛋白类促激素中，决定激素特异性的是？","a":"A","e":"TSH（促甲状腺激素）、FSH（促卵泡激素）、LH（黄体生成素）为糖蛋白，通常由α、β两个亚基组成，β亚基决定特异性。","src":"本页自测","o":["A. β亚基","B. α亚基","C. 糖链的数量","D. 胆固醇骨架"],"oe":["A正确：β亚基决定糖蛋白激素的特异性。","B错误：α亚基在同类激素中较保守，不决定特异性。","C错误：糖链不是决定特异性的主要因素。","D错误：糖蛋白激素不含胆固醇骨架。"]}},{"i":37,"sec":"老师PPT逐页","title":"促甲状腺激素的功能","notes":"促甲状腺激素TSH（促甲状腺激素）的靶腺是甲状腺，它促使甲状腺发育并分泌甲状腺激素。通过提高甲状腺激素水平，TSH间接影响全身代谢。TSH分泌受下丘脑TRH（促甲状腺激素释放激素）和血中甲状腺激素的负反馈调节。","points":["靶腺为甲状腺","促进甲状腺发育","促进甲状腺激素分泌","间接影响全身代谢"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full38.jpg","imageExplain":"TSH（促甲状腺激素）作用图应显示垂体→TSH→甲状腺→T4（甲状腺素）/T3（三碘甲状腺原氨酸）→全身代谢这条纵向通路，并标出血中甲状腺激素对垂体的负反馈。","check":{"kind":"mcq","id":"bc14_check_37","q":"促甲状腺激素（TSH）的靶腺是？","a":"A","e":"TSH（促甲状腺激素）靶腺为甲状腺，促进甲状腺发育和甲状腺激素分泌。","src":"本页自测","o":["A. 甲状腺","B. 肾上腺皮质","C. 性腺","D. 胰岛"],"oe":["A正确：TSH作用于甲状腺。","B错误：肾上腺皮质是ACTH的靶腺。","C错误：性腺是FSH和LH的靶腺。","D错误：胰岛不是TSH的靶腺。"]}},{"i":38,"sec":"老师PPT逐页","title":"促肾上腺皮质激素ACTH（促肾上腺皮质激素）","notes":"促肾上腺皮质激素ACTH（促肾上腺皮质激素）是由39个氨基酸组成的多肽，不同物种间存在种属差异。它促使肾上腺皮质发育，并促使肾上腺皮质分泌糖皮质激素。ACTH的分泌受下丘脑CRH（促肾上腺皮质激素释放激素）调控，并受皮质醇负反馈抑制。","points":["ACTH（促肾上腺皮质激素）为39肽","存在种属差异","促进肾上腺皮质发育","促进糖皮质激素分泌"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full39.jpg","imageExplain":"ACTH（促肾上腺皮质激素）轴图应从下丘脑CRH（促肾上腺皮质激素释放激素）→垂体ACTH→肾上腺皮质→皮质醇，并画出皮质醇对下丘脑和垂体的负反馈箭头。","check":{"kind":"mcq","id":"bc14_check_38","q":"促肾上腺皮质激素（ACTH）由多少个氨基酸组成？","a":"A","e":"ACTH（促肾上腺皮质激素）是由39个氨基酸组成的多肽，存在种属差异。","src":"本页自测","o":["A. 39个","B. 29个","C. 32个","D. 13个"],"oe":["A正确：ACTH为39肽。","B错误：29肽是胰高血糖素。","C错误：32肽是降钙素。","D错误：13肽是α-MSH。"]}},{"i":39,"sec":"老师PPT逐页","title":"脂肪酸释放激素LPH","notes":"脂肪酸释放激素包括β-LPH和γ-LPH，前者由91个氨基酸组成，后者由58个氨基酸组成，均为蛋白质。其主要功能是促使脂肪水解，释放出脂肪酸供机体利用。LPH与ACTH（促肾上腺皮质激素）等一样来源于阿黑皮素原前体。","points":["β-LPH为91肽、γ-LPH为58肽","二者均为蛋白质","促进脂肪水解、释放脂肪酸","与ACTH（促肾上腺皮质激素）同源于同一前体"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full40.jpg","imageExplain":"LPH页面应比较β-LPH与γ-LPH的肽链长度，并标出其作用于脂肪组织、促使甘油三酯水解为脂肪酸的功能箭头。","check":{"kind":"mcq","id":"bc14_check_39","q":"β-脂肪酸释放激素（β-LPH）由多少个氨基酸组成？","a":"A","e":"β-LPH由91个氨基酸组成，γ-LPH由58个氨基酸组成。","src":"本页自测","o":["A. 91个","B. 58个","C. 39个","D. 22个"],"oe":["A正确：β-LPH为91肽。","B错误：58肽对应γ-LPH。","C错误：39肽对应ACTH。","D错误：22肽对应人的β-MSH。"]}},{"i":40,"sec":"老师PPT逐页","title":"垂体中叶促黑激素MSH","notes":"垂体中叶分泌促黑激素MSH，分为α-MSH和β-MSH，均为肽类化合物。α-MSH是13肽，没有种属差异；β-MSH有种属差异，人的β-MSH为22肽，牛和羊的为18肽。MSH促使皮肤黑色素细胞分泌黑色素，使皮肤颜色加深。","points":["MSH分α-MSH和β-MSH","α-MSH为13肽、无种属差异","β-MSH有种属差异（人22肽）","促进黑色素分泌、使皮肤变深"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full41.jpg","imageExplain":"MSH结构图应并列α-MSH（13肽）与β-MSH，注意β-MSH在不同物种间长度不同，功能箭头指向皮肤黑色素细胞。","check":{"kind":"mcq","id":"bc14_check_40","q":"关于促黑激素MSH，下列哪项正确？","a":"A","e":"α-MSH是13肽、无种属差异；β-MSH有种属差异，人的β-MSH为22肽。","src":"本页自测","o":["A. α-MSH为13肽且无种属差异","B. α-MSH为22肽且有种属差异","C. β-MSH为13肽且无种属差异","D. 人的β-MSH为18肽"],"oe":["A正确：α-MSH的肽长与种属特性均正确。","B错误：α-MSH是13肽且无种属差异。","C错误：13肽且无种属差异描述的是α-MSH。","D错误：人的β-MSH为22肽，18肽是牛和羊的。"]}},{"i":41,"sec":"老师PPT逐页","title":"垂体后叶激素标题页","notes":"本页是“垂体后叶激素”小节标题，起承上启下作用。后叶激素由下丘脑合成、经神经垂体储存和释放，主要包括催产素和升压素。后续页面将介绍其结构和功能。","points":["垂体后叶激素小节标题","后叶激素由下丘脑合成","经神经垂体储存释放","主要为催产素和升压素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full42.jpg","imageExplain":"标题页本身无图，可留意小节编号“3”和“垂体后叶激素”字样，明确接下来讲神经垂体来源的两种九肽。","check":{"kind":"mcq","id":"bc14_check_41","q":"垂体后叶激素的合成部位是？","a":"A","e":"后叶激素由下丘脑合成，经神经垂体储存和释放。","src":"本页自测","o":["A. 下丘脑","B. 神经垂体","C. 腺垂体","D. 垂体柄"],"oe":["A正确：合成部位在下丘脑。","B错误：神经垂体只储存和释放，不合成。","C错误：腺垂体分泌前叶激素，不合成后叶激素。","D错误：垂体柄是连接结构，不是合成部位。"]}},{"i":42,"sec":"老师PPT逐页","title":"催产素与升压素的结构","notes":"催产素和升压素（加压素）都是含二硫键的九肽。两者肽链骨架相似，都形成含二硫键的二十元环。它们的差别仅在第3位和第8位氨基酸不同，这一微小差异导致二者功能侧重不同。","points":["二者均为含二硫键的九肽","骨架相似、形成二十元环","仅第3、8位氨基酸不同","结构微小差异决定功能差异"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full43.jpg","imageExplain":"结构图应将催产素与升压素的九肽序列上下对齐，重点圈出第3位和第8位不同的氨基酸以及形成环的二硫键。","check":{"kind":"mcq","id":"bc14_check_42","q":"催产素与升压素的结构差别在于？","a":"A","e":"二者均为含二硫键的九肽，骨架相似，仅第3位和第8位氨基酸不同。","src":"本页自测","o":["A. 仅第3位和第8位氨基酸不同","B. 肽链长度相差3个氨基酸","C. 一个有二硫键，一个没有","D. 一个为九肽，一个为八肽"],"oe":["A正确：差异位点就是第3、8位。","B错误：二者肽链长度相同，均为九肽。","C错误：二者都含二硫键并形成二十元环。","D错误：二者都是九肽，不是八肽。"]}},{"i":43,"sec":"老师PPT逐页","title":"催产素与升压素的功能","notes":"催产素使子宫平滑肌收缩，临床上用于催产，还可使乳腺平滑肌收缩以排出乳汁。升压素使毛细血管收缩、升高血压，并有减少排尿的抗利尿作用，因此又称抗利尿激素。二者结构相近但外周作用明显分工。","points":["催产素促子宫平滑肌收缩、用于催产","催产素促乳腺排乳","升压素收缩血管、升高血压","升压素抗利尿，又称抗利尿激素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full44.jpg","imageExplain":"功能对比图应把催产素指向子宫和乳腺，把升压素指向血管和肾脏集合管，注意升压素的抗利尿作用是其名称之外的另一个关键功能。","check":{"kind":"mcq","id":"bc14_check_43","q":"升压素因具有何种作用而又称抗利尿激素？","a":"A","e":"升压素使毛细血管收缩升高血压，并有减少排尿的抗利尿作用，故称抗利尿激素。","src":"本页自测","o":["A. 减少排尿","B. 促进排钠","C. 增加排尿","D. 促进排钾"],"oe":["A正确：减少排尿即抗利尿作用。","B错误：排钠不是其抗利尿名称的来源。","C错误：它减少而非增加排尿。","D错误：排钾不是其抗利尿作用的表述。"]}},{"i":44,"sec":"老师PPT逐页","title":"垂体激素的小结","notes":"垂体体积虽小，但分泌的激素种类很多，覆盖生长、泌乳、代谢、应激、生殖和水盐平衡等多方面。这些激素的分泌都受下丘脑的控制，构成下丘脑—垂体—靶腺的调控体系。垂体因此被视为内分泌系统的枢纽。","points":["垂体小但分泌激素种类多","功能覆盖生长、代谢、生殖等","分泌受下丘脑控制","是内分泌调控的枢纽"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full45.jpg","imageExplain":"小结图应把垂体放在中心，向上连下丘脑、向下连各类靶腺和靶组织，体现“小腺体、大网络”的枢纽地位。","check":{"kind":"mcq","id":"bc14_check_44","q":"垂体被视为内分泌系统的枢纽，主要原因是？","a":"A","e":"垂体虽小，分泌激素种类多，覆盖生长、泌乳、代谢、应激、生殖和水盐平衡，并受下丘脑控制。","src":"本页自测","o":["A. 体积小但分泌激素种类多，且分泌受下丘脑控制","B. 体积大且能合成所有激素","C. 直接感受环境刺激并独立调节全身","D. 只分泌一种激素但作用广泛"],"oe":["A正确：种类多且受下丘脑控制是其枢纽地位的原因。","B错误：垂体体积小，也不能合成所有激素。","C错误：垂体受下丘脑控制，并非独立调节全身。","D错误：垂体分泌多种激素，不只一种。"]}},{"i":45,"sec":"老师PPT逐页","title":"下丘脑激素的调控作用","notes":"下丘脑通过释放因子和抑制因子调控腺垂体，腺垂体再分泌促激素作用于外周腺体，最终影响靶细胞。下丘脑还合成催产素和升压素，经神经垂体释放。下丘脑因此把神经信号转换为内分泌信号。","points":["释放/抑制因子调控腺垂体","经腺垂体促激素影响靶腺","合成催产素与升压素","是神经与内分泌的转换枢纽"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full46.jpg","imageExplain":"下丘脑调控图应显示两条输出：一条经释放因子到腺垂体再逐级向下，另一条合成催产素/升压素经神经垂体释放。","check":{"kind":"mcq","id":"bc14_check_45","q":"下丘脑被视为神经与内分泌的转换枢纽，是因为？","a":"A","e":"下丘脑通过释放/抑制因子调控腺垂体，并合成催产素和升压素经神经垂体释放，实现神经信号向内分泌信号的转换。","src":"本页自测","o":["A. 它把神经信号转换为内分泌信号，通过释放因子和激素调控垂体","B. 它只接收神经信号而不分泌任何激素","C. 它直接分泌胰岛素调节血糖","D. 它只合成类固醇激素"],"oe":["A正确：转换枢纽的含义即神经信号转为内分泌信号。","B错误：下丘脑分泌多种肽类激素。","C错误：胰岛素由胰岛B细胞分泌。","D错误：下丘脑激素主要为肽类，不是类固醇。"]}},{"i":46,"sec":"老师PPT逐页","title":"下丘脑的十种肽类激素","notes":"下丘脑至少分泌10种激素，化学本质都属肽类，且多为分子量较小的小肽。它们包括生长激素释放因子与抑制因子（somatostatin）、催乳激素释放因子与抑制因子、促甲状腺激素释放因子、促肾上腺皮质激素释放因子、黄体生成素释放因子、促卵泡激素释放因子以及促黑激素释放因子与抑制因子。释放因子促进、抑制因子抑制腺垂体相应激素的分泌。","points":["至少10种，均为小分子多肽","分释放因子RF和抑制因子RIF","生长抑素即somatostatin","分别对应腺垂体各激素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full47.jpg","imageExplain":"清单图应按“释放因子/抑制因子”两列排列，并把每一种下丘脑因子与其对应的腺垂体激素配对，注意生长抑素是抑制因子。","check":{"kind":"mcq","id":"bc14_check_46","q":"下丘脑分泌的激素在化学本质上属于？","a":"A","e":"下丘脑至少分泌10种激素，化学本质都属肽类，且多为分子量较小的小肽。","src":"本页自测","o":["A. 小分子多肽","B. 类固醇","C. 脂肪酸衍生物","D. 糖蛋白"],"oe":["A正确：下丘脑激素为小分子多肽。","B错误：下丘脑激素不是类固醇。","C错误：不是脂肪酸衍生物。","D错误：下丘脑激素不属于糖蛋白类促激素。"]}},{"i":47,"sec":"老师PPT逐页","title":"脑肽与内啡肽","notes":"脑肽是存在于中枢神经系统中的一类神经肽，内啡肽是其中的代表。内啡肽具有镇痛作用，属于内源性阿片肽，能与阿片受体结合。脑肽的发现说明神经系统与内分泌系统共享肽类信号分子。","points":["脑肽为中枢神经系统的神经肽","内啡肽是代表成员","内啡肽具有镇痛作用","属内源性阿片肽"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full48.jpg","imageExplain":"脑肽页面应把内啡肽与镇痛效应、阿片受体联系起来，理解它是神经系统自身产生的类阿片物质。","check":{"kind":"mcq","id":"bc14_check_47","q":"内啡肽的主要生理作用是？","a":"A","e":"内啡肽是内源性阿片肽，能与阿片受体结合，具有镇痛作用。","src":"本页自测","o":["A. 镇痛","B. 升高血糖","C. 促进泌乳","D. 收缩子宫"],"oe":["A正确：镇痛是内啡肽的代表性作用。","B错误：升高血糖主要与胰高血糖素、肾上腺素等有关。","C错误：促进泌乳是催乳激素的作用。","D错误：收缩子宫是催产素的作用。"]}},{"i":48,"sec":"老师PPT逐页","title":"胰岛与甲状旁腺激素","notes":"胰岛分泌胰岛素和胰高血糖素，分别由B细胞和A细胞产生，共同调节血糖。胰岛素降低血糖，胰高血糖素升高血糖。甲状旁腺分泌甲状旁腺激素，主要调节血钙和血磷水平。这些激素与垂体轴共同维持内环境稳定。","points":["胰岛素由胰岛B细胞分泌","胰高血糖素由A细胞分泌","二者反向调节血糖","甲状旁腺激素调节钙磷代谢"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full49.jpg","imageExplain":"胰岛与甲状旁腺示意图应标出胰岛A、B细胞及各自激素，并标出甲状旁腺激素作用于骨、肾和肠道以调节血钙的方向。","check":{"kind":"mcq","id":"bc14_check_48","q":"胰岛中分泌胰高血糖素的细胞是？","a":"A","e":"胰岛素由B细胞分泌，胰高血糖素由A细胞分泌，二者反向调节血糖。","src":"本页自测","o":["A. A细胞","B. B细胞","C. D细胞","D. PP细胞"],"oe":["A正确：A细胞分泌胰高血糖素。","B错误：B细胞分泌胰岛素。","C错误：D细胞主要分泌生长抑素。","D错误：PP细胞分泌胰多肽。"]}},{"i":49,"sec":"老师PPT逐页","title":"胰岛素的一级结构与加工","notes":"胰岛素先以更长前体形式合成：前胰岛素原切除信号肽成为胰岛素原，再切除中间的C肽才生成成熟胰岛素。成熟胰岛素含A、B两条肽链，链间由二硫键连接，A链内还有链内二硫键。信号肽引导肽链进入内质网，C肽的切除是成熟的关键步骤。","points":["前胰岛素原→胰岛素原→成熟胰岛素","信号肽引导进入内质网并被切除","C肽连接A、B链，成熟时被切除","A链与B链靠链间二硫键相连","A链内另有链内二硫键"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full50.jpg","imageExplain":"看图中A链、B链两条肽链、连接它们的链间二硫键，以及被切下的信号肽和C肽位置。","check":{"kind":"mcq","id":"bc14_check_49","q":"成熟胰岛素中A链与B链之间的连接方式是？","a":"A","e":"成熟胰岛素含A、B两条肽链，链间由二硫键连接，A链内还有链内二硫键。","src":"本页自测","o":["A. 链间二硫键","B. 肽键直接相连","C. 氢键连接","D. C肽共价桥接"],"oe":["A正确：A、B链靠链间二硫键相连。","B错误：两条链不是以肽键直接相连。","C错误：氢键不是维持A、B链共价连接的方式。","D错误：C肽在成熟时已被切除，不桥接两条链。"]}},{"i":50,"sec":"老师PPT逐页","title":"胰岛素的降血糖功能","notes":"胰岛素是降低血糖的核心激素，它促进肝糖原和肌糖原的合成，并促进葡萄糖氧化分解为CO2和H2O。它同时促进蛋白质与脂类的合成代谢，使血糖去路增加、来源减少。因此胰岛素不足时血糖升高。","points":["促进糖原合成，降低血糖","促进葡萄糖氧化供能","促进蛋白质合成","促进脂类合成","总体使血糖下降"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full51.jpg","imageExplain":"看图中胰岛素作用下葡萄糖分别流向糖原、CO2+H2O以及合成代谢的方向箭头。","check":{"kind":"mcq","id":"bc14_check_50","q":"下列哪项不是胰岛素的降血糖作用？","a":"A","e":"胰岛素促进糖原合成、葡萄糖氧化和蛋白质/脂类合成，从而降低血糖；促进肝糖原分解是升糖作用。","src":"本页自测","o":["A. 促进肝糖原分解","B. 促进肝糖原和肌糖原合成","C. 促进葡萄糖氧化分解","D. 促进蛋白质和脂类合成"],"oe":["A正确：促进肝糖原分解会升高血糖，不是胰岛素作用。","B错误：促进糖原合成确是胰岛素降糖机制。","C错误：促进葡萄糖氧化确是胰岛素作用。","D错误：促进合成代谢确是胰岛素作用。"]}},{"i":51,"sec":"老师PPT逐页","title":"胰高血糖素的升血糖作用","notes":"胰高血糖素是由29个氨基酸组成的多肽激素，作用在许多方面与胰岛素相反。它主要促使肝糖原分解，使血糖升高，并促进脂肪分解。它是空腹或应激时维持血糖的重要升糖激素。","points":["化学本质为29肽","主要靶点为肝脏","促进肝糖原分解、升高血糖","促进脂肪分解","与胰岛素作用相反"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full52.jpg","imageExplain":"看图中胰高血糖素作用于肝细胞后糖原分解为葡萄糖并释放入血的方向。","check":{"kind":"mcq","id":"bc14_check_51","q":"胰高血糖素由多少个氨基酸组成？","a":"A","e":"胰高血糖素是由29个氨基酸组成的多肽激素。","src":"本页自测","o":["A. 29个","B. 39个","C. 32个","D. 51个"],"oe":["A正确：胰高血糖素为29肽。","B错误：39肽是ACTH。","C错误：32肽是降钙素。","D错误：51个氨基酸是胰岛素两条链的总数，不是胰高血糖素。"]}},{"i":52,"sec":"老师PPT逐页","title":"维持血糖的激素（课堂提问）","notes":"本页只提出「哪些激素与维持血糖的水平有关」这一问题，没有给出图示或答案，属于课堂讨论的过渡页。回答时应把降糖的胰岛素与升糖的胰高血糖素、肾上腺素、糖皮质激素、生长激素等放在一起比较。","points":["课堂提问页，无独立图示","降糖主角是胰岛素","升糖包括胰高血糖素","肾上腺素、糖皮质激素也升糖","生长激素等参与长期调节"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full53.jpg","imageExplain":"该页为纯文字提问，没有可读图；若有配图只需确认是问题页而非通路图。","check":{"kind":"mcq","id":"bc14_check_52","q":"课堂提问“哪些激素与维持血糖水平有关”中，降低血糖的核心激素是？","a":"A","e":"胰岛素是降低血糖的核心激素，胰高血糖素、肾上腺素、糖皮质激素等主要升高血糖。","src":"本页自测","o":["A. 胰岛素","B. 胰高血糖素","C. 肾上腺素","D. 糖皮质激素"],"oe":["A正确：胰岛素是唯一核心降糖激素。","B错误：胰高血糖素升高血糖。","C错误：肾上腺素升高血糖。","D错误：糖皮质激素升高血糖。"]}},{"i":53,"sec":"老师PPT逐页","title":"甲状旁腺激素（PTH）","notes":"甲状旁腺激素是蛋白质类激素，存在种属差异。它的靶器官是骨和肾脏，总体效应是升高血钙、降低血磷。它通过促进骨钙释放、增加肾小管钙重吸收并影响维生素D活化来实现这一效应。","points":["化学本质为蛋白质激素","有种属差异","靶器官为骨和肾脏","血钙升高","血磷降低"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full54.jpg","imageExplain":"看图中PTH（甲状旁腺激素）作用于骨与肾脏的箭头，以及血钙上升、血磷下降的结果标注。","check":{"kind":"mcq","id":"bc14_check_53","q":"甲状旁腺激素（PTH）对血钙和血磷的总体效应是？","a":"A","e":"PTH（甲状旁腺激素）靶器官为骨和肾脏，总体效应是升高血钙、降低血磷。","src":"本页自测","o":["A. 血钙升高、血磷降低","B. 血钙降低、血磷升高","C. 血钙和血磷都升高","D. 血钙和血磷都降低"],"oe":["A正确：PTH使血钙升高、血磷降低。","B错误：与PTH实际效应相反。","C错误：血钙和血磷都升高是活性维生素D的效应。","D错误：血钙和血磷都降低是降钙素的效应。"]}},{"i":54,"sec":"老师PPT逐页","title":"降钙素（CT）","notes":"降钙素是由32个氨基酸组成的多肽，靶器官同样是骨和肾脏。它的效应与甲状旁腺激素相反：降低血钙、降低血磷。它抑制骨钙释放、促进钙在骨中沉积，是重要的降钙激素。","points":["化学本质为32肽","靶器官为骨和肾脏","血钙降低","血磷降低","与PTH（甲状旁腺激素）效应相拮抗"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full55.jpg","imageExplain":"看图中降钙素作用于骨、肾后血钙与血磷同时下降的标注。","check":{"kind":"mcq","id":"bc14_check_54","q":"降钙素（CT）对血钙和血磷的效应是？","a":"A","e":"降钙素由32个氨基酸组成，靶器官为骨和肾脏，使血钙和血磷都降低。","src":"本页自测","o":["A. 血钙降低、血磷降低","B. 血钙升高、血磷降低","C. 血钙升高、血磷升高","D. 血钙降低、血磷升高"],"oe":["A正确：CT使血钙和血磷均降低。","B错误：血钙升高、血磷降低是PTH的效应。","C错误：二者都升高是活性维生素D的效应。","D错误：CT不使血磷升高。"]}},{"i":55,"sec":"老师PPT逐页","title":"三种钙磷调节激素对比","notes":"本页把三种调钙激素的效应并列比较：甲状旁腺激素使血钙升高、血磷降低；降钙素使血钙和血磷都降低；1,25-二羟胆钙化醇（活性维生素D）使血钙和血磷都升高。理解这一张表就能区分三个激素对钙磷的相反或协同作用。","points":["PTH（甲状旁腺激素）：血钙↑、血磷↓","降钙素：血钙↓、血磷↓","1,25-二羟胆钙化醇：血钙↑、血磷↑","三者共同维持血钙稳定"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full56.jpg","imageExplain":"看三行对照中血钙与血磷各自的上下箭头，注意降钙素与活性维生素D在血磷上的差别。","check":{"kind":"mcq","id":"bc14_check_55","q":"三种钙磷调节激素中，使血钙和血磷都升高的是？","a":"A","e":"PTH（甲状旁腺激素）使血钙升高、血磷降低；降钙素使二者都降低；1,25-二羟胆钙化醇使二者都升高。","src":"本页自测","o":["A. 1,25-二羟胆钙化醇（活性维生素D）","B. 甲状旁腺激素","C. 降钙素","D. 胰岛素"],"oe":["A正确：活性维生素D使血钙和血磷都升高。","B错误：PTH使血钙升高但血磷降低。","C错误：降钙素使血钙和血磷都降低。","D错误：胰岛素不参与这三种调钙激素的对比。"]}},{"i":56,"sec":"老师PPT逐页","title":"肾上腺皮质激素与固醇骨架","notes":"肾上腺皮质激素由肾上腺皮质分泌，主要有7种，都属于环戊烷多氢菲（甾核）衍生物。按作用可分为糖皮质激素、盐皮质激素和少量性激素前体。图中给出的是皮质激素的通用甾体骨架及C11、C13、C17等关键取代位置。","points":["来源于肾上腺皮质","主要有7种","化学本质为类固醇","共同骨架是环戊烷多氢菲","C11、C17等取代基决定活性"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full57.jpg","imageExplain":"看甾核四个环以及C11、C13、C17上R1、R2等可变取代基，理解同骨架不同基团产生不同激素。","check":{"kind":"mcq","id":"bc14_check_56","q":"肾上腺皮质激素的共同骨架是？","a":"A","e":"肾上腺皮质激素主要有7种，都属于环戊烷多氢菲（甾核）衍生物。","src":"本页自测","o":["A. 环戊烷多氢菲（甾核）","B. 前列腺烷酸","C. 花生四烯酸","D. 酪氨酸"],"oe":["A正确：环戊烷多氢菲是皮质激素的通用甾体骨架。","B错误：前列腺烷酸是前列腺素骨架。","C错误：花生四烯酸是脂肪酸衍生物前体。","D错误：酪氨酸是氨基酸衍生物激素前体。"]}},{"i":57,"sec":"老师PPT逐页","title":"糖皮质激素","notes":"糖皮质激素包括皮质酮、皮质醇和可的松，因对糖代谢影响大、对水盐代谢影响小而命名。它调节糖代谢：抑制糖的氧化、促使蛋白质转化为糖，从而升高血糖。临床上还利用其抗炎、抗免疫作用。","points":["代表物：皮质酮、皮质醇、可的松","主要影响糖代谢","抑制葡萄糖氧化","促进蛋白质转化为糖","升高血糖"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full58.jpg","imageExplain":"看图中糖皮质激素作用下蛋白质→糖、血糖升高的方向箭头。","check":{"kind":"mcq","id":"bc14_check_57","q":"下列哪项不属于糖皮质激素的代表物？","a":"A","e":"糖皮质激素包括皮质酮、皮质醇和可的松；醛固酮是盐皮质激素的代表。","src":"本页自测","o":["A. 醛固酮","B. 皮质酮","C. 皮质醇","D. 可的松"],"oe":["A正确：醛固酮属盐皮质激素，不是糖皮质激素。","B错误：皮质酮是糖皮质激素。","C错误：皮质醇是糖皮质激素。","D错误：可的松是糖皮质激素。"]}},{"i":58,"sec":"老师PPT逐页","title":"盐皮质激素","notes":"盐皮质激素对水、盐代谢影响大，对糖和蛋白质代谢影响较小。其代表是醛固酮，主要作用是保钠排钾，从而调节水盐平衡和血容量。","points":["主要影响水盐代谢","代表激素为醛固酮","促进肾小管保钠","促进排钾","维持血容量与血压"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full59.jpg","imageExplain":"看图中肾小管处Na+重吸收、K+排出的箭头，注意保钠排钾的方向。","check":{"kind":"mcq","id":"bc14_check_58","q":"盐皮质激素醛固酮的主要作用是？","a":"A","e":"醛固酮对水盐代谢影响大，主要作用是保钠排钾，维持血容量与血压。","src":"本页自测","o":["A. 保钠排钾，调节水盐平衡和血容量","B. 升高血糖并促进蛋白质转化为糖","C. 促进骨钙释放","D. 促进乳腺泌乳"],"oe":["A正确：保钠排钾是醛固酮的核心作用。","B错误：这是糖皮质激素的糖代谢作用。","C错误：促进骨钙释放是PTH作用。","D错误：促进泌乳是催乳激素作用。"]}},{"i":59,"sec":"老师PPT逐页","title":"雌性性激素的来源","notes":"雌性性激素主要包括卵泡激素和黄体激素，主要由卵巢产生。人类的胎盘、肾上腺皮质甚至睾丸也能产生少量雌激素。因此雌激素并非只由卵巢独有。","points":["分为卵泡激素与黄体激素","主要由卵巢分泌","胎盘可产生雌激素","肾上腺皮质可产生少量","睾丸也产生少量雌激素"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full60.jpg","imageExplain":"看图中卵巢为中心、胎盘与肾上腺皮质等旁支来源的标注。","check":{"kind":"mcq","id":"bc14_check_59","q":"雌性性激素的主要来源是？","a":"A","e":"雌性性激素主要由卵巢产生，胎盘、肾上腺皮质和睾丸也能产生少量雌激素。","src":"本页自测","o":["A. 卵巢","B. 睾丸","C. 肾上腺髓质","D. 甲状腺"],"oe":["A正确：卵巢是主要来源。","B错误：睾丸主要产生雄激素，只产生少量雌激素。","C错误：肾上腺髓质分泌肾上腺素，不产生雌激素。","D错误：甲状腺不产生雌性性激素。"]}},{"i":60,"sec":"老师PPT逐页","title":"雌激素的化学结构","notes":"卵泡激素包括雌二醇、雌三醇和雌酮，都可看作雌烃（雌烷）的衍生物。三者结构相近，差别主要在A环和D环上的羟基、羰基数目。雌二醇是活性最高的天然雌激素。","points":["包括雌二醇、雌三醇、雌酮","均属雌烷衍生物","A环为芳香环","差别在羟基与羰基数目","雌二醇活性最高"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full61.jpg","imageExplain":"比较图中雌二醇、雌三醇、雌酮的结构式，重点看A环酚羟基和D环羟基/羰基的差异。","check":{"kind":"mcq","id":"bc14_check_60","q":"天然雌激素中活性最高的是？","a":"A","e":"雌二醇是活性最高的天然雌激素，雌酮次之，雌三醇最弱。","src":"本页自测","o":["A. 雌二醇","B. 雌三醇","C. 雌酮","D. 孕酮"],"oe":["A正确：雌二醇活性最高。","B错误：雌三醇活性最低。","C错误：雌酮活性次之。","D错误：孕酮是黄体激素，不是雌激素。"]}},{"i":61,"sec":"老师PPT逐页","title":"雌激素的生理功能","notes":"雌激素促进女性器官发育并参与排卵调节。三种天然雌激素中雌二醇活性最高，雌酮次之，雌三醇最弱。临床与生理上常以雌二醇作为主要活性形式。","points":["促进女性生殖器官发育","参与排卵调节","雌二醇活性最高","雌酮次之","雌三醇活性最低"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full62.jpg","imageExplain":"看图中三种雌激素并列及其活性高低的标注顺序。","check":{"kind":"mcq","id":"bc14_check_61","q":"三种天然雌激素的活性由强到弱依次是？","a":"A","e":"雌二醇活性最高，雌酮次之，雌三醇最弱。","src":"本页自测","o":["A. 雌二醇＞雌酮＞雌三醇","B. 雌三醇＞雌酮＞雌二醇","C. 雌酮＞雌二醇＞雌三醇","D. 三者活性相同"],"oe":["A正确：活性顺序符合本章表述。","B错误：雌三醇活性最弱，不应排第一。","C错误：雌二醇活性高于雌酮。","D错误：三者活性并不相同。"]}},{"i":62,"sec":"老师PPT逐页","title":"孕酮（黄体激素）","notes":"黄体激素主要为孕酮，是维持妊娠的重要甾体激素。它促进子宫和乳腺发育，抑制排卵、抑制动情，并对全身代谢有显著影响。孕酮与雌激素协同调节月经周期与妊娠。","points":["黄体激素主要是孕酮","促进子宫内膜与乳腺发育","抑制排卵","抑制动情","对全身代谢有影响"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full63.jpg","imageExplain":"看孕酮的甾体结构式，注意C3酮基和C4-C5双键等特征基团。","check":{"kind":"mcq","id":"bc14_check_62","q":"下列哪项不是孕酮的作用？","a":"A","e":"孕酮促进子宫和乳腺发育，抑制排卵和动情，维持妊娠；它不促进排卵。","src":"本页自测","o":["A. 促进排卵","B. 促进子宫内膜和乳腺发育","C. 抑制排卵","D. 抑制动情"],"oe":["A正确：孕酮抑制而非促进排卵。","B错误：促进子宫内膜和乳腺发育确是孕酮作用。","C错误：抑制排卵确是孕酮作用。","D错误：抑制动情确是孕酮作用。"]}},{"i":63,"sec":"老师PPT逐页","title":"雄性性激素","notes":"雄激素包括睾酮、雄酮和雄烯二酮，可看作雄烃（雄烷）的衍生物。它刺激男性性器官发育、促进精子生成并促进第二性征。此外雄激素还有明显的全身代谢（蛋白同化）作用。","points":["包括睾酮、雄酮、雄烯二酮","属雄烷衍生物","促进男性生殖器官发育","促进精子生成与第二性征","具有全身代谢/同化作用"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full64.jpg","imageExplain":"看三种雄激素的结构式并比较C17羟基与C4-C5双键的差别。","check":{"kind":"mcq","id":"bc14_check_63","q":"下列哪项不属于雄激素？","a":"A","e":"雄激素包括睾酮、雄酮和雄烯二酮；雌二醇是雌激素。","src":"本页自测","o":["A. 雌二醇","B. 睾酮","C. 雄酮","D. 雄烯二酮"],"oe":["A正确：雌二醇是雌激素，不属于雄激素。","B错误：睾酮是雄激素。","C错误：雄酮是雄激素。","D错误：雄烯二酮是雄激素。"]}},{"i":64,"sec":"老师PPT逐页","title":"前列腺素的基本结构","notes":"前列腺素属于脂肪族激素，骨架可看作前列腺烷酸。所有天然前列腺素在C13与C14之间有一个反式双键，并在C15上有一个羟基。这两点是识别前列腺素结构的关键特征。","points":["属脂肪酸衍生物","骨架为前列腺烷酸","C13-C14间有反式双键","C15上带羟基","由花生四烯酸衍生"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full65.jpg","imageExplain":"看前列腺烷酸编号1~20及C13=C14反式双键、C15羟基的位置标注。","check":{"kind":"mcq","id":"bc14_check_64","q":"识别天然前列腺素结构的关键特征是？","a":"A","e":"天然前列腺素在C13-C14之间有反式双键，C15上有羟基；骨架为前列腺烷酸。","src":"本页自测","o":["A. C13与C14之间有反式双键，C15上有羟基","B. C1与C2之间有顺式双键，C15上有酮基","C. 含环戊烷多氢菲骨架","D. 含二硫键形成的二十元环"],"oe":["A正确：这两点是识别前列腺素的关键结构特征。","B错误：双键位置、构型及C15基团均不符。","C错误：环戊烷多氢菲是类固醇骨架。","D错误：二硫键二十元环是催产素和升压素的特征。"]}},{"i":65,"sec":"老师PPT逐页","title":"前列腺素的主要类型","notes":"依五碳环上取代基和双键的不同，前列腺素分为PGE、PGF、PGA、PGB等类型。PGFα为天然形式，PGFβ多为化学合成；不同型别在环上羟基、酮基位置不同。类型差异决定其生理作用差异。","points":["分为PGE、PGF、PGA、PGB等","PGFα为天然形式","PGFβ常为化学合成","环上羟基/酮基位置不同","结构差异导致作用不同"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full66.jpg","imageExplain":"对照图中PGE、PGFα、PGFβ、PGA、PGB的五碳环取代基差异。","check":{"kind":"mcq","id":"bc14_check_65","q":"关于前列腺素的类型，下列哪项正确？","a":"A","e":"前列腺素分为PGE、PGF、PGA、PGB等，PGFα为天然形式，PGFβ多为化学合成。","src":"本页自测","o":["A. PGFα为天然形式，PGFβ多为化学合成","B. PGFα多为化学合成，PGFβ为天然形式","C. 前列腺素只有PGE一种类型","D. 各型前列腺素结构完全相同"],"oe":["A正确：天然与合成形式的对应关系正确。","B错误：二者天然/合成的对应说反了。","C错误：前列腺素包括PGE、PGF、PGA、PGB等多种类型。","D错误：各型在环上羟基、酮基位置不同，结构并不相同。"]}},{"i":66,"sec":"老师PPT逐页","title":"激素作用机制：为什么只作用于靶细胞","notes":"激素作用机制的核心问题是靶细胞膜上或靶细胞内部存在特异性受体。受体决定了哪种细胞能识别并响应某一激素，因此激素只对具有相应受体的靶细胞起作用。这一页是后续各类受体与信号通路的引子。","points":["受体位于靶细胞膜或细胞内","受体决定靶细胞特异性","激素只作用于有受体的细胞","引出膜受体与胞内受体两大类"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full67.jpg","imageExplain":"该页为概念引入，看图时确认激素分子与靶细胞受体结合的示意关系。","check":{"kind":"mcq","id":"bc14_check_66","q":"激素只作用于靶细胞的根本原因是？","a":"A","e":"靶细胞存在特异性受体，受体决定哪种细胞能识别并响应某一激素。","src":"本页自测","o":["A. 靶细胞膜上或细胞内部存在特异性受体","B. 激素能进入所有细胞并直接改变DNA","C. 所有细胞都有相同的受体","D. 激素在血液中只运输到靶细胞"],"oe":["A正确：特异性受体是靶细胞特异性的根本原因。","B错误：激素并非进入所有细胞直接改变DNA。","C错误：若所有细胞受体相同就失去特异性。","D错误：激素随血流分布全身，并非只运输到靶细胞。"]}},{"i":67,"sec":"老师PPT逐页","title":"受体与配体的基本概念","notes":"受体是能识别并与特定信号物质结合的特异蛋白质或糖脂。配体是与受体结合的细胞外生物活性物质，如激素、某些药物和毒素。受体与配体的结合具有特异性和可饱和性。","points":["受体是特异蛋白或糖脂","受体能识别特定信号","配体是细胞外活性物质","配体包括激素、药物、毒素","结合具有特异性"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full68.jpg","imageExplain":"看图中配体与受体互补结合的示意，理解特异性来自结构互补。","check":{"kind":"mcq","id":"bc14_check_67","q":"关于受体与配体，下列哪项符合本章概念？","a":"A","e":"受体是能识别并结合特定信号物质的特异蛋白质或糖脂；配体是细胞外活性物质，如激素、药物和毒素，结合具有特异性和可饱和性。","src":"本页自测","o":["A. 受体是能识别特定信号的蛋白质或糖脂，配体是细胞外活性物质","B. 受体都是脂类，配体都是细胞内酶","C. 受体与配体结合没有特异性且不可饱和","D. 配体只包括激素，不包括药物和毒素"],"oe":["A正确：受体与配体的定义均符合本章。","B错误：受体是蛋白质或糖脂，配体不是细胞内酶。","C错误：受体与配体结合具有特异性和可饱和性。","D错误：配体还包括某些药物和毒素。"]}},{"i":68,"sec":"老师PPT逐页","title":"受体的两大类：膜受体与胞内受体","notes":"按在细胞内的分布，受体分为膜受体和胞内受体。膜受体位于细胞质膜表面，接受水溶性激素等不能入胞的信号；胞内受体位于胞质或核内，接受可穿过质膜的脂溶性激素。这一分布差异决定了信号转导方式。","points":["按分布分为膜受体与胞内受体","膜受体在质膜表面","胞内受体在胞质或核内","水溶性激素多用膜受体","脂溶性激素多用胞内受体"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full69.jpg","imageExplain":"看图中受体分别位于细胞膜外侧与细胞内的两类定位示意。","check":{"kind":"mcq","id":"bc14_check_68","q":"下列有关膜受体与胞内受体分布的叙述，正确的是？","a":"B","e":"按细胞内分布，膜受体在质膜表面接受水溶性激素；胞内受体在胞质或核内接受可穿膜的脂溶性激素，这一分布差异决定了信号转导方式。","src":"本页自测","o":["A. 膜受体位于细胞质内，接受脂溶性激素","B. 膜受体位于质膜表面，主要接受不能自由入胞的水溶性激素","C. 胞内受体只存在于细胞核外","D. 脂溶性激素只能通过膜受体起作用"],"oe":["A错误：膜受体位于质膜表面而非细胞质内，且主要接受水溶性激素。","B正确：膜受体位于质膜表面，接受不能自由入胞的水溶性激素。","C错误：胞内受体可位于胞质或核内，并非只存在于核外。","D错误：脂溶性激素多与胞内/核受体结合，而非只能经膜受体。"]}},{"i":69,"sec":"老师PPT逐页","title":"膜受体（一）：离子通道型受体","notes":"膜受体按结构和信号转换方式分类，首先是离子通道型受体，主要见于神经递质受体。配体结合后通道开放，离子快速跨膜流动，引起膜电位变化，因此响应非常迅速。","points":["属于膜受体","主要为神经递质受体","配体门控离子通道","离子快速跨膜流动","响应迅速"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full70.jpg","imageExplain":"看图中受体形成跨膜通道、配体结合后离子内流的示意。","check":{"kind":"mcq","id":"bc14_check_69","q":"离子通道型膜受体最主要的特点是？","a":"B","e":"离子通道型受体属于膜受体，主要为神经递质受体，配体门控通道开放后离子快速跨膜流动，引起膜电位变化，响应非常迅速。","src":"本页自测","o":["A. 必须经G蛋白介导后通道才开放","B. 配体结合后通道开放，离子快速跨膜流动，响应迅速","C. 配体结合后受体自身发生酪氨酸磷酸化","D. 位于核内，调节基因转录"],"oe":["A错误：G蛋白介导是G蛋白偶联受体的特点，不是离子通道型受体的必需环节。","B正确：配体结合使通道开放，离子快速跨膜流动，故响应迅速。","C错误：受体自身酪氨酸磷酸化是酶活性受体（如胰岛素受体）的特点。","D错误：位于核内调节转录的是胞内/核受体，不是离子通道型受体。"]}},{"i":70,"sec":"老师PPT逐页","title":"膜受体（二）：G蛋白偶联型受体","notes":"G蛋白偶联受体是跨膜糖蛋白，通常为一条肽链七次跨膜。它接受胞外信号后并不直接改变细胞内过程，而需G蛋白介导，再激活或抑制效应酶。肾上腺素α2、β受体和毒蕈碱型乙酰胆碱受体属于此类。","points":["本质为跨膜糖蛋白","一条肽链七次跨膜","信号传递需要G蛋白介导","不直接产生细胞内效应","例：α2/β肾上腺素受体、毒蕈碱受体"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full71.jpg","imageExplain":"看图中七次跨膜的受体与膜内侧G蛋白三聚体的偶联关系。","check":{"kind":"mcq","id":"bc14_check_70","q":"关于G蛋白偶联型受体的结构，正确的是？","a":"A","e":"G蛋白偶联受体是跨膜糖蛋白，通常一条肽链七次跨膜；接受胞外信号后不直接改变细胞内过程，而需G蛋白介导再激活或抑制效应酶。","src":"本页自测","o":["A. 一条肽链七次跨膜，信号传递需G蛋白介导","B. 由四条肽链组成，胞内段含酪氨酸激酶结构域","C. 本身即为配体门控离子通道","D. 位于核内，直接结合DNA"],"oe":["A正确：本质为跨膜糖蛋白，一条肽链七次跨膜，信号需G蛋白介导。","B错误：α2β2四条链并含酪氨酸激酶域是胰岛素受体的特征。","C错误：配体门控离子通道属于离子通道型受体，与G蛋白偶联受体不同。","D错误：位于核内直接结合DNA的是核受体，不是G蛋白偶联受体。"]}},{"i":71,"sec":"老师PPT逐页","title":"膜受体（三）：具有酶活性的受体","notes":"这类受体是跨膜糖蛋白，配体结合后可使受体自身磷酸化，并进一步催化底物蛋白特定酪氨酸残基磷酸化。胰岛素受体是典型代表，其胞内段具有酪氨酸激酶活性。","points":["本质为跨膜糖蛋白","配体结合引起受体自身磷酸化","可催化底物Tyr残基磷酸化","具有内在酪氨酸激酶活性","典型例子是胰岛素受体"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full72.jpg","imageExplain":"看图中配体结合后受体胞内段自磷酸化并磷酸化下游底物的示意。","check":{"kind":"mcq","id":"bc14_check_71","q":"胰岛素受体胞内段所具有的酶活性是？","a":"B","e":"具有酶活性的受体在配体结合后自身磷酸化，并催化底物蛋白特定酪氨酸残基磷酸化；胰岛素受体胞内段具有内在酪氨酸激酶活性。","src":"本页自测","o":["A. 丝氨酸/苏氨酸激酶活性","B. 酪氨酸激酶活性","C. 磷脂酶C活性","D. 腺苷酸环化酶活性"],"oe":["A错误：丝氨酸/苏氨酸磷酸化多是PKA等激酶对底物的作用，不是胰岛素受体胞内段的酶活性。","B正确：胰岛素受体胞内段具有内在酪氨酸激酶活性，可自磷酸化并磷酸化底物Tyr残基。","C错误：磷脂酶C是Gq通路中水解PIP2的酶，不是胰岛素受体的活性。","D错误：腺苷酸环化酶催化ATP生成cAMP，与胰岛素受体激酶活性无关。"]}},{"i":72,"sec":"老师PPT逐页","title":"胞内受体（核受体）","notes":"胞内受体主要存在于细胞核内，部分在胞浆中结合配体后再转入核内。它们的作用是调节基因转录，因此效应出现较慢但持久。类固醇激素受体和甲状腺素受体属于此类。","points":["主要位于细胞核内","部分在胞浆结合配体后入核","作用是调节基因转录","效应较慢而持久","例：类固醇、甲状腺素受体"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full73.jpg","imageExplain":"看图中受体从胞浆结合激素后穿过核膜进入核内的路径。","check":{"kind":"mcq","id":"bc14_check_72","q":"胞内受体（核受体）的主要作用方式是？","a":"B","e":"胞内受体主要位于细胞核内，部分在胞浆结合配体后转入核内，作用是调节基因转录，因此效应出现较慢但持久；类固醇激素受体和甲状腺素受体属于此类。","src":"本页自测","o":["A. 直接开放离子通道","B. 调节基因转录，效应较慢而持久","C. 生成cAMP并激活PKA","D. 直接激活腺苷酸环化酶"],"oe":["A错误：直接开放离子通道是离子通道型膜受体的作用。","B正确：核受体调节基因转录，效应较慢而持久。","C错误：生成cAMP并激活PKA是膜受体-cAMP通路的事件。","D错误：激活腺苷酸环化酶由Gs等G蛋白完成，不是核受体的作用。"]}},{"i":73,"sec":"老师PPT逐页","title":"肽/胺类与类固醇激素信号通路对比","notes":"肽类和胺类激素作用于膜受体，不进入细胞，通过第二信使cAMP（环腺苷一磷酸）等改变已有酶的活性，因此起效快。类固醇和甲状腺激素能穿过质膜，与胞内或核受体结合，复合物在核内调控基因转录，改变新合成蛋白的量，因此起效慢。","points":["肽/胺类用膜受体","肽/胺类经第二信使改变酶活性","肽/胺类起效快","类固醇/甲状腺激素进入细胞","核受体调控转录、改变蛋白量","类固醇/甲状腺激素起效慢"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full74.jpg","imageExplain":"看左右两条通路：左侧膜受体→cAMP（环腺苷一磷酸）→酶活性，右侧激素入胞→核受体→基因转录→新蛋白。","check":{"kind":"mcq","id":"bc14_check_73","q":"关于肽/胺类激素与类固醇激素信号通路的比较，正确的是？","a":"A","e":"肽类和胺类激素作用于膜受体，不进入细胞，通过cAMP（环腺苷一磷酸）等第二信使改变已有酶活性，起效快；类固醇和甲状腺激素穿膜与胞内/核受体结合，调控基因转录，起效慢。","src":"本页自测","o":["A. 肽/胺类经膜受体与第二信使起作用，起效快","B. 肽/胺类进入细胞后作用于核受体","C. 类固醇激素经膜受体起作用，起效快","D. 类固醇激素通过cAMP改变已有酶的活性"],"oe":["A正确：肽/胺类用膜受体，经第二信使改变酶活性，起效快。","B错误：肽/胺类不进入细胞，作用于膜受体而非核受体。","C错误：类固醇激素进入细胞与核受体结合，起效慢而非快。","D错误：类固醇激素改变的是基因转录和新蛋白量，而非通过cAMP改变已有酶活性。"]}},{"i":74,"sec":"老师PPT逐页","title":"激素信号转导的四种途径","notes":"本章把激素作用机制归纳为四条途径：cAMP（环腺苷一磷酸）途径、钙及肌醇三磷酸途径、受体酪氨酸激酶途径，以及固醇类激素受体调节基因转录途径。前三条以膜受体为主，第四条以胞内/核受体为主。后续各节分别展开这四条通路。","points":["途径一：cAMP（环腺苷一磷酸）途径","途径二：钙及IP3（三磷酸肌醇）途径","途径三：受体酪氨酸激酶途径","途径四：固醇类受体调节基因转录"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full75.jpg","imageExplain":"看四种途径的总览列表，记住每条途径的核心信使或效应器。","check":{"kind":"mcq","id":"bc14_check_74","q":"下列哪一项不属于本章归纳的激素信号转导四条途径？","a":"D","e":"本章归纳的四条途径为：cAMP（环腺苷一磷酸）途径、钙及IP3（三磷酸肌醇）途径、受体酪氨酸激酶途径、固醇类激素受体调节基因转录途径；三羧酸循环属于代谢途径，不是激素信号转导途径。","src":"本页自测","o":["A. cAMP途径","B. 钙及肌醇三磷酸（IP3）途径","C. 受体酪氨酸激酶途径","D. 三羧酸循环途径"],"oe":["A错误：cAMP途径是四条途径之一。","B错误：钙及IP3途径是四条途径之一。","C错误：受体酪氨酸激酶途径是四条途径之一。","D正确：三羧酸循环是糖脂等氧化供能的代谢途径，不属于此处四条信号转导途径。"]}},{"i":75,"sec":"老师PPT逐页","title":"cAMP（环腺苷一磷酸）途径（小节标题）","notes":"本页只是「1．通过cAMP（环腺苷一磷酸）起作用」的小节标题，没有通路图或分子细节。它标志后续几页将讲解腺苷酸环化酶、cAMP与蛋白激酶A的级联。","points":["小节标题页","引出cAMP（环腺苷一磷酸）信号通路","后续讲AC（腺苷酸环化酶）、cAMP（环腺苷一磷酸）与PKA（蛋白激酶A）"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full76.jpg","imageExplain":"标题页，无独立图示；看图只需确认是cAMP（环腺苷一磷酸）途径的章节引导。","check":{"kind":"mcq","id":"bc14_check_75","q":"「通过cAMP（环腺苷一磷酸）起作用」这一小节随后主要讲解的分子顺序是？","a":"A","e":"该页只是cAMP（环腺苷一磷酸）途径的小节标题，标志后续将讲解腺苷酸环化酶（AC）、cAMP与蛋白激酶A（PKA）的级联。","src":"本页自测","o":["A. 腺苷酸环化酶→cAMP→蛋白激酶A","B. 磷脂酶C→IP3→蛋白激酶C","C. 受体酪氨酸激酶→IRS→GLUT4","D. 核受体→HRE→基因转录"],"oe":["A正确：cAMP小节引出AC、cAMP与PKA的级联。","B错误：PLC→IP3→PKC属于钙及IP3途径，不是本小节内容。","C错误：RTK→IRS→GLUT4属于受体酪氨酸激酶途径。","D错误：核受体→HRE→转录属于固醇类受体调节基因转录途径。"]}},{"i":76,"sec":"老师PPT逐页","title":"cAMP-AC-PKA通路总图","notes":"激素H结合受体R后激活G蛋白，进而激活腺苷酸环化酶AC（腺苷酸环化酶）。AC催化ATP（三磷酸腺苷）生成cAMP（环腺苷一磷酸），cAMP使无活性的蛋白激酶变为有活性，后者催化酶或蛋白质磷酸化，产生生理效应。磷酸酶水解脱去磷酸基团，使信号终止。","points":["H→R→G蛋白→AC（腺苷酸环化酶）","AC（腺苷酸环化酶）催化ATP（三磷酸腺苷）→cAMP（环腺苷一磷酸）","cAMP（环腺苷一磷酸）激活蛋白激酶","激酶使底物蛋白磷酸化","磷酸酶去磷酸化终止信号"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full77.jpg","imageExplain":"沿图中H→R→G→AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→蛋白激酶→底物-P→生理效应的箭头顺序阅读，并注意磷酸酶的回退箭头。","check":{"kind":"mcq","id":"bc14_check_76","q":"cAMP-AC-PKA通路的正确顺序是？","a":"A","e":"激素H结合受体R后激活G蛋白，进而激活腺苷酸环化酶AC（腺苷酸环化酶）；AC催化ATP（三磷酸腺苷）生成cAMP（环腺苷一磷酸），cAMP激活蛋白激酶，后者使底物蛋白磷酸化产生效应；磷酸酶去磷酸化使信号终止。","src":"本页自测","o":["A. 激素→受体→G蛋白→腺苷酸环化酶→cAMP→蛋白激酶→底物磷酸化","B. 激素→受体→磷脂酶C→DAG→蛋白激酶C","C. 激素→核受体→DNA→mRNA","D. 激素→受体酪氨酸激酶→IRS→PI3K"],"oe":["A正确：H→R→G蛋白→AC→cAMP→蛋白激酶→底物磷酸化，符合本页总图。","B错误：PLC→DAG→PKC属于IP3/DAG通路。","C错误：核受体→DNA→mRNA属于核受体通路。","D错误：RTK→IRS→PI3K属于受体酪氨酸激酶通路。"]}},{"i":77,"sec":"老师PPT逐页","title":"Sutherland与第二信使学说","notes":"第二信使学说由Sutherland提出，他因此获得1971年诺贝尔生理学或医学奖。该学说指出激素作为第一信使作用于膜受体，再通过cAMP（环腺苷一磷酸）等第二信使把信号传入细胞。这是激素作用机制研究的里程碑。","points":["Sutherland提出第二信使学说","激素为第一信使","cAMP（环腺苷一磷酸）为第二信使","获1971年诺贝尔生理学或医学奖"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full78.jpg","imageExplain":"本页为人物/学说说明页，看图时确认Sutherland与第二信使学说的对应关系。","check":{"kind":"mcq","id":"bc14_check_77","q":"第二信使学说由谁提出，并因此获得1971年诺贝尔生理学或医学奖？","a":"A","e":"第二信使学说由Sutherland提出，他因此获1971年诺贝尔生理学或医学奖；激素为第一信使，cAMP（环腺苷一磷酸）为第二信使。","src":"本页自测","o":["A. Sutherland","B. Bayliss","C. Starling","D. Krebs"],"oe":["A正确：Sutherland提出第二信使学说并获1971年诺贝尔生理学或医学奖。","B错误：Bayliss与Starling于1904年提出激素概念，并非第二信使学说。","C错误：Starling与Bayliss共同提出激素概念。","D错误：Krebs与第二信使学说的提出无关。"]}},{"i":78,"sec":"老师PPT逐页","title":"cAMP（环腺苷一磷酸）的产生与灭活","notes":"腺苷酸环化酶催化ATP（三磷酸腺苷）生成cAMP（环腺苷一磷酸），环核苷酸磷酸二酯酶则把cAMP水解为5′-AMP，两者共同决定cAMP水平。Mg2+是这两种酶的激活剂。咖啡碱和茶碱抑制磷酸二酯酶，从而提高cAMP、延长信号。","points":["AC（腺苷酸环化酶）：ATP（三磷酸腺苷）→cAMP（环腺苷一磷酸）","PDE：cAMP（环腺苷一磷酸）→5′-AMP","Mg2+激活两种酶","咖啡碱、茶碱抑制PDE","抑制PDE可延长cAMP（环腺苷一磷酸）信号"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full79.jpg","imageExplain":"看图中ATP（三磷酸腺苷）经AC（腺苷酸环化酶）生成cAMP（环腺苷一磷酸）、再经PDE降解为5′-AMP的双向流程及Mg2+、咖啡碱/茶碱的调节位点。","check":{"kind":"mcq","id":"bc14_check_78","q":"咖啡碱和茶碱提高cAMP（环腺苷一磷酸）水平、延长信号的机制是？","a":"B","e":"腺苷酸环化酶催化ATP（三磷酸腺苷）生成cAMP（环腺苷一磷酸），环核苷酸磷酸二酯酶把cAMP水解为5′-AMP；咖啡碱和茶碱抑制磷酸二酯酶，从而提高cAMP、延长信号。","src":"本页自测","o":["A. 激活腺苷酸环化酶","B. 抑制环核苷酸磷酸二酯酶，减少cAMP水解","C. 直接激活蛋白激酶A","D. 促进cAMP转化为ATP"],"oe":["A错误：咖啡碱/茶碱抑制的是磷酸二酯酶，不是激活腺苷酸环化酶。","B正确：抑制PDE可减少cAMP水解，使cAMP升高、信号延长。","C错误：它们不直接激活PKA，而是通过升高cAMP间接起作用。","D错误：cAMP的生成方向是ATP→cAMP，而非cAMP→ATP。"]}},{"i":79,"sec":"老师PPT逐页","title":"蛋白激酶A（PKA）的结构与激活","notes":"PKA（蛋白激酶A）由四个亚基组成：两个相同的催化亚基C和两个相同的调节亚基R。每个R上有两个cAMP（环腺苷一磷酸）结合位点，结合4个cAMP后C与R解离，游离的C亚基表现出激酶活性。PKA随后磷酸化底物蛋白的Ser/Thr残基。","points":["PKA（蛋白激酶A）为R2C2四聚体","含2个催化亚基C","含2个调节亚基R","每R结合2个cAMP（环腺苷一磷酸），共需4个","cAMP（环腺苷一磷酸）结合后C与R解离而活化"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full80.jpg","imageExplain":"看图中R2C2四聚体在4个cAMP（环腺苷一磷酸）结合后解聚为游离C亚基的过程。","check":{"kind":"mcq","id":"bc14_check_79","q":"关于蛋白激酶A（PKA）的亚基组成与激活，正确的是？","a":"A","e":"PKA（蛋白激酶A）由两个相同的催化亚基C和两个相同的调节亚基R组成R2C2四聚体；每个R有两个cAMP（环腺苷一磷酸）结合位点，结合4个cAMP后C与R解离，游离C亚基表现激酶活性，磷酸化底物Ser/Thr残基。","src":"本页自测","o":["A. 为R2C2四聚体，结合4个cAMP后C与R解离而活化","B. 为C2R2，仅需2个cAMP即可解离","C. 为单体酶，cAMP直接结合催化位点","D. 由α2β2组成，属于酪氨酸激酶"],"oe":["A正确：PKA为R2C2四聚体，共需4个cAMP，结合后C与R解离而活化。","B错误：每个R结合2个cAMP，两个R共需4个，不是2个。","C错误：PKA是R2C2四聚体，且cAMP结合于调节亚基R而非催化位点。","D错误：α2β2且具酪氨酸激酶活性的是胰岛素受体，不是PKA。"]}},{"i":80,"sec":"老师PPT逐页","title":"肾上腺素经cAMP（环腺苷一磷酸）升高血糖的机理","notes":"肾上腺素作为第一信使与靶细胞膜上的特异受体结合，激活腺苷酸环化酶。AC（腺苷酸环化酶）使ATP（三磷酸腺苷）分解为cAMP（环腺苷一磷酸）和PPi，cAMP升高后激活PKA（蛋白激酶A），PKA再激活糖原磷酸化酶激酶，最终促进糖原分解。结果是磷酸葡萄糖增加、血糖上升。","points":["肾上腺素结合膜受体","激活腺苷酸环化酶","ATP（三磷酸腺苷）→cAMP（环腺苷一磷酸），cAMP升高","cAMP（环腺苷一磷酸）激活PKA（蛋白激酶A）","PKA（蛋白激酶A）激活糖原磷酸化酶激酶","糖原分解、血糖升高"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full81.jpg","imageExplain":"按图中自上而下的箭头读：受体→AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）→磷酸化酶激酶→糖原分解。","check":{"kind":"mcq","id":"bc14_check_80","q":"肾上腺素经cAMP（环腺苷一磷酸）升高血糖时，cAMP直接激活的是？","a":"B","e":"肾上腺素结合膜受体激活腺苷酸环化酶，ATP（三磷酸腺苷）分解为cAMP（环腺苷一磷酸）；cAMP升高后激活PKA（蛋白激酶A），PKA再激活糖原磷酸化酶激酶，最终促进糖原分解、血糖上升。","src":"本页自测","o":["A. 糖原磷酸化酶","B. 蛋白激酶A（PKA）","C. 糖原磷酸化酶激酶","D. 腺苷酸环化酶"],"oe":["A错误：糖原磷酸化酶是被磷酸化酶激酶激活的下游酶，不是cAMP直接激活对象。","B正确：cAMP直接激活PKA，再由PKA激活糖原磷酸化酶激酶。","C错误：糖原磷酸化酶激酶由PKA激活，位于cAMP→PKA的下游。","D错误：腺苷酸环化酶位于cAMP生成的上游，被G蛋白激活。"]}},{"i":81,"sec":"老师PPT逐页","title":"肾上腺素-cAMP级联放大","notes":"外界刺激经中枢神经传至肾上腺髓质，释放肾上腺素作用于肝细胞膜受体。信号沿AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）→磷酸化酶b激酶→糖原磷酸化酶逐级传递，每一级都放大数量。最终少量肾上腺素即可动员大量糖原，使葡萄糖大量入血。","points":["刺激→CNS→肾上腺髓质→肾上腺素","肾上腺素作用于肝细胞膜受体","AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）逐级传递","激活磷酸化酶b激酶","激活糖原磷酸化酶","级联放大可达万倍"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full82.jpg","imageExplain":"看图中每一级旁标注的放大倍数（如40×、10×、100×…）以及最终糖原→葡萄糖的方向。","check":{"kind":"mcq","id":"bc14_check_81","q":"肾上腺素-cAMP级联放大的生理意义是？","a":"A","e":"信号沿AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）→磷酸化酶b激酶→糖原磷酸化酶逐级传递，每一级都放大数量，级联放大可达万倍，最终少量肾上腺素即可动员大量糖原、使葡萄糖大量入血。","src":"本页自测","o":["A. 少量激素即可动员大量糖原，信号逐级放大","B. 使血糖迅速降低","C. 直接抑制糖原分解","D. 使信号逐级衰减以便精确控制"],"oe":["A正确：逐级放大使少量激素动员大量糖原，是级联放大的意义。","B错误：该通路促进糖原分解、血糖升高，不是降低血糖。","C错误：通路最终激活糖原磷酸化酶，促进而非抑制糖原分解。","D错误：级联是逐级放大而非衰减。"]}},{"i":82,"sec":"老师PPT逐页","title":"Gs-AC-cAMP-PKA七步通路","notes":"该页把Gs（刺激性G蛋白）偶联通路拆成七步：肾上腺素结合受体；Gs由GDP型转为GTP型；Gα激活腺苷酸环化酶；ATP（三磷酸腺苷）生成cAMP（环腺苷一磷酸）；cAMP激活PKA（蛋白激酶A）；PKA磷酸化底物；磷酸二酯酶把cAMP降解为5′-AMP而终止信号。七步串起来就是完整的第二信使通路。","points":["①激素结合受体","②Gs（刺激性G蛋白） GDP→GTP","③Gα激活AC（腺苷酸环化酶）","④ATP（三磷酸腺苷）→cAMP（环腺苷一磷酸）","⑤cAMP（环腺苷一磷酸）激活PKA（蛋白激酶A）","⑥PKA（蛋白激酶A）磷酸化底物","⑦PDE降解cAMP（环腺苷一磷酸）终止"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full83.jpg","imageExplain":"按①~⑦编号沿图追踪，注意Gα-GTP与AC（腺苷酸环化酶）的结合以及PDE对cAMP（环腺苷一磷酸）的降解箭头。","check":{"kind":"mcq","id":"bc14_check_82","q":"该页Gs-AC-cAMP-PKA七步通路中，第⑦步用于终止cAMP（环腺苷一磷酸）信号的是？","a":"B","e":"该页七步依次为：激素结合受体、Gs（刺激性G蛋白）由GDP型转GTP型、Gα激活AC（腺苷酸环化酶）、ATP（三磷酸腺苷）生成cAMP（环腺苷一磷酸）、cAMP激活PKA（蛋白激酶A）、PKA磷酸化底物、磷酸二酯酶把cAMP降解为5′-AMP而终止信号。","src":"本页自测","o":["A. Gα水解GTP","B. 磷酸二酯酶把cAMP降解为5′-AMP","C. 磷酸酶使受体去磷酸化","D. Gi抑制腺苷酸环化酶"],"oe":["A错误：Gα水解GTP是G蛋白失活事件，但本页所列第⑦步终止信号的是PDE降解cAMP。","B正确：第⑦步为磷酸二酯酶降解cAMP为5′-AMP，从而终止信号。","C错误：受体去磷酸化不是本页七步中的终止步骤。","D错误：Gi抑制AC属于另一类G蛋白调节，不是本页第⑦步。"]}},{"i":83,"sec":"老师PPT逐页","title":"磷酸肌醇途径：PIP2水解为IP3（三磷酸肌醇）与DAG（二酰甘油）","notes":"激素与受体结合后活化磷脂酶C（PLC）。PLC催化磷脂酰肌醇PI逐步磷酸化为PIP2，再水解PIP2生成IP3（三磷酸肌醇）和DAG（二酰甘油）。PIP2即磷脂酰肌醇4,5-二磷酸，IP3为肌醇1,4,5-三磷酸，DAG为二酰基甘油。","points":["激素-受体活化PLC（磷脂酶C）","PI→PIP2","PIP2水解为IP3（三磷酸肌醇）+DAG（二酰甘油）","IP3（三磷酸肌醇）为肌醇三磷酸","DAG（二酰甘油）为二酰基甘油"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full84.jpg","imageExplain":"看图中PIP2在PLC（磷脂酶C）作用下裂解为膜上的DAG（二酰甘油）和水溶性的IP3（三磷酸肌醇）两部分。","check":{"kind":"mcq","id":"bc14_check_83","q":"磷脂酶C（PLC）水解PIP2生成的两种产物是？","a":"A","e":"激素-受体活化PLC（磷脂酶C），PLC催化PI逐步磷酸化为PIP2，再水解PIP2生成IP3（肌醇1,4,5-三磷酸）和DAG（二酰基甘油）。","src":"本页自测","o":["A. IP3和DAG","B. cAMP和PPi","C. IP4和Ca2+","D. DAG和ATP"],"oe":["A正确：PIP2在PLC作用下水解为IP3和DAG。","B错误：cAMP和PPi由腺苷酸环化酶催化ATP生成，不是PLC水解PIP2的产物。","C错误：IP4是IP3进一步磷酸化的产物，且Ca2+不是PLC的直接产物。","D错误：DAG是产物之一，但ATP不是PLC水解PIP2的产物。"]}},{"i":84,"sec":"老师PPT逐页","title":"G蛋白-磷脂酶C-IP3/DAG（二酰甘油）通路图","notes":"受体激活G蛋白后激活磷脂酶C，PLC（磷脂酶C）分解PIP2产生DG和IP3（三磷酸肌醇）。IP3促使内质网释放Ca2+，使胞内Ca2+升高；DG与Ca2+共同激活蛋白激酶C（PKC）。PKC使底物蛋白磷酸化，或改变钙调蛋白等钙传感器的构象而产生效应。IP4是IP3进一步磷酸化的产物。","points":["G蛋白激活PLC（磷脂酶C）","PIP2→DG+IP3（三磷酸肌醇）","IP3（三磷酸肌醇）使内质网释放Ca2+","DG与Ca2+激活PKC（蛋白激酶C）","PKC（蛋白激酶C）磷酸化底物产生效应","IP4由IP3（三磷酸肌醇）磷酸化生成"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full85.jpg","imageExplain":"沿图中受体→G蛋白→PLC（磷脂酶C）→PIP2分支为DG与IP3（三磷酸肌醇）；IP3指向内质网释放Ca2+，DG与Ca2+共同指向PKC（蛋白激酶C）。","check":{"kind":"mcq","id":"bc14_check_84","q":"在G蛋白-磷脂酶C-IP3/DAG（二酰甘油）通路中，IP3（三磷酸肌醇）的直接作用是？","a":"B","e":"PLC（磷脂酶C）分解PIP2产生DG和IP3（三磷酸肌醇）；IP3促使内质网释放Ca2+使胞内Ca2+升高，DG与Ca2+共同激活PKC（蛋白激酶C）；IP4由IP3进一步磷酸化生成。","src":"本页自测","o":["A. 激活腺苷酸环化酶","B. 促使内质网释放Ca2+，使胞内Ca2+升高","C. 激活受体酪氨酸激酶","D. 与Ca2+共同激活蛋白激酶C"],"oe":["A错误：激活腺苷酸环化酶是Gs通路的事件，IP3不激活AC。","B正确：IP3促使内质网释放Ca2+，升高胞内Ca2+。","C错误：受体酪氨酸激酶由配体激活，不是IP3的作用。","D错误：与Ca2+共同激活PKC的是DG，不是IP3。"]}},{"i":85,"sec":"老师PPT逐页","title":"Gq-PLC-IP3/DAG-Ca2+-PKC通路","notes":"激素结合受体后激活Gq（Gq蛋白），Gq由GDP型转为GTP型并激活PLC（磷脂酶C）。PLC水解PIP2生成IP3（三磷酸肌醇）和DAG（二酰甘油）；IP3使内质网释放Ca2+，DAG与Ca2+共同激活PKC（蛋白激酶C）。PKC再磷酸化下游底物，调节细胞功能。","points":["受体激活Gq（Gq蛋白）","Gq（Gq蛋白）激活PLC（磷脂酶C）","PIP2→IP3（三磷酸肌醇）+DAG（二酰甘油）","IP3（三磷酸肌醇）动员内质网Ca2+","DAG（二酰甘油）+Ca2+激活PKC（蛋白激酶C）","PKC（蛋白激酶C）磷酸化底物"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full86.jpg","imageExplain":"看Gq（Gq蛋白）→PLC（磷脂酶C）→PIP2分支，以及IP3（三磷酸肌醇）→Ca2+、DAG（二酰甘油）+Ca2+→PKC（蛋白激酶C）两条汇合路径。","check":{"kind":"mcq","id":"bc14_check_85","q":"Gq（Gq蛋白）偶联通路的正确顺序是？","a":"A","e":"激素结合受体后激活Gq（Gq蛋白），Gq由GDP型转GTP型并激活PLC（磷脂酶C）；PLC水解PIP2生成IP3（三磷酸肌醇）和DAG（二酰甘油），IP3使内质网释放Ca2+，DAG与Ca2+共同激活PKC（蛋白激酶C）。","src":"本页自测","o":["A. Gq→PLC→PIP2→IP3+DAG→Ca2+/PKC","B. Gs→AC→cAMP→PKA","C. Gq→AC→cAMP→PKA","D. Gq→RTK→IRS→PI3K"],"oe":["A正确：Gq→PLC→PIP2→IP3+DAG→Ca2+/PKC，符合本页通路。","B错误：Gs→AC→cAMP→PKA是cAMP通路，不是Gq通路。","C错误：Gq激活的是PLC而非腺苷酸环化酶。","D错误：RTK→IRS→PI3K属于受体酪氨酸激酶通路。"]}},{"i":86,"sec":"老师PPT逐页","title":"Ca2+信号、EF手型与钙调蛋白","notes":"钙结合蛋白具有重复出现的螺旋区-泡区-螺旋区结构，即EF手型。实验表明离体蛙心只有在含Ca2+的循环液中才能继续搏动，说明Ca2+对收缩必不可少。细胞收缩、胞吐、胞饮、糖原代谢、神经递质释放和细胞死亡都与Ca2+有关，Ca2+因此是重要的细胞内信号。","points":["EF手型为螺旋-泡-螺旋结构","Ca2+是许多通路的胞内信号","离体蛙心搏动依赖Ca2+","Ca2+参与收缩与胞吐","Ca2+参与糖原代谢与递质释放","钙调蛋白是重要钙传感器"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full87.jpg","imageExplain":"看图中EF手型结构域与Ca2+结合位点，以及钙调蛋白结合Ca2+后构象变化的示意。","check":{"kind":"mcq","id":"bc14_check_86","q":"EF手型结构是指？","a":"A","e":"钙结合蛋白具有重复出现的螺旋区-泡区-螺旋区结构，即EF手型；钙调蛋白是重要的钙传感器，Ca2+参与收缩、胞吐、糖原代谢、递质释放等。","src":"本页自测","o":["A. 重复的螺旋区-泡区-螺旋区结构，是钙结合蛋白的结构域","B. 一条肽链七次跨膜的受体结构","C. 由α2β2组成的四聚体结构","D. 结合DNA的锌指结构"],"oe":["A正确：EF手型为螺旋-泡-螺旋重复结构，是钙结合蛋白的结构域。","B错误：七次跨膜是一条肽链的G蛋白偶联受体特征。","C错误：α2β2四聚体是胰岛素受体结构。","D错误：锌指是DNA结合结构，不是EF手型。"]}},{"i":87,"sec":"老师PPT逐页","title":"Ca2+结合蛋白（EF手型）示意","notes":"本页为低分辨率线稿，红色Ca标出钙离子结合位点，右图可见EF字样，示意钙调蛋白等EF手型结构域结合Ca2+。图像细节模糊，不能可靠辨认螺旋编号或具体残基。学习时应结合上一页文字理解EF手型的螺旋-泡-螺旋构象。","points":["示意EF手型结合Ca2+","红色Ca标记结合位点","图为低清扫描","细节不足以辨认残基编号"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full88.jpg","imageExplain":"注意红色Ca标记所在的环区，即EF手型中结合钙离子的位置；不要尝试从模糊图中读具体残基。","check":{"kind":"mcq","id":"bc14_check_87","q":"关于EF手型结合Ca2+示意图的说明，正确的是？","a":"A","e":"本页为低分辨率线稿，红色Ca标出钙离子结合位点，右图可见EF字样；图像细节模糊，不能可靠辨认螺旋编号或具体残基，应结合上一页文字理解EF手型。","src":"本页自测","o":["A. 红色Ca标记EF手型环区的钙离子结合位点","B. 从图中可清晰读出具体残基编号","C. 该图为高分辨率结构图，可确定螺旋编号","D. 图中Ca标记的是DNA结合位点"],"oe":["A正确：红色Ca标记所在环区即EF手型结合钙离子的位置。","B错误：该图为低清扫描，细节不足以辨认残基编号。","C错误：图为低分辨率，无法可靠确定螺旋编号。","D错误：EF手型结合的是Ca2+，不是DNA。"]}},{"i":88,"sec":"老师PPT逐页","title":"受体酪氨酸激酶（RTK）途径","notes":"激素结合到本质为酪氨酸激酶的受体上，使受体本身的酪氨酸残基磷酸化。自身磷酸化又进一步增强受体酪氨酸激酶活性，从而磷酸化下游底物。这是第三条主要信号途径，胰岛素受体是其代表。","points":["受体本身具酪氨酸激酶活性","配体结合引起受体自磷酸化","自磷酸化增强激酶活性","进一步磷酸化底物Tyr残基","代表为胰岛素受体"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full89.jpg","imageExplain":"看图中配体结合后受体二聚化、胞内激酶区相互磷酸化的示意。","check":{"kind":"mcq","id":"bc14_check_88","q":"受体酪氨酸激酶（RTK）途径的特点是？","a":"A","e":"激素结合到本质为酪氨酸激酶的受体上，使受体本身的酪氨酸残基磷酸化；自身磷酸化进一步增强受体酪氨酸激酶活性，从而磷酸化下游底物；胰岛素受体为代表。","src":"本页自测","o":["A. 配体结合引起受体自身酪氨酸磷酸化，并增强受体激酶活性","B. 需G蛋白介导后再激活腺苷酸环化酶","C. 受体位于核内，调控基因转录","D. 受体本身是配体门控离子通道"],"oe":["A正确：配体结合引起受体自磷酸化，自磷酸化又增强激酶活性。","B错误：需G蛋白介导再激活AC的是G蛋白偶联受体通路。","C错误：位于核内调控转录的是核受体，不是RTK。","D错误：配体门控离子通道属于离子通道型受体。"]}},{"i":89,"sec":"老师PPT逐页","title":"胰岛素受体的结构","notes":"胰岛素受体由两个α链和两个β链组成：α链位于细胞外侧并含胰岛素结合位点，β链穿过细胞膜且胞质侧含酪氨酸激酶结构域。胰岛素结合后打开受体酪氨酸激酶活性，使β链上的酪氨酸残基自动磷酸化，即自身磷酸化。","points":["由α2β2四条链组成","α链在胞外、含胰岛素结合位点","β链跨膜、胞内带酪氨酸激酶域","胰岛素结合激活激酶活性","β链酪氨酸自身磷酸化"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full90.jpg","imageExplain":"看图中两个α链在膜外、两个β链跨膜，以及β链胞内段的激酶域和自磷酸化位点。","check":{"kind":"mcq","id":"bc14_check_89","q":"关于胰岛素受体的结构，正确的是？","a":"A","e":"胰岛素受体由两个α链和两个β链组成：α链位于细胞外侧并含胰岛素结合位点，β链穿过细胞膜且胞质侧含酪氨酸激酶结构域；胰岛素结合后β链酪氨酸自身磷酸化。","src":"本页自测","o":["A. 由α2β2组成，α链在胞外含胰岛素结合位点，β链跨膜且胞内带酪氨酸激酶域","B. 由α2β2组成，β链位于胞外并结合胰岛素","C. 为单条肽链七次跨膜","D. 由R2C2四个亚基组成"],"oe":["A正确：α2β2，α链胞外结合胰岛素，β链跨膜且胞内具酪氨酸激酶域。","B错误：结合胰岛素的是胞外α链，不是β链。","C错误：单条肽链七次跨膜是G蛋白偶联受体的结构。","D错误：R2C2是PKA的四聚体组成，不是胰岛素受体。"]}},{"i":90,"sec":"老师PPT逐页","title":"核受体途径：慢反应与诱导酶合成","notes":"类固醇激素先进入细胞，与胞浆受体形成激素-受体复合物，再进入细胞核。受体本身是结合DNA的蛋白质，被激素激活后转变成转录增强子，去除抑制蛋白的作用，使特定基因表达增强。该过程起效慢，通过诱导酶蛋白合成改变细胞功能。","points":["类固醇激素可进入细胞","先与胞浆受体结合","复合物转入细胞核","受体结合DNA、充当转录增强子","去除抑制蛋白、增强基因表达","反应慢，依赖新酶合成"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full91.jpg","imageExplain":"按图中激素入胞→胞浆受体→入核→结合DNA→基因表达→酶蛋白的纵向流程阅读。","check":{"kind":"mcq","id":"bc14_check_90","q":"类固醇激素与胞浆受体结合后，激素-受体复合物的作用是？","a":"B","e":"类固醇激素进入细胞后与胞浆受体形成复合物，再进入细胞核；受体本身是结合DNA的蛋白质，被激活后转变成转录增强子，去除抑制蛋白的作用，使特定基因表达增强，起效慢。","src":"本页自测","o":["A. 直接开放离子通道","B. 转入核内，结合DNA充当转录增强子，增强基因表达","C. 激活腺苷酸环化酶生成cAMP","D. 激活磷脂酶C生成IP3"],"oe":["A错误：直接开放离子通道是离子通道型膜受体的作用。","B正确：复合物入核，结合DNA充当转录增强子，增强基因表达。","C错误：生成cAMP由膜受体-Gs-AC通路完成，不是该复合物的作用。","D错误：生成IP3由Gq-PLC通路完成。"]}},{"i":91,"sec":"老师PPT逐页","title":"类固醇激素-核受体作用示意","notes":"该图用H表示类固醇激素、R表示受体，展示激素进入细胞后与受体结合，穿过核膜进入核内。复合物结合DNA并促进mRNA生成，mRNA出核翻译为酶蛋白，从而改变细胞代谢。图示强调激素信号最终转化为基因表达的改变。","points":["H为类固醇激素，R为受体","激素-受体复合物过核膜","在核内促进mRNA生成","mRNA翻译为酶蛋白","效应通过基因表达实现"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full92.jpg","imageExplain":"看图中H与R结合后跨过核膜，以及核内生成mRNA、胞质翻译成酶蛋白的路径。","check":{"kind":"mcq","id":"bc14_check_91","q":"类固醇激素-核受体示意图中，核内生成mRNA之后的去向是？","a":"B","e":"该图用H表示类固醇激素、R表示受体，复合物结合DNA促进mRNA生成，mRNA出核翻译为酶蛋白，从而改变细胞代谢，效应通过基因表达实现。","src":"本页自测","o":["A. 在核内直接降解","B. 出核翻译为酶蛋白，从而改变细胞代谢","C. 转化为cAMP","D. 结合到细胞膜受体上"],"oe":["A错误：mRNA并非在核内直接降解，而是出核参与翻译。","B正确：mRNA出核翻译为酶蛋白，改变细胞代谢。","C错误：mRNA不转化为cAMP，cAMP是膜受体通路的第二信使。","D错误：mRNA在胞质翻译，不结合细胞膜受体。"]}},{"i":92,"sec":"老师PPT逐页","title":"类固醇/甲状腺激素核受体的四步作用","notes":"该页把核受体通路概括为四步：激素经血清结合蛋白运输并扩散入胞；与核受体结合形成二聚体；二聚体结合DNA上的激素反应元件HRE，调控相邻基因转录；生成的mRNA翻译为新蛋白，改变细胞功能。四步体现了慢而持久的调节特点。","points":["①激素经运输扩散入胞","②与核受体结合成二聚体","③结合HRE调控转录","④mRNA翻译为新蛋白","改变细胞功能、起效慢"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full93.jpg","imageExplain":"沿图中激素入胞→受体二聚体→HRE→转录→mRNA→新蛋白的四步顺序阅读。","check":{"kind":"mcq","id":"bc14_check_92","q":"类固醇/甲状腺激素核受体通路中，受体二聚体结合的DNA序列称为？","a":"A","e":"核受体通路四步为：激素经血清结合蛋白运输并扩散入胞、与核受体结合成二聚体、二聚体结合DNA上的激素反应元件HRE调控相邻基因转录、mRNA翻译为新蛋白。","src":"本页自测","o":["A. 激素反应元件（HRE）","B. TATA框","C. 沉默子","D. 操纵基因"],"oe":["A正确：二聚体结合DNA上的激素反应元件HRE，调控相邻基因转录。","B错误：TATA框是转录起始的启动子元件，不是本页所述受体二聚体的结合位点。","C错误：本页强调的是增强转录，结合的是HRE而非沉默子。","D错误：操纵基因是原核操纵子中的调控序列，不适用于此处。"]}},{"i":93,"sec":"老师PPT逐页","title":"表17-6 一些激素的作用方式","notes":"本页引用教材P581表17-6，汇总多种激素的作用方式，把激素与其受体类型、信号通路和主要效应对应起来。它是前面各条通路的归纳表，可用于快速检索某激素走cAMP（环腺苷一磷酸）、IP3（三磷酸肌醇）/Ca2+、酪氨酸激酶还是核受体途径。","points":["教材P581表17-6","汇总激素的作用方式","对应受体类型与信号通路","便于比较不同激素机制"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full94.jpg","imageExplain":"看表格的行列：一列是激素，另一列是受体/通路或效应，按行查找即可对应机制。","check":{"kind":"mcq","id":"bc14_check_93","q":"教材表17-6（本页）的主要用途是？","a":"A","e":"该表引用教材P581表17-6，汇总多种激素的作用方式，把激素与其受体类型、信号通路和主要效应对应起来，便于快速检索某激素走cAMP（环腺苷一磷酸）、IP3（三磷酸肌醇）/Ca2+、酪氨酸激酶还是核受体途径。","src":"本页自测","o":["A. 汇总激素与受体类型、信号通路及主要效应的对应关系","B. 列出糖酵解各步的自由能变化","C. 给出遗传密码子表","D. 列出常见脂肪酸的熔点"],"oe":["A正确：该表汇总激素与受体类型、信号通路及效应的对应关系。","B错误：糖酵解自由能属于代谢章节内容，不是该表。","C错误：遗传密码子表属于核酸/翻译内容。","D错误：脂肪酸熔点属于脂质内容。"]}},{"i":94,"sec":"老师PPT逐页","title":"激素分泌的调节","notes":"激素分泌受多层次调节：神经轴从上到下接受神经系统和各级刺激，从下到上则有长、短、超短负反馈。另有分步剪裁和多元调控机制。这些机制共同把激素水平维持在适宜范围。","points":["神经轴自上而下传递刺激","负反馈自下而上","负反馈分长、短、超短","存在分步剪裁","存在多元调控"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full95.jpg","imageExplain":"看图中神经轴上下箭头与长/短/超短反馈回路的方向。","check":{"kind":"mcq","id":"bc14_check_94","q":"激素分泌的多层次调节中，负反馈的方向是？","a":"B","e":"神经轴自上而下传递刺激，负反馈则自下而上，并分为长、短、超短负反馈；另有分步剪裁和多元调控，共同把激素水平维持在适宜范围。","src":"本页自测","o":["A. 自上而下","B. 自下而上","C. 仅在同一层次横向进行","D. 无方向性"],"oe":["A错误：自上而下是神经轴传递刺激的方向，不是负反馈方向。","B正确：负反馈自下而上，分为长、短、超短负反馈。","C错误：负反馈是跨层次的环路，不是仅横向进行。","D错误：负反馈具有明确的自下而上方向。"]}},{"i":95,"sec":"老师PPT逐页","title":"神经内分泌—垂体—靶腺总览","notes":"该图展示四级级联：环境与中枢神经→下丘脑释放激素→垂体前叶六种促激素或后叶催产素、抗利尿激素→第二靶点（肾上腺皮质、甲状腺、性腺、胰岛、髓质）→最终靶组织。图中标注了ACTH（促肾上腺皮质激素）等激素的分子量。它把分散的轴系整合成一张总览。","points":["四级级联结构","下丘脑释放激素为第一级","垂体前叶六种促激素","垂体后叶释放催产素/ADH（抗利尿激素）","第二靶点为外周内分泌腺","最终作用于靶组织"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full96.jpg","imageExplain":"从上到下追踪环境/CNS→下丘脑→垂体→外周腺→靶组织，并区分前叶促激素与后叶直接释放。","check":{"kind":"mcq","id":"bc14_check_95","q":"在神经内分泌—垂体—靶腺级联中，垂体前叶释放的是？","a":"A","e":"该图展示四级级联：下丘脑释放激素→垂体前叶六种促激素（或后叶释放催产素、抗利尿激素）→第二靶点（肾上腺皮质、甲状腺、性腺、胰岛、髓质）→最终靶组织。","src":"本页自测","o":["A. 六种促激素","B. 催产素和抗利尿激素","C. 甲状腺激素","D. 胰岛素"],"oe":["A正确：垂体前叶释放六种促激素。","B错误：催产素和抗利尿激素由垂体后叶释放，不是前叶。","C错误：甲状腺激素由甲状腺分泌，不是垂体前叶。","D错误：胰岛素由胰岛β细胞分泌。"]}},{"i":96,"sec":"老师PPT逐页","title":"植物激素","notes":"植物激素包括生长素、赤霉素、细胞激动素、脱落酸和乙烯。天然生长素是吲哚乙酸；赤霉素促进茎叶生长、打破休眠、促进萌发并防止果实脱落；脱落酸促进脱叶脱果，存在于衰老和休眠器官中；乙烯促进成熟。它们共同调控植物生长发育。","points":["生长素：天然为吲哚乙酸","赤霉素：促茎叶生长、打破休眠","细胞激动素（细胞分裂素）","脱落酸：促脱叶脱果、与休眠有关","乙烯：促进成熟"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full97.jpg","imageExplain":"看图中五类植物激素的名称与代表性作用标注。","check":{"kind":"mcq","id":"bc14_check_96","q":"天然生长素的化学本质是？","a":"A","e":"植物激素包括生长素、赤霉素、细胞激动素、脱落酸和乙烯；天然生长素是吲哚乙酸，赤霉素促进茎叶生长，脱落酸促进脱叶脱果，乙烯促进成熟。","src":"本页自测","o":["A. 吲哚乙酸","B. 赤霉素","C. 脱落酸","D. 乙烯"],"oe":["A正确：天然生长素是吲哚乙酸。","B错误：赤霉素是另一类植物激素，不是天然生长素。","C错误：脱落酸促进脱叶脱果、与休眠有关。","D错误：乙烯促进果实成熟。"]}},{"i":97,"sec":"老师PPT逐页","title":"昆虫激素","notes":"昆虫激素可分为发育激素、性激素和变色激素。发育激素中，保幼激素抑制成虫特征出现，蜕皮激素、鞣化激素、羽化激素参与蜕皮与变态，脑激素调节发育激素。性激素中有些是外激素（信息素），变色激素参与保护色和警戒色的形成。","points":["发育激素：保幼激素抑制成虫特征","蜕皮激素/鞣化激素/羽化激素","脑激素调节发育激素","性激素含外激素（信息素）","变色激素形成保护色/警戒色"],"fig":"","page":null,"anim":null,"img":"assets/img/bc14/full98.jpg","imageExplain":"看图中昆虫激素按发育、性、变色三类的分支及保幼激素与蜕皮激素的相互拮抗关系。","check":{"kind":"mcq","id":"bc14_check_97","q":"昆虫保幼激素的主要作用是？","a":"A","e":"昆虫发育激素中，保幼激素抑制成虫特征出现；蜕皮激素、鞣化激素、羽化激素参与蜕皮与变态；脑激素调节发育激素；性激素中有些是外激素；变色激素参与保护色和警戒色形成。","src":"本页自测","o":["A. 抑制成虫特征出现","B. 促进蜕皮","C. 形成保护色","D. 作为性外激素吸引异性"],"oe":["A正确：保幼激素抑制成虫特征出现。","B错误：促进蜕皮的是蜕皮激素等，不是保幼激素。","C错误：形成保护色的是变色激素。","D错误：作为性外激素的是部分性激素，不是保幼激素。"]}},{"title":"AI主讲1：激素总览","sec":"第14章 · AI主讲","notes":"激素是由内分泌腺/细胞分泌、经体液运输、作用于靶细胞的微量高效信息分子；分内分泌、旁分泌、自分泌。激素不供能，调节代谢/生长/生殖。","points":["微量高效","经体液运输","靶细胞受体","内分泌/旁分泌/自分泌"],"img":"assets/img/bc14/full2.jpg","imageExplain":"看激素分泌→血液→靶细胞。","srcType":"白话辅助","role":"主线","i":98,"check":{"kind":"mcq","id":"bc14_check_98","q":"关于激素的叙述，正确的是？","a":"A","e":"激素由内分泌腺/细胞分泌、经体液运输、作用于靶细胞的受体，是微量高效的信息分子；分内分泌、旁分泌、自分泌，不供能，只调节代谢、生长和生殖。","src":"本页自测","o":["A. 激素是微量高效的信息分子，不直接供能","B. 激素可作为能源物质为细胞供能","C. 激素只能由内分泌腺分泌并作用于自身","D. 激素通过神经纤维运输到靶细胞"],"oe":["A正确：激素微量高效，作为信息分子不直接供能。","B错误：激素不供能，只起调节作用。","C错误：激素可经内分泌、旁分泌、自分泌等方式作用，并非只作用于自身。","D错误：激素经体液（血液）运输，不是经神经纤维运输。"]},"tableTitle":"激素信号常用缩写","table":[["缩写","中文"],["cAMP","环腺苷一磷酸"],["PKA","蛋白激酶A"],["AC","腺苷酸环化酶"],["PLC","磷脂酶C"],["IP3","三磷酸肌醇"],["DAG","二酰甘油"],["PKC","蛋白激酶C"],["RTK","受体酪氨酸激酶"],["GLUT4","葡萄糖转运体4"],["PTH","甲状旁腺激素"],["CT","降钙素"],["T3/T4","三碘甲状腺原氨酸/甲状腺素"]]},{"title":"AI主讲2：激素分类与分泌","sec":"第14章 · AI主讲","notes":"按化学本质：多肽/蛋白、氨基酸衍生物、固醇、脂肪酸衍生物。按溶解性：水溶性（膜受体）和脂溶性（核受体）。分泌受神经/负反馈调节。","points":["多肽/胺/固醇/脂肪酸","水溶性→膜受体","脂溶性→核受体","负反馈"],"img":"assets/img/bc14/full3.jpg","imageExplain":"看激素化学本质与受体位置。","srcType":"白话辅助","role":"主线","i":99,"check":{"kind":"mcq","id":"bc14_check_99","q":"按溶解性分类，脂溶性激素通常与哪类受体结合？","a":"B","e":"按溶解性，水溶性激素用膜受体，脂溶性激素用核受体；按化学本质分多肽/蛋白、氨基酸衍生物、固醇和脂肪酸衍生物，分泌受神经和负反馈调节。","src":"本页自测","o":["A. 膜受体","B. 核受体","C. 离子通道型受体","D. G蛋白偶联受体"],"oe":["A错误：水溶性激素通常用膜受体。","B正确：脂溶性激素通常与核受体结合。","C错误：离子通道型受体是膜受体的一种，主要接受神经递质。","D错误：G蛋白偶联受体属于膜受体，主要介导水溶性激素信号。"]}},{"title":"AI主讲3：下丘脑-垂体轴","sec":"第14章 · AI主讲","notes":"下丘脑释放/抑制因子→腺垂体→靶腺→激素；负反馈。神经垂体储存ADH（抗利尿激素）/催产素。三短轴：下丘脑-垂体-甲状腺/肾上腺/性腺。","points":["下丘脑→垂体→靶腺","负反馈","神经垂体储存ADH（抗利尿激素）/OT（催产素）"],"img":"assets/img/bc14/full8.jpg","imageExplain":"看三级/四级级联。","srcType":"白话辅助","role":"主线","i":100,"check":{"kind":"mcq","id":"bc14_check_100","q":"神经垂体储存和释放的激素是？","a":"A","e":"下丘脑释放/抑制因子作用于腺垂体，腺垂体再作用于靶腺；神经垂体储存并释放ADH（抗利尿激素）和催产素；三短轴为下丘脑-垂体-甲状腺/肾上腺/性腺。","src":"本页自测","o":["A. 抗利尿激素（ADH）和催产素","B. TSH和ACTH","C. 胰岛素和胰高血糖素","D. T3和T4"],"oe":["A正确：神经垂体储存和释放ADH与催产素。","B错误：TSH和ACTH由腺垂体分泌。","C错误：胰岛素和胰高血糖素由胰岛分泌。","D错误：T3和T4由甲状腺分泌。"]}},{"title":"AI主讲4：甲状腺激素","sec":"第14章 · AI主讲","notes":"甲状腺激素为含碘酪氨酸衍生物T3（三碘甲状腺原氨酸）/T4（甲状腺素）；合成需碘、甲状腺球蛋白、TPO；功能促代谢/产热/生长/发育；缺乏致甲减/呆小，过多甲亢。","points":["T3（三碘甲状腺原氨酸）/T4（甲状腺素）含碘","TPO碘化","促代谢/发育","甲减/甲亢"],"img":"assets/img/bc14/full22.jpg","imageExplain":"看甲状腺激素合成与T3（三碘甲状腺原氨酸）/T4（甲状腺素）。","srcType":"白话辅助","role":"主线","i":101,"check":{"kind":"mcq","id":"bc14_check_101","q":"甲状腺激素合成必需的元素是？","a":"B","e":"甲状腺激素为含碘酪氨酸衍生物T3（三碘甲状腺原氨酸）/T4（甲状腺素），合成需要碘、甲状腺球蛋白和TPO；功能为促代谢、产热、生长和发育，缺乏致甲减/呆小，过多致甲亢。","src":"本页自测","o":["A. 铁","B. 碘","C. 锌","D. 铜"],"oe":["A错误：铁主要参与血红蛋白等，不是甲状腺激素的特征元素。","B正确：T3/T4为含碘酪氨酸衍生物，合成必需碘。","C错误：锌是多种酶的辅因子，不是甲状腺激素合成必需的特征元素。","D错误：铜参与部分氧化酶，不是甲状腺激素合成的必需元素。"]}},{"title":"AI主讲5：肾上腺素","sec":"第14章 · AI主讲","notes":"肾上腺素是儿茶酚胺，来自Tyr；作用于α/β受体，升高cAMP（环腺苷一磷酸）/PKA（蛋白激酶A），促糖原分解、脂解、心率↑、血管收缩。","points":["Tyr衍生","α/β受体","cAMP（环腺苷一磷酸）/PKA（蛋白激酶A）","升糖/心血管"],"img":"assets/img/bc14/full26.jpg","imageExplain":"看肾上腺素信号通路。","srcType":"白话辅助","role":"主线","i":102,"check":{"kind":"mcq","id":"bc14_check_102","q":"肾上腺素由哪种氨基酸衍生而来？","a":"B","e":"肾上腺素是儿茶酚胺，来自酪氨酸；作用于α/β受体，升高cAMP（环腺苷一磷酸）/PKA（蛋白激酶A），促糖原分解、脂解，使心率升高、血管收缩。","src":"本页自测","o":["A. 色氨酸","B. 酪氨酸","C. 组氨酸","D. 谷氨酸"],"oe":["A错误：色氨酸是5-羟色胺等的前体，不是肾上腺素。","B正确：肾上腺素为儿茶酚胺，由酪氨酸衍生。","C错误：组氨酸是组胺的前体。","D错误：谷氨酸不是儿茶酚胺类激素的前体。"]}},{"title":"AI主讲6：胰岛素与胰高血糖素","sec":"第14章 · AI主讲","notes":"胰岛素由β细胞分泌，A/B链二硫键；促GLUT4（葡萄糖转运体4）转位、糖原合成、脂合成，降血糖。胰高血糖素由α细胞分泌，升血糖。","points":["胰岛素降糖","GLUT4（葡萄糖转运体4）","A/B链","胰高血糖素升糖"],"img":"assets/img/bc14/full49.jpg","imageExplain":"看胰岛素A/B链与分泌。","srcType":"白话辅助","role":"主线","i":103,"check":{"kind":"mcq","id":"bc14_check_103","q":"胰岛素降低血糖主要通过促进哪种葡萄糖转运体转位？","a":"C","e":"胰岛素由β细胞分泌，含A/B链二硫键，促GLUT4（葡萄糖转运体4）转位、糖原合成和脂合成，从而降血糖；胰高血糖素由α细胞分泌，升高血糖。","src":"本页自测","o":["A. GLUT1","B. GLUT2","C. GLUT4","D. GLUT5"],"oe":["A错误：GLUT1广泛分布，主要介导基础葡萄糖摄取，非胰岛素诱导转位。","B错误：GLUT2多见于肝和胰岛β细胞，与葡萄糖感应有关。","C正确：胰岛素促进GLUT4转位，增加肌肉和脂肪组织摄取葡萄糖。","D错误：GLUT5主要转运果糖。"]}},{"title":"AI主讲7：类固醇与钙磷激素","sec":"第14章 · AI主讲","notes":"类固醇激素由胆固醇合成，脂溶性，核受体；糖皮质激素/盐皮质激素/性激素。PTH（甲状旁腺激素）升血钙、降血磷；降钙素降血钙。","points":["固醇→核受体","PTH（甲状旁腺激素）升钙","CT（降钙素）降钙","性激素"],"img":"assets/img/bc14/full56.jpg","imageExplain":"看类固醇合成与钙磷调节。","srcType":"白话辅助","role":"主线","i":104,"check":{"kind":"mcq","id":"bc14_check_104","q":"甲状旁腺激素（PTH）对血钙和血磷的影响是？","a":"A","e":"类固醇激素由胆固醇合成、脂溶性、作用于核受体；钙磷调节中PTH（甲状旁腺激素）升血钙、降血磷，降钙素（CT）降血钙。","src":"本页自测","o":["A. 升血钙、降血磷","B. 降血钙、升血磷","C. 升血钙、升血磷","D. 降血钙、降血磷"],"oe":["A正确：PTH升血钙、降血磷。","B错误：方向相反，PTH升高而非降低血钙。","C错误：PTH降低血磷，不是升高血磷。","D错误：PTH升高血钙，不是降低血钙。"]}},{"title":"AI主讲8：膜受体与cAMP（环腺苷一磷酸）","sec":"第14章 · AI主讲","notes":"水溶性激素结合膜受体；Gs（刺激性G蛋白）激活AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）↑→PKA（蛋白激酶A）；Gi（抑制性G蛋白）抑制AC。肾上腺素/胰高血糖素用cAMP通路，信号级联放大。","points":["膜受体","Gs（刺激性G蛋白）/Gi（抑制性G蛋白）","AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）","级联放大"],"img":"assets/img/bc14/full78.jpg","imageExplain":"看Gs-AC-cAMP-PKA七步。","srcType":"白话辅助","role":"主线","i":105,"check":{"kind":"mcq","id":"bc14_check_105","q":"关于Gs（刺激性G蛋白）和Gi（抑制性G蛋白）对腺苷酸环化酶的作用，正确的是？","a":"A","e":"水溶性激素结合膜受体，Gs（刺激性G蛋白）激活腺苷酸环化酶使cAMP（环腺苷一磷酸）升高、激活PKA（蛋白激酶A），Gi（抑制性G蛋白）则抑制AC（腺苷酸环化酶）；肾上腺素、胰高血糖素走cAMP通路并有级联放大。","src":"本页自测","o":["A. Gs激活AC，Gi抑制AC","B. Gs抑制AC，Gi激活AC","C. 两者都激活AC","D. 两者都抑制AC"],"oe":["A正确：Gs激活AC，Gi抑制AC。","B错误：两者作用相反，Gs是激活、Gi是抑制。","C错误：Gi抑制而非激活AC。","D错误：Gs激活而非抑制AC。"]}},{"title":"AI主讲9：IP3（三磷酸肌醇）/DAG（二酰甘油）与RTK（受体酪氨酸激酶）","sec":"第14章 · AI主讲","notes":"Gq（Gq蛋白）激活PLC（磷脂酶C）→IP3（三磷酸肌醇）+DAG（二酰甘油）；IP3促Ca2+释放，DAG激活PKC（蛋白激酶C）。胰岛素受体是RTK（受体酪氨酸激酶），自磷酸化→IRS（胰岛素受体底物）→PI3K（磷脂酰肌醇3激酶）/Akt→GLUT4（葡萄糖转运体4）。","points":["Gq（Gq蛋白）→PLC（磷脂酶C）","IP3（三磷酸肌醇） Ca2+","DAG（二酰甘油） PKC（蛋白激酶C）","RTK（受体酪氨酸激酶）→PI3K（磷脂酰肌醇3激酶）"],"img":"assets/img/bc14/full85.jpg","imageExplain":"看Gq（Gq蛋白）和胰岛素RTK（受体酪氨酸激酶）通路。","srcType":"白话辅助","role":"主线","i":106,"check":{"kind":"mcq","id":"bc14_check_106","q":"胰岛素受体（RTK）激活后经IRS（胰岛素受体底物）→PI3K（磷脂酰肌醇3激酶）/Akt促进哪种蛋白转位以摄取葡萄糖？","a":"A","e":"Gq（Gq蛋白）激活PLC（磷脂酶C）产生IP3（三磷酸肌醇）和DAG（二酰甘油），IP3促Ca2+释放、DAG激活PKC（蛋白激酶C）；胰岛素受体是RTK（受体酪氨酸激酶），自磷酸化后经IRS（胰岛素受体底物）→PI3K（磷脂酰肌醇3激酶）/Akt促进GLUT4（葡萄糖转运体4）转位。","src":"本页自测","o":["A. GLUT4","B. 胰岛素受体本身","C. 磷脂酶C","D. 蛋白激酶A"],"oe":["A正确：RTK→IRS→PI3K/Akt通路促进GLUT4转位。","B错误：胰岛素受体是信号起始的受体，不是被转位的葡萄糖转运体。","C错误：PLC是Gq通路的效应酶，不是葡萄糖转运体。","D错误：PKA是cAMP通路的激酶，不介导GLUT4转位。"]}},{"title":"AI主讲10：核受体与调节","sec":"第14章 · AI主讲","notes":"类固醇/甲状腺激素入细胞结合核受体，调控基因转录，反应慢。激素分泌受负反馈、神经调节、昼夜节律。","points":["核受体","基因转录","反应慢","负反馈"],"img":"assets/img/bc14/full92.jpg","imageExplain":"看核受体四步。","srcType":"白话辅助","role":"主线","i":107,"check":{"kind":"mcq","id":"bc14_check_107","q":"类固醇/甲状腺激素通过核受体调控基因转录，其反应特点是？","a":"B","e":"类固醇/甲状腺激素入细胞结合核受体，调控基因转录，需新合成蛋白，故反应慢而持久；激素分泌还受负反馈、神经调节和昼夜节律影响。","src":"本页自测","o":["A. 快而短暂","B. 慢而持久","C. 瞬时且不依赖蛋白合成","D. 直接改变已有酶的活性"],"oe":["A错误：快而短暂是膜受体-第二信使通路的特点。","B正确：核受体调控转录、依赖新蛋白合成，反应慢而持久。","C错误：该通路依赖基因转录和蛋白合成，并非瞬时且不依赖蛋白合成。","D错误：直接改变已有酶活性是cAMP等第二信使通路的特点。"]}},{"title":"原书精读1：激素分类","sec":"第14章 · AI主讲","notes":"按化学本质分多肽/蛋白、氨基酸衍生物、固醇、脂肪酸；按溶解性决定受体位置。","points":["多肽","胺","固醇","溶解性"],"img":"assets/img/bc14/full3.jpg","imageExplain":"看分类表。","table":"第14章 · 原书精读","srcType":"白话辅助","role":"主线","i":108,"check":{"kind":"mcq","id":"bc14_check_108","q":"激素按化学本质分类，下列哪一项不属于？","a":"D","e":"按化学本质分多肽/蛋白、氨基酸衍生物、固醇和脂肪酸衍生物；按溶解性决定受体位置，水溶性用膜受体、脂溶性用核受体。","src":"本页自测","o":["A. 多肽/蛋白质","B. 氨基酸衍生物","C. 固醇类","D. 核酸类"],"oe":["A错误：多肽/蛋白质是激素的化学本质类别之一。","B错误：氨基酸衍生物是激素的化学本质类别之一。","C错误：固醇类是激素的化学本质类别之一。","D正确：激素不包括核酸类，核酸不是激素的化学本质分类。"]}},{"title":"原书精读2：下丘脑-垂体","sec":"第14章 · AI主讲","notes":"三级轴：下丘脑→垂体→靶腺；负反馈；神经垂体储存ADH（抗利尿激素）/OT（催产素）。","points":["三级轴","负反馈","ADH（抗利尿激素）/OT（催产素）"],"img":"assets/img/bc14/full8.jpg","imageExplain":"看轴与反馈。","table":"第14章 · 原书精读","srcType":"白话辅助","role":"主线","i":109,"check":{"kind":"mcq","id":"bc14_check_109","q":"下丘脑-垂体-靶腺三级轴的正确顺序是？","a":"A","e":"三级轴为下丘脑→垂体→靶腺，伴有负反馈；神经垂体储存ADH（抗利尿激素）和催产素。","src":"本页自测","o":["A. 下丘脑→垂体→靶腺","B. 垂体→下丘脑→靶腺","C. 靶腺→垂体→下丘脑","D. 下丘脑→靶腺→垂体"],"oe":["A正确：三级轴顺序为下丘脑→垂体→靶腺。","B错误：垂体位于下丘脑下游，顺序颠倒。","C错误：靶腺位于最下游，不应排在首位。","D错误：垂体位于靶腺上游，不应排在靶腺之后。"]}},{"title":"原书精读3：胰岛素","sec":"第14章 · AI主讲","notes":"前胰岛素原→胰岛素原→C肽切除→A/B链二硫键；RTK（受体酪氨酸激酶）→PI3K（磷脂酰肌醇3激酶）/Akt→GLUT4（葡萄糖转运体4）。","points":["C肽","二硫键","RTK（受体酪氨酸激酶）","GLUT4（葡萄糖转运体4）"],"img":"assets/img/bc14/full49.jpg","imageExplain":"看胰岛素加工。","table":"第14章 · 原书精读","srcType":"白话辅助","role":"主线","i":110,"check":{"kind":"mcq","id":"bc14_check_110","q":"胰岛素原加工为胰岛素时被切除的片段是？","a":"A","e":"前胰岛素原→胰岛素原→切除C肽→形成A/B链二硫键；胰岛素经RTK（受体酪氨酸激酶）→PI3K（磷脂酰肌醇3激酶）/Akt→GLUT4（葡萄糖转运体4）发挥作用。","src":"本页自测","o":["A. C肽","B. A链","C. B链","D. 二硫键"],"oe":["A正确：胰岛素原加工时切除C肽，保留A、B链。","B错误：A链是成熟胰岛素保留的部分，不被切除。","C错误：B链是成熟胰岛素保留的部分，不被切除。","D错误：二硫键连接A、B链，是形成而非切除的对象。"]}},{"title":"原书精读4：信号通路","sec":"第14章 · AI主讲","notes":"cAMP（环腺苷一磷酸）/PKA（蛋白激酶A）、IP3（三磷酸肌醇）/DAG（二酰甘油）/Ca2+/PKC（蛋白激酶C）、RTK（受体酪氨酸激酶）、核受体四条主线。","points":["cAMP（环腺苷一磷酸）","IP3（三磷酸肌醇）/DAG（二酰甘油）","RTK（受体酪氨酸激酶）","核受体"],"img":"assets/img/bc14/full85.jpg","imageExplain":"看四条通路。","table":"第14章 · 原书精读","srcType":"白话辅助","role":"主线","i":111,"check":{"kind":"mcq","id":"bc14_check_111","q":"下列哪一条不属于本章四条信号主线？","a":"D","e":"本章四条信号主线为cAMP（环腺苷一磷酸）/PKA（蛋白激酶A）、IP3（三磷酸肌醇）/DAG（二酰甘油）/Ca2+/PKC（蛋白激酶C）、RTK（受体酪氨酸激酶）和核受体；磷酸戊糖途径属于糖代谢，不是信号转导主线。","src":"本页自测","o":["A. cAMP/PKA","B. IP3/DAG/Ca2+/PKC","C. 受体酪氨酸激酶（RTK）","D. 磷酸戊糖途径"],"oe":["A错误：cAMP/PKA是四条主线之一。","B错误：IP3/DAG/Ca2+/PKC是四条主线之一。","C错误：RTK是四条主线之一。","D正确：磷酸戊糖途径是糖代谢途径，不属于四条信号主线。"]}},{"title":"过程版1：激素分类","sec":"第14章 · 过程版","notes":"先看化学本质，再看溶解性→受体位置。","points":["多肽","固醇","膜/核受体"],"img":"","imageExplain":"","table":[["类型","受体"],["水溶性","膜受体"],["脂溶性","核受体"]],"srcType":"白话辅助","role":"主线","i":112,"check":{"kind":"mcq","id":"bc14_check_112","q":"过程版强调：判断激素与受体位置关系时，应先看？","a":"A","e":"过程版的学习顺序是：先看化学本质，再看溶解性，由溶解性推断受体位置（膜受体或核受体）。","src":"本页自测","o":["A. 化学本质与溶解性","B. 分子量大小","C. 是否含硫","D. 等电点"],"oe":["A正确：先看化学本质，再由溶解性推断受体位置。","B错误：分子量大小不能直接决定受体位置。","C错误：是否含硫与受体定位无直接关系。","D错误：等电点不是判断受体位置的依据。"]}},{"title":"过程版2：下丘脑-垂体","sec":"第14章 · 过程版","notes":"下丘脑因子→垂体激素→靶腺激素→负反馈。","points":["三级","负反馈"],"img":"","imageExplain":"","table":[["层级","激素"],["下丘脑","释放/抑制因子"],["腺垂体","TSH（促甲状腺激素）/ACTH（促肾上腺皮质激素）/FSH（促卵泡激素）/LH（黄体生成素）/GH（生长激素）"],["靶腺","T3（三碘甲状腺原氨酸）/T4（甲状腺素）/皮质醇/性激素"]],"srcType":"白话辅助","role":"主线","i":113,"check":{"kind":"mcq","id":"bc14_check_113","q":"下丘脑-垂体-靶腺轴的调节环路属于？","a":"B","e":"过程版强调：下丘脑因子→垂体激素→靶腺激素→负反馈，通过负反馈维持激素水平稳定。","src":"本页自测","o":["A. 正反馈","B. 负反馈","C. 无反馈","D. 仅前馈"],"oe":["A错误：正反馈会使偏离加剧，不是该轴的主要调节方式。","B正确：该轴通过负反馈维持激素水平稳定。","C错误：该轴存在明确的反馈调节。","D错误：除前馈外，负反馈是该轴的关键环节。"]}},{"title":"过程版3：cAMP（环腺苷一磷酸）通路","sec":"第14章 · 过程版","notes":"激素→受体→Gs（刺激性G蛋白）→AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）→磷酸化。","points":["Gs（刺激性G蛋白）","AC（腺苷酸环化酶）","cAMP（环腺苷一磷酸）","PKA（蛋白激酶A）"],"img":"","imageExplain":"","table":[["步骤","分子"],["1","激素-受体"],["2","Gs（刺激性G蛋白）"],["3","AC（腺苷酸环化酶）"],["4","cAMP（环腺苷一磷酸）"],["5","PKA（蛋白激酶A）"]],"srcType":"白话辅助","role":"主线","i":114,"check":{"kind":"mcq","id":"bc14_check_114","q":"cAMP（环腺苷一磷酸）通路过程版中，Gs（刺激性G蛋白）之后的效应酶是？","a":"A","e":"cAMP（环腺苷一磷酸）通路的过程为：激素→受体→Gs（刺激性G蛋白）→腺苷酸环化酶→cAMP→PKA（蛋白激酶A）→底物磷酸化。","src":"本页自测","o":["A. 腺苷酸环化酶（AC）","B. 磷脂酶C（PLC）","C. 蛋白激酶C（PKC）","D. 受体酪氨酸激酶（RTK）"],"oe":["A正确：Gs激活腺苷酸环化酶，AC再生成cAMP。","B错误：PLC是Gq通路的效应酶。","C错误：PKC位于DAG/Ca2+通路下游。","D错误：RTK属于另一条信号主线。"]}},{"title":"过程版4：核受体","sec":"第14章 · 过程版","notes":"脂溶性激素→入细胞→核受体→DNA→转录→慢反应。","points":["入细胞","核受体","转录","慢"],"img":"","imageExplain":"","table":[["步骤","事件"],["1","激素入细胞"],["2","结合核受体"],["3","调控基因"],["4","慢反应"]],"srcType":"白话辅助","role":"主线","i":115,"check":{"kind":"mcq","id":"bc14_check_115","q":"脂溶性激素核受体通路的最终效应是？","a":"A","e":"过程版：脂溶性激素→入细胞→核受体→DNA→转录→慢反应，最终通过改变基因表达产生效应。","src":"本页自测","o":["A. 改变基因转录，起效慢","B. 快速开放离子通道","C. 迅速生成cAMP","D. 立即激活PKA"],"oe":["A正确：核受体通路改变基因转录，起效慢。","B错误：快速开放离子通道是离子通道型受体的作用。","C错误：迅速生成cAMP是膜受体-cAMP通路的事件。","D错误：立即激活PKA属于cAMP通路。"]}},{"title":"变式1：水溶/脂溶","sec":"第14章 · AI主讲","notes":"水溶性用膜受体/第二信使；脂溶性用核受体/基因转录。","points":["水溶膜受体","脂溶核受体"],"img":"","imageExplain":"","table":"第14章 · 变式","srcType":"白话辅助","role":"主线","i":116,"check":{"kind":"mcq","id":"bc14_check_116","q":"水溶性激素的信号转导通常依赖？","a":"A","e":"变式强调：水溶性激素用膜受体/第二信使，脂溶性激素用核受体/基因转录。","src":"本页自测","o":["A. 膜受体与第二信使","B. 核受体与基因转录","C. 直接进入细胞核","D. 与DNA直接结合"],"oe":["A正确：水溶性激素不能自由入胞，依赖膜受体与第二信使。","B错误：核受体与基因转录对应脂溶性激素。","C错误：水溶性激素通常不进入细胞核。","D错误：与DNA直接结合的是核受体，属于脂溶性激素通路。"]}},{"title":"变式2：cAMP（环腺苷一磷酸） vs IP3（三磷酸肌醇）/DAG（二酰甘油）","sec":"第14章 · AI主讲","notes":"Gs（刺激性G蛋白）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）；Gq（Gq蛋白）→PLC（磷脂酶C）→IP3（三磷酸肌醇）/DAG（二酰甘油）→Ca2+/PKC（蛋白激酶C）。","points":["Gs（刺激性G蛋白） cAMP（环腺苷一磷酸）","Gq（Gq蛋白） IP3（三磷酸肌醇）","PKC（蛋白激酶C）"],"img":"","imageExplain":"","table":"第14章 · 变式","srcType":"白话辅助","role":"主线","i":117,"check":{"kind":"mcq","id":"bc14_check_117","q":"Gq（Gq蛋白）偶联受体激活后的第二信使是？","a":"B","e":"变式对比：Gs（刺激性G蛋白）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）；Gq（Gq蛋白）→PLC（磷脂酶C）→IP3（三磷酸肌醇）/DAG（二酰甘油）→Ca2+/PKC（蛋白激酶C）。","src":"本页自测","o":["A. cAMP","B. IP3和DAG","C. cGMP","D. ATP"],"oe":["A错误：cAMP是Gs-AC通路产生的第二信使。","B正确：Gq激活PLC，水解PIP2生成IP3和DAG。","C错误：cGMP不是该通路的第二信使。","D错误：ATP是底物/能量分子，不是第二信使。"]}},{"title":"变式3：胰岛素 vs 胰高血糖素","sec":"第14章 · AI主讲","notes":"胰岛素降糖；胰高血糖素升糖。","points":["胰岛素降","胰高升"],"img":"","imageExplain":"","table":"第14章 · 变式","srcType":"白话辅助","role":"主线","i":118,"check":{"kind":"mcq","id":"bc14_check_118","q":"关于胰岛素与胰高血糖素对血糖的作用，正确的是？","a":"A","e":"变式要点：胰岛素降低血糖，胰高血糖素升高血糖，二者作用相反。","src":"本页自测","o":["A. 胰岛素降糖，胰高血糖素升糖","B. 两者都升糖","C. 两者都降糖","D. 胰岛素升糖，胰高血糖素降糖"],"oe":["A正确：胰岛素降糖，胰高血糖素升糖。","B错误：胰岛素降低而非升高血糖。","C错误：胰高血糖素升高而非降低血糖。","D错误：两者作用说反了。"]}},{"title":"变式4：PTH（甲状旁腺激素） vs CT（降钙素）","sec":"第14章 · AI主讲","notes":"PTH（甲状旁腺激素）升血钙降血磷；CT（降钙素）降血钙。","points":["PTH（甲状旁腺激素）升钙","CT（降钙素）降钙"],"img":"","imageExplain":"","table":"第14章 · 变式","srcType":"白话辅助","role":"主线","i":119,"check":{"kind":"mcq","id":"bc14_check_119","q":"降钙素（CT）对血钙的作用是？","a":"B","e":"变式对比：PTH（甲状旁腺激素）升血钙、降血磷；CT（降钙素）降血钙。","src":"本页自测","o":["A. 升高血钙","B. 降低血钙","C. 对血钙无影响","D. 先升后降"],"oe":["A错误：升高血钙的是PTH。","B正确：降钙素降低血钙。","C错误：CT对血钙有明确降低作用。","D错误：CT的作用是降低血钙，不是先升后降。"]}},{"title":"变式5：甲状腺激素","sec":"第14章 · AI主讲","notes":"T3（三碘甲状腺原氨酸）/T4（甲状腺素）含碘，促代谢/发育；甲减/甲亢。","points":["T3（三碘甲状腺原氨酸）/T4（甲状腺素）","代谢","发育"],"img":"","imageExplain":"","table":"第14章 · 变式","srcType":"白话辅助","role":"主线","i":120,"check":{"kind":"mcq","id":"bc14_check_120","q":"甲状腺激素T3（三碘甲状腺原氨酸）/T4（甲状腺素）的化学本质是？","a":"A","e":"变式要点：T3（三碘甲状腺原氨酸）/T4（甲状腺素）含碘，是酪氨酸衍生物，促代谢和发育，异常可致甲减/甲亢。","src":"本页自测","o":["A. 含碘酪氨酸衍生物","B. 固醇类","C. 多肽","D. 脂肪酸衍生物"],"oe":["A正确：T3/T4为含碘酪氨酸衍生物。","B错误：固醇类是类固醇激素的化学本质。","C错误：多肽/蛋白质是胰岛素等激素的本质。","D错误：脂肪酸衍生物是前列腺素等的本质。"]}},{"title":"变式6：类固醇","sec":"第14章 · AI主讲","notes":"胆固醇→类固醇激素；核受体慢反应。","points":["胆固醇","核受体","慢"],"img":"","imageExplain":"","table":"第14章 · 变式","srcType":"白话辅助","role":"主线","i":121,"check":{"kind":"mcq","id":"bc14_check_121","q":"类固醇激素合成的原料是？","a":"A","e":"变式要点：胆固醇→类固醇激素，脂溶性，作用于核受体，反应慢。","src":"本页自测","o":["A. 胆固醇","B. 葡萄糖","C. 脂肪酸","D. 氨基酸"],"oe":["A正确：类固醇激素由胆固醇合成。","B错误：葡萄糖不是类固醇激素的合成原料。","C错误：脂肪酸可衍生前列腺素等，不是类固醇激素的主要原料。","D错误：氨基酸衍生胺类/肽类激素，不是类固醇激素的原料。"]}},{"title":"图卡：cAMP（环腺苷一磷酸）通路","sec":"第14章 · AI主讲","notes":"Gs（刺激性G蛋白）→AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A）。","points":["Gs（刺激性G蛋白）","AC（腺苷酸环化酶）","cAMP（环腺苷一磷酸）","PKA（蛋白激酶A）"],"img":"assets/img/bc14/full78.jpg","imageExplain":"看cAMP（环腺苷一磷酸）七步。","table":"第14章 · 图卡","srcType":"白话辅助","role":"主线","i":122,"check":{"kind":"mcq","id":"bc14_check_122","q":"cAMP（环腺苷一磷酸）通路图卡的核心顺序是？","a":"A","e":"图卡要点：Gs（刺激性G蛋白）→AC（腺苷酸环化酶）→cAMP（环腺苷一磷酸）→PKA（蛋白激酶A），即Gs激活腺苷酸环化酶，生成cAMP后激活PKA。","src":"本页自测","o":["A. Gs→AC→cAMP→PKA","B. Gq→PLC→IP3→PKC","C. RTK→IRS→PI3K","D. 核受体→转录"],"oe":["A正确：cAMP通路核心为Gs→AC→cAMP→PKA。","B错误：Gq→PLC→IP3→PKC是IP3/DAG通路。","C错误：RTK→IRS→PI3K是胰岛素RTK通路。","D错误：核受体→转录是核受体通路。"]}},{"title":"图卡：IP3（三磷酸肌醇）/DAG（二酰甘油）","sec":"第14章 · AI主讲","notes":"Gq（Gq蛋白）→PLC（磷脂酶C）→IP3（三磷酸肌醇）+DAG（二酰甘油）→Ca2+/PKC（蛋白激酶C）。","points":["Gq（Gq蛋白）","PLC（磷脂酶C）","IP3（三磷酸肌醇）","PKC（蛋白激酶C）"],"img":"assets/img/bc14/full85.jpg","imageExplain":"看Gq（Gq蛋白）通路。","table":"第14章 · 图卡","srcType":"白话辅助","role":"主线","i":123,"check":{"kind":"mcq","id":"bc14_check_123","q":"Gq（Gq蛋白）→PLC（磷脂酶C）通路中，生成IP3（三磷酸肌醇）和DAG（二酰甘油）的底物是？","a":"A","e":"图卡要点：Gq（Gq蛋白）→PLC（磷脂酶C）→IP3（三磷酸肌醇）+DAG（二酰甘油）→Ca2+/PKC（蛋白激酶C），PLC水解的底物是PIP2。","src":"本页自测","o":["A. PIP2","B. ATP","C. cAMP","D. 胆固醇"],"oe":["A正确：PLC水解PIP2生成IP3和DAG。","B错误：ATP是腺苷酸环化酶生成cAMP的底物。","C错误：cAMP是第二信使，不是PLC生成IP3/DAG的底物。","D错误：胆固醇是类固醇激素合成原料，不是PLC底物。"]}},{"title":"图卡：胰岛素RTK（受体酪氨酸激酶）","sec":"第14章 · AI主讲","notes":"胰岛素→RTK（受体酪氨酸激酶）→IRS（胰岛素受体底物）→PI3K（磷脂酰肌醇3激酶）→GLUT4（葡萄糖转运体4）。","points":["RTK（受体酪氨酸激酶）","PI3K（磷脂酰肌醇3激酶）","GLUT4（葡萄糖转运体4）"],"img":"assets/img/bc14/full89.jpg","imageExplain":"看胰岛素受体。","table":"第14章 · 图卡","srcType":"白话辅助","role":"主线","i":124,"check":{"kind":"mcq","id":"bc14_check_124","q":"胰岛素→RTK（受体酪氨酸激酶）→IRS（胰岛素受体底物）→PI3K（磷脂酰肌醇3激酶）之后，促进转位以摄取葡萄糖的是？","a":"A","e":"图卡要点：胰岛素→RTK（受体酪氨酸激酶）→IRS（胰岛素受体底物）→PI3K（磷脂酰肌醇3激酶）→GLUT4（葡萄糖转运体4），GLUT4转位增加葡萄糖摄取。","src":"本页自测","o":["A. GLUT4","B. GLUT2","C. PKA","D. PLC"],"oe":["A正确：该通路最终促进GLUT4转位。","B错误：GLUT2主要见于肝和胰岛β细胞。","C错误：PKA属于cAMP通路，不介导此转位。","D错误：PLC属于Gq通路。"]}},{"title":"图卡：核受体","sec":"第14章 · AI主讲","notes":"激素入细胞→核受体→基因转录。","points":["核受体","转录","慢"],"img":"assets/img/bc14/full92.jpg","imageExplain":"看核受体四步。","table":"第14章 · 图卡","srcType":"白话辅助","role":"主线","i":125,"check":{"kind":"mcq","id":"bc14_check_125","q":"核受体图卡的关键事件是？","a":"A","e":"图卡要点：激素入细胞→核受体→基因转录，反应慢。","src":"本页自测","o":["A. 激素入细胞→核受体→基因转录","B. 激素→膜受体→cAMP","C. 激素→PLC→IP3","D. 激素→RTK→自磷酸化"],"oe":["A正确：核受体通路关键为激素入胞、结合核受体并调控基因转录。","B错误：膜受体→cAMP属于cAMP通路。","C错误：PLC→IP3属于Gq通路。","D错误：RTK自磷酸化属于受体酪氨酸激酶通路。"]}},{"title":"图卡：甲状腺激素","sec":"第14章 · AI主讲","notes":"T3（三碘甲状腺原氨酸）/T4（甲状腺素）含碘，促代谢/发育。","points":["T3（三碘甲状腺原氨酸）/T4（甲状腺素）","碘","代谢"],"img":"assets/img/bc14/full22.jpg","imageExplain":"看甲状腺激素。","table":"第14章 · 图卡","srcType":"白话辅助","role":"主线","i":126,"check":{"kind":"mcq","id":"bc14_check_126","q":"关于甲状腺激素，下列叙述错误的是？","a":"D","e":"图卡要点：T3（三碘甲状腺原氨酸）/T4（甲状腺素）含碘，促代谢和发育；它通过核受体调控基因转录，而不是作为第二信使直接激活PKA（蛋白激酶A）。","src":"本页自测","o":["A. T3/T4含碘","B. 能促进代谢和产热","C. 能促进生长发育","D. 直接作为第二信使激活PKA"],"oe":["A错误：T3/T4确实含碘，此叙述正确。","B错误：甲状腺激素确实促进代谢和产热，此叙述正确。","C错误：甲状腺激素确实促进生长发育，此叙述正确。","D正确：甲状腺激素经核受体调控转录，不是直接激活PKA的第二信使。"]}},{"title":"图卡：下丘脑-垂体轴","sec":"第14章 · AI主讲","notes":"三级轴+负反馈。","points":["三级","负反馈"],"img":"assets/img/bc14/full8.jpg","imageExplain":"看轴。","table":"第14章 · 图卡","srcType":"白话辅助","role":"主线","i":127,"check":{"kind":"mcq","id":"bc14_check_127","q":"下丘脑-垂体轴的调节方式是？","a":"A","e":"图卡要点：下丘脑-垂体轴为三级级联，并伴有负反馈调节。","src":"本页自测","o":["A. 三级级联伴负反馈","B. 单级正反馈","C. 无反馈的开放环路","D. 仅靠旁分泌"],"oe":["A正确：该轴为三级级联并伴负反馈。","B错误：该轴以负反馈为主，不是单级正反馈。","C错误：该轴存在反馈调节，不是开放环路。","D错误：该轴是典型的内分泌轴，不仅靠旁分泌。"]}},{"title":"学习支持1：激素分类表","sec":"第14章 · 学习支持","notes":"多肽/胺/固醇/脂肪酸；膜/核受体。","points":["分类","受体"],"img":"","imageExplain":"","table":[["类型","例子"],["多肽","胰岛素"],["胺","肾上腺素"],["固醇","皮质醇"],["脂肪酸","前列腺素"]],"srcType":"白话辅助","role":"主线","i":128,"check":{"kind":"mcq","id":"bc14_check_128","q":"下列激素与受体位置的配对，错误的是？","a":"D","e":"学习支持表强调：多肽/胺类多用水溶性膜受体，固醇类/甲状腺激素用核受体；甲状腺激素应配核受体而非膜受体。","src":"本页自测","o":["A. 胰岛素—膜受体","B. 肾上腺素—膜受体","C. 类固醇激素—核受体","D. 甲状腺激素—膜受体"],"oe":["A错误：胰岛素为多肽激素，用膜受体，配对正确。","B错误：肾上腺素为胺类激素，用膜受体，配对正确。","C错误：类固醇激素脂溶性，用核受体，配对正确。","D正确：甲状腺激素虽含碘，但属脂溶性、经核受体起作用，配对为膜受体是错误的。"]}},{"title":"学习支持2：第二信使","sec":"第14章 · 学习支持","notes":"cAMP（环腺苷一磷酸）、IP3（三磷酸肌醇）、DAG（二酰甘油）、Ca2+。","points":["cAMP（环腺苷一磷酸）","IP3（三磷酸肌醇）","DAG（二酰甘油）","Ca"],"img":"","imageExplain":"","table":[["信使","来源"],["cAMP（环腺苷一磷酸）","AC（腺苷酸环化酶）"],["IP3（三磷酸肌醇）","PLC（磷脂酶C）"],["DAG（二酰甘油）","PLC（磷脂酶C）"],["Ca2+","IP3（三磷酸肌醇）"]],"srcType":"白话辅助","role":"主线","i":129,"check":{"kind":"mcq","id":"bc14_check_129","q":"下列全部属于第二信使的一组是？","a":"A","e":"学习支持页列出第二信使为cAMP（环腺苷一磷酸）、IP3（三磷酸肌醇）、DAG（二酰甘油）、Ca2+，它们把膜受体接受的信号传入细胞并引起效应。","src":"本页自测","o":["A. cAMP、IP3、DAG、Ca2+","B. ATP、ADP、AMP、cAMP","C. 葡萄糖、脂肪酸、氨基酸","D. DNA、RNA、蛋白质"],"oe":["A正确：cAMP、IP3、DAG、Ca2+均为第二信使。","B错误：ATP、ADP、AMP是能量/核苷酸分子，只有cAMP是第二信使。","C错误：葡萄糖、脂肪酸、氨基酸是代谢物/营养物质，不是第二信使。","D错误：DNA、RNA、蛋白质是遗传信息与功能大分子，不是第二信使。"]}},{"title":"学习支持3：血糖激素","sec":"第14章 · 学习支持","notes":"胰岛素降；胰高血糖素/肾上腺素/皮质醇升。","points":["胰岛素降","胰高升","皮质醇升"],"img":"","imageExplain":"","table":[["激素","血糖"],["胰岛素","↓"],["胰高血糖素","↑"],["肾上腺素","↑"],["皮质醇","↑"]],"srcType":"白话辅助","role":"主线","i":130,"check":{"kind":"mcq","id":"bc14_check_130","q":"下列哪种激素降低血糖？","a":"D","e":"学习支持页汇总：胰岛素降血糖；胰高血糖素、肾上腺素、皮质醇均升高血糖。","src":"本页自测","o":["A. 胰高血糖素","B. 肾上腺素","C. 皮质醇","D. 胰岛素"],"oe":["A错误：胰高血糖素升高血糖。","B错误：肾上腺素升高血糖。","C错误：皮质醇升高血糖。","D正确：胰岛素降低血糖，是唯一的降糖激素。"]}},{"title":"学习支持4：钙磷激素","sec":"第14章 · 学习支持","notes":"PTH（甲状旁腺激素）升钙降磷；CT（降钙素）降钙。","points":["PTH（甲状旁腺激素）","CT（降钙素）","钙磷"],"img":"","imageExplain":"","table":[["激素","血钙"],["PTH（甲状旁腺激素）","↑"],["CT（降钙素）","↓"],["VD3","↑"]],"srcType":"白话辅助","role":"主线","i":131,"check":{"kind":"mcq","id":"bc14_check_131","q":"PTH（甲状旁腺激素）与降钙素（CT）对血钙调节的拮抗关系是？","a":"A","e":"学习支持页：PTH（甲状旁腺激素）升血钙、降血磷；CT（降钙素）降血钙，两者对血钙的调节方向相反。","src":"本页自测","o":["A. PTH升血钙，CT降血钙","B. PTH降血钙，CT升血钙","C. 两者都升血钙","D. 两者都降血钙"],"oe":["A正确：PTH升血钙，CT降血钙。","B错误：两者作用说反了。","C错误：CT降低而非升高血钙。","D错误：PTH升高而非降低血钙。"]}},{"title":"计算1：激素单位换算","sec":"第14章 · 计算","notes":"1 μg胰岛素≈25.7 IU；1 IU≈0.0389 mg。按题目给定换算。","points":["IU↔μg","单位换算"],"img":"","imageExplain":"","table":[["量","换算"],["胰岛素","1 mg≈25.7 IU"]],"srcType":"白话辅助","role":"主线","i":132,"check":{"kind":"mcq","id":"bc14_check_132","q":"已知1 IU胰岛素≈0.0389 mg，则1 IU约等于多少微克（μg）？","a":"B","e":"单位换算：0.0389 mg×1000=38.9 μg；本页给出1 μg胰岛素≈25.7 IU，1 IU≈0.0389 mg。","src":"本页自测","o":["A. 3.89 μg","B. 38.9 μg","C. 389 μg","D. 0.389 μg"],"oe":["A错误：3.89 μg对应0.00389 mg，换算少了一个数量级。","B正确：0.0389 mg×1000=38.9 μg。","C错误：389 μg对应0.389 mg，换算多了一个数量级。","D错误：0.389 μg对应0.000389 mg，数量级错误。"]}},{"title":"计算2：激素浓度","sec":"第14章 · 计算","notes":"浓度=质量/体积；注意ng/mL、pmol/L换算。","points":["质量/体积","单位"],"img":"","imageExplain":"","table":[["单位","换算"],["ng/mL","μg/L"],["pmol/L","nmol/L×1000"]],"srcType":"白话辅助","role":"主线","i":133,"check":{"kind":"mcq","id":"bc14_check_133","q":"某激素溶液含激素20 ng，体积为2 mL，其浓度是？","a":"A","e":"浓度=质量/体积=20 ng÷2 mL=10 ng/mL；计算时注意ng/mL、pmol/L等单位换算。","src":"本页自测","o":["A. 10 ng/mL","B. 20 ng/mL","C. 40 ng/mL","D. 5 ng/mL"],"oe":["A正确：20 ng÷2 mL=10 ng/mL。","B错误：20 ng/mL相当于把质量直接当作浓度，未除以体积。","C错误：40 ng/mL是把体积乘而非除。","D错误：5 ng/mL对应20 ng÷4 mL，体积用错。"]}},{"title":"bc14 使用评估与学习建议","sec":"第14章 · 使用评估","notes":"先AI主讲1-10建立激素-受体-通路框架；再看图卡/表；最后做题。重点：分类、下丘脑-垂体轴、cAMP（环腺苷一磷酸）/IP3（三磷酸肌醇）/RTK（受体酪氨酸激酶）/核受体、血糖与钙磷。","points":["框架","受体","通路","反馈"],"img":"","imageExplain":"","table":[["项目","数量"],["总页数","135"],["章测","20选择+5判断+5填空+12简答+6计算+8名词"],["网页题","50"]],"srcType":"白话辅助","role":"主线","i":134,"check":{"kind":"mcq","id":"bc14_check_134","q":"本页给出的bc14学习建议，正确的顺序是？","a":"A","e":"使用评估建议：先AI主讲1-10建立激素-受体-通路框架，再看图卡/表，最后做题；重点是分类、下丘脑-垂体轴、cAMP（环腺苷一磷酸）/IP3（三磷酸肌醇）/RTK（受体酪氨酸激酶）/核受体、血糖与钙磷。","src":"本页自测","o":["A. 先AI主讲1-10建立激素-受体-通路框架，再看图卡/表，最后做题","B. 先做难题，再看图卡，最后看框架","C. 只背激素名称即可","D. 只做计算题即可"],"oe":["A正确：先建框架，再看图卡/表，最后做题。","B错误：应先建立框架再做题，而非先做难题。","C错误：只背名称不能掌握受体与通路，不符合建议。","D错误：计算只是部分内容，不能只做计算题。"]}}],"mcq":[{"id":"bc14_mcq_1","modI":0,"q":"下列对激素的性质和特征描述错误的是〈 )。[云南大学 2005 WH; 江西师范大学 2013 研]","o":["A. ，作用力强","B. 作用有特异性","C. 可以积累","D. 特定细胞合成"],"a":"C","e":"","kp":""},{"id":"bc14_mcq_2","modI":0,"q":"生长激素能促进个体生长，成年后该激素过多所产生的疾病为〈 )。[浙江师范大学 2012 研]","o":["A. 侏儒症","B. ，肢端肥大症","C. 巨人症","D. HI"],"a":"B","e":"","kp":""},{"id":"bc14_mcq_4","modI":0,"q":"饮用一杯浓咖啡将引起下列哪种反应? 《 ) [中国科学技术大学 2002 研]","o":["A. 于扰前列腺素的合成","B. 减弱胰高血糖素的作用","C. 增强肾上腺素的作用","D. 提供尼克酰胺维生素"],"a":"C","e":"","kp":""}],"judge":[],"fill":[],"short":[{"id":"bc14_short_1","modI":0,"q":"何谓激素? 按化学本质可将激素分哪几类? 举例说明。","a":"(1) 激素是生物体内产生的，通过体液或细胞外液运送到作用部位，产生特殊的生理效应，调节控制各 种物质代谢的生理功能，有利于多细胞的有机体统一成整体的一类微量的有机化合物。 (2) 激素按其化学成分主要分为三大类: OFRBR: 氨基酸衍生物类激素、多肽及蛋白质类激素; 名固醇类激素:肾上腺皮质激素、雌性性激素及雄性性激素; @@脂肪酸衍生物激素: 如二十碳四烯酸。 3，人和痛椎动物有哪些主要的内分泌腺? 它们各分泌哪些主要激素? 答: CL) 人体的内分泌腺主要要有下匡脑、垂体、甲状腺、肾上腺、胰岛、胸腺、性腺等。 (2) 下丘脑主要分泌促垂体分泌激素和抑制垂体分泌激素;垂体生长激素和各种促激素如促甲状腺激素、 促肾上腺皮质激素还有抗利尿激素等; 甲状腺分泌甲状腺激素; 肾上腺艇质分泌肾上腺素; 肾上腺皮质分泌皮质 醇、醛固醇等，胰岛分泌胰岛素、胰高血糖素、去甲硼上腺素等;胸腺分泌胸腺素; 性腺中举丸分泌雄激素，卵 巢分泌雌激素、孕酮、松弛素等。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_2","modI":0,"q":"垂体激素中哪些是直接作用于机体外周组织的靶细胞的，它们各自的功能是什么?","a":"生长激素是作用于全身细胞组织的，主要是促进生长发育和代谢; 催乳激素作用于乳房，促进乳汁分泌; 促 肾上腺皮质激素作用于肾上腺，刺激肯上腺皮质分泌多种类固醇皮质激素; 促甲状腺激素作用于甲状腺,促进甲 状腺的发育和分泥，从而影响全身代谢; 众产素作用于子宫，促进妊娠子宫收缩; 加压素作用于血管，可以升高 血压并抗利尿。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_3","modI":0,"q":"试述 (1) 类固醇激素和 (2) 肽《和蛋白质) 激素的作用机制。","a":"CL) 类固醇激素作用机制: 类固醇激素分子质量较小，且是脂溶性的，可通过扩散或载体转运进入训细 胞，可以进行激素进入细胞后先与胞浆内的受体结合。这类激素的受体通常是结合 DNA 的蛋白质，一旦激素结 合到受体上，受体就转变成一种转录的增强子而特定的基因就得到扩增表达，这种作用是通过基因转录形成 mRNA 而实现的，过程较慢。这些激素的原发效应反映在基因表达上，而不表现在酶的激活或转运过程的变化 上。由于这种作用是通过基因转录形成 mRNA 而实现的，因此作用过程较慢。 (2) 肽和蛋白质) 激素作用机制: 肽《和和蛋白质) 激素为水溶性，分子质量大，不能进入细胞膜，激素 到达竹细胞后，首先和驾细胞膜上的特异性受体相结合，活化的受体刺激与之偶联的蛋白活化,刺激细胞内第二 信使产生。第二信使上调蛋白激酶活性，进一步催化下游靶蛋白磷酸化，发挥生物学作用。还有一种机制是激素 与受体酷氨酸激酶 (TPK) 结合后，使原来无活性的 TPK 变为有活性的 TPK，TPK 众化受体分子自身 Tyr 残基 磷酸化，并进一步提高 TPK 的活性，使其他底物蛋白磷酸化，通过一系列的反应产生相应的生理效应。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_4","modI":0,"q":"胰岛素是怎样调节糖代谢的?","a":"进食富糖食品后葡萄糖从小肠进入血流，血糖升高导致胰腺分泌胰岛素增加《而胰高血糖素降低)。具 体过程如下: C1) 当血糖升高时,， 葡萄糖转运蛋白运载葡萄糖进入 B-细胞, 在这里葡萄糖立即被已糖激酶IV(葡糖激酶) 转化为 6-磷酸葡糖，并进入糖酵解; (2) 随着葡萄糖分解代谢速率的增加，ATP 升高，导致质膜中 ATP-门控 K \"通道关闭; (3) K 的外向流量减少造成膜去极化; (4) 膜的去极化打开电位门控 Ca通道，使细胞溶胶中[Ca2]增加; (5) Ca的增加触发胰岛素通过胞吐释放。 大脑整合有关能量供需方面的信号和来自副交感和交感神经系统的信号也影响胰岛素的释放。 在整个过程中有一个反馈环限制激素释放: 胰岛素通过刺激组织摄取和葡萄糖使血糖降低; B-细胞根据通向已 糖激酶反应的葡萄糖流量减小检测出血糖下降; 这就减慢或停止胰岛素的释放。 这一反馈调节保持血糖浓度基本 稳定，尽管进食有很大的变动。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_5","modI":0,"q":"CL) 皮质激素主要包括哪些激素? 〈2) 骨上腺素和去甲肯上腺素在功能上有何异同?","a":"CL) 皮质激素可以分为糖皮质激素和盐皮质激素。糖皮质激素主要有皮质醇、可的松和皮质酮;! 盐皮质 激素主要有醛固酮、11-脱氧皮质酮。 (2) 上肾上腺素和去甲皮上腺素功能上的异同如表 14-8 所示。 表 14-8 ”肾上腺素和去甲肯上腺素功能上的异同 引起血压升高、心跳加快、血管紧张、 = = me 心肌血流量加大等 原分解作用〈升高血糖 比肾上腺素强 20 信 8，甲状腺激素在体内过多或不足对机体有何影响? 答: 甲状腺激素包括甲状腺素和三碘甲状原氮酸，其功能是促进组织特别是肝和肌肉组织的产能代谢，加强 线粒体中的氧化磷酸化，增加 ATP 的生成量，而 ATP 的增加亦为核酸和蛋白质等的合成提供了能量，总的结果 促进机体的生长和发育。甲状腺机能亢进也就是甲状腺激素分泌过多，基础代谢率高，身体消瘦、神经紧张、心 跳加快、出汗、颤拌，并有眼球突出的症状。甲状腺机能减退也就是甲状腺激素分泌过多分泌不足，基础代谢率 下降，产能减小，患者不能正常生长、发育、精神和智力以及生殖器官的发育也都受到影响。小儿时期因甲状腺 机能不全或因缺碘甲状腺激素合成受阻，则出现呆小症: 体形小、智力低和性功能不成熟等。成人缺碘则出现面 部和手肿大的症状，是皮下结缔组织增厚的缘故，还有阻力、有呆滞、记忆力减退等。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_6","modI":0,"q":"C1) 试述符酮和肉二醇的生理功能。(2) 性激素分沁率乱会造成机体形态和功能上的什么变化?","a":"〈1) 举酮的主要生理功能是促进男性性器官发育，刺激男性副性征的出现，维持精子产生和正常性欲， 同时还可以促进骨骼生长、促进代谢作用; 雌二醇的生理功能是促进女性生殖器官的发育及功能形成，第二性征 的出现和维持，并与孕激素协同合作，形成月经周期。 (2) 性激素分泌率乱会影响机体性器官的发育成熟，影响第二性征及性行为。男性雄激素水平低下，身体 会发生女性化,女性雄激素分泌过多会发生多毛证的症状; 峻激素紊乱会导致月经不调或停经，妊垦异常或不孕 不育，子宫或卵巢发育不良，发生肿瘤等。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_7","modI":0,"q":"避孕药的设计原理是什么?","a":"避孕药一般是人工合成的肉激素和雄激素，有女性避孕药和男性避孕药。避孕原理是代替性激素，反馈 抑制下匡脑-垂体-性腺，特别是抑制垂体分泌促性腺激素，从而抑制性腺功能。以卵巢为例，避孕药代替肉激素 抑制垂体产生促性腺激素，从而抑制了卵梨排卵，并改变子宫颈黏液，使精子不宜穿透，或使子宫腺体减少肝糖 的制造，让宫胚不易存活，或是改变子宫和输卵管的活动方式，阻碍受精卵的运送。最终使精卵无法结合形成受 精卵，从而达到避孕的效果。 11， 何谓信号转导? 信号转导的基本过程是怎样的? 答:〈1) 信号转导是指细胞外的信号〈包括机械、化学和电信号等) 被放大并转化为细胞内的化学变化〈细 胞应答) 的过程。 (2) 信号转导的基本过程; 包一个信号跟受体发生相互作用; 名被活化了的受体跟细胞机器相互作用，产生第二信使或细胞蛋白质活性发生变化; 鲜靶细胞的代谢活动发生改变， 多阻断受体或把它从细胞表面除去，转导过程结束。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_8","modI":0,"q":"信号转导有哪些共同特点?","a":"信号转导有以下共同特点: C1) 信号转导的专一性 专一性是通过信号和受体之间的精确互补实现的。一个给定信号的受体或一个给定信号途径的胞内靶只在某 些类型的细胞中存在。 (2) 信号转导的敏感性 在三个方面可以说明信号转导的敏感性: 中受体对信号分子有高度亲和力; @@受体-配体〈信号分子) 相互 作用经常具有协同性: 配体浓度的小变化则引起受体活性的大变化; @@酶级联对信号具有放大作用，酶级联是指 一个跟信号受体结合的酶被连续激活的反应链，即酶催化酶的生化序列。 (3) 信号转导分子的模块性 模块性是指一个细胞能组合和匹配一套信号转导分子，以创建具有不同功能和细胞定位的复合体。 许多信和号 转导蛋白质具有多结构域，能识别其他蛋白质中或细胞骨架或质膜中的专一特点。因此，单个的模块是多价的， 允许这些模块组装成各种各样的多酶复合体 (4) 受体系统的脱敏作用 当一个信号连续出现时，受体的活化触发了反馈循环，阻断受体把它从细胞表面除去; 当刺激降到某一闪值 时，系统重新变得敏感。 (5) 转导系统的整合作用 整合是指系统接受多信号并产生适合细胞或生物体需要的统一应答能力。不同的信号途径在几个水平上可以 互相转换，以维持细胞和生物体的内稳态。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_9","modI":0,"q":"试述友上腺素受体、胰岛素受体的结构特点。","a":"(1) 肾上腺素受体是一个跨膜的受体蛋白，横路在靶细胞的细胞膜上，像其他一些与 G 蛋白偶联的受 体，如视紫质-光受体以及重毒碱的乙酰胆碱受体等一样，都是含有具 7 个螺旋区的受体。 (2) 胰岛素受体的相对分子量为 300000，它与胰岛素结合非常紧密，所形成的复合物的解离常数很低。是 整合在细胞膜上的一种糖蛋白，由两个 o-链和两个 B-链通过 3 个二硫键联结而组成，o-链处于细胞膜外侧，B- 链则穿过细胞膜。从纵训图可以看到，此受体由左右各 1 个 oP 单位组成，每一个 中 单位都从一个具有 1382 个 氨基酸残基的单链前体衍生而成。这个前体由一段信号肽为起始端，后面接着 w-亚基的序列，再接着高度碱性 的四肽，最后为B 亚基的序列。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_10","modI":0,"q":"GR G 蛋白和和钙调蛋白的结构和功能特点。","a":"G 蛋白是一个界面蛋白，处于细胞膜内侧，由 w、B、Y 三个亚基组成。它变动于它的 GDP 形式〈对环 化酶无活性) 及它的 GTP 形式 (有活性) 之间。无激素时，几乎所有的 G 蛋白都处于无活性的 GDP 形式。当 激素结合到受体上时，触发 GTP 将结合态的 GDP 取代下来: 激素-受体复合物结合到 G 蛋白上，使得结合态的 GDP MG 蛋白上释放，GTP 进入 G 和蛋白。接着，负载着 GTP 的 w亚基从B、y 亚基上解离下来，然后 G-GTP 活化环化酶。每一个被激素结合的受体又促使形成分子 G-GTP，由此给出“放大”的效应。此后，结合着 u 亚 基的 GTP 又在适当的条件下水解， 最终关闭这个由激素所触发的循环。结合态 GTP 缓慢的水解表明 G 蛋白是一 个 GTPase。也就是说这个调节蛋白具有一种内藏式的脱活化作用的设计。当缺乏激素时，GTP-GDP 交换反应的 速度大大地降低。最后，几乎所有的 G 蛋白均以结合着 GDP 的无活性形式存在，接着，几乎所有的环化酶都转 变成为无活性状态。 UR (CaM) 是钙传感器家族一 -结合钙蛋白质中的一种，存在于几乎所有的真核细胞中，对于任何微 量的钙都能敏感地捕获。状椎动物的钙调蛋白在 115 位都含有一个三甲基赖氨酸，这是翻译后的修饰产物，它可 能起着增加 CaM 与壮酶亲和力的作用。钙调和蛋白的一级结构在进化上呈现很强的保守性。钙调蛋白结构上若发 生突变是很容易致死的。另外，还有许多生理活动受它的协调，有人称它为细胞代谢调控的综合剂。特别是它作 为细胞内钙离子的受体，既调节细胞内钙离子的浓度，又媒介钙离子的功能，同时还调节第二信使 CAMP 的合 成与分解。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_11","modI":0,"q":"试述明上腺素在促进糖原降解中的级联放大。","a":"肾上腺素是一种含氨激素，当肾上腺素到达邯细胞后通过与受体结合，激活环化酶，生成cAMP，这是 一次信号放大过程; cAMP 别构刺激蛋白激酶活性，蛋白激酶糖原合成酶磷酸化，而后失活，这又是一次信号放 大反应; 蛋白激酶还可以磷酸化，磷酸化激酶使其激活，激活的磷酸化激酶使糖原磷酸化激活，成为有活性的磷 酸化酶 a，磷酸化酶 a 催化糖原转化为 1-磷酸葡萄糖，进而转变成葡萄糖，这也是一次信号放大反应，经过这些 步骤，在极短时间内可以提高血糖含量，产生大量的 ArTP，提供能量。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"},{"id":"bc14_short_12","modI":0,"q":"举出真核生物中 6 个普通类型的蛋白激酶和激活每个类型的直接因子。","a":"巴蛋白激酶 A，需要 cAMP 激活; 包和蛋白激酶 C，需要二酰甘油 (DG) 激活: @MAPK 激酶需要 Raf 蛋白激活; 外钙调蛋白，需要钙离子和钙调蛋白激活; OR ABA G. HI cGMP 激活; @酷氨酸激酶，需要胰 Ly GE","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记"}],"calc":[],"term":[]}],"mcq":[{"id":"bc14_mcq_1","modI":0,"q":"下列对激素的性质和特征描述错误的是〈 )。[云南大学 2005 WH; 江西师范大学 2013 研]","o":["A. ，作用力强","B. 作用有特异性","C. 可以积累","D. 特定细胞合成"],"a":"C","e":"解析：见激素/受体通路。","kp":"","oe":["解析：见激素/受体通路。","错误项不符合题意。","错误项不符合题意。","错误项不符合题意。"]},{"id":"bc14_mcq_2","modI":0,"q":"生长激素能促进个体生长，成年后该激素过多所产生的疾病为〈 )。[浙江师范大学 2012 研]","o":["A. 侏儒症","B. ，肢端肥大症","C. 巨人症","D. HI"],"a":"B","e":"解析：见激素/受体通路。","kp":"","oe":["解析：见激素/受体通路。","错误项不符合题意。","错误项不符合题意。","错误项不符合题意。"]},{"id":"bc14_mcq_4","modI":0,"q":"饮用一杯浓咖啡将引起下列哪种反应? 《 ) [中国科学技术大学 2002 研]","o":["A. 于扰前列腺素的合成","B. 减弱胰高血糖素的作用","C. 增强肾上腺素的作用","D. 提供尼克酰胺维生素"],"a":"C","e":"解析：见激素/受体通路。","kp":"","oe":["解析：见激素/受体通路。","错误项不符合题意。","错误项不符合题意。","错误项不符合题意。"]},{"id":"bc14_mcq4","modI":0,"q":"水溶性激素通常作用于？","o":["A. 膜受体","B. 核受体","C. 线粒体DNA","D. 核糖体"],"a":"A","e":"水溶性激素不能自由入细胞，作用于膜受体。","kp":"","kpId":"bc14_s0_98","oe":["正确：水溶性激素不能自由入细胞，作用于膜受体。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq5","modI":0,"q":"脂溶性激素通常作用于？","o":["A. 核受体","B. 膜受体","C. G蛋白","D. 离子通道"],"a":"A","e":"脂溶性激素可入细胞，结合核受体调控转录。","kp":"","kpId":"bc14_s0_98","oe":["正确：脂溶性激素可入细胞，结合核受体调控转录。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq6","modI":0,"q":"cAMP由谁生成？","o":["A. 腺苷酸环化酶","B. PLC","C. PKC","D. RTK"],"a":"A","e":"AC将ATP转化为cAMP。","kp":"","kpId":"bc14_s0_98","oe":["正确：AC将ATP转化为cAMP。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq7","modI":0,"q":"IP3的主要作用？","o":["A. 促Ca2+释放","B. 生成cAMP","C. 激活RTK","D. 降解DNA"],"a":"A","e":"IP3作用于内质网促Ca2+释放。","kp":"","kpId":"bc14_s0_98","oe":["正确：IP3作用于内质网促Ca2+释放。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq8","modI":0,"q":"DAG激活？","o":["A. PKC","B. PKA","C. AC","D. PLC"],"a":"A","e":"DAG与Ca2+共同激活PKC。","kp":"","kpId":"bc14_s0_98","oe":["正确：DAG与Ca2+共同激活PKC。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq9","modI":0,"q":"胰岛素受体属于？","o":["A. 酪氨酸激酶受体","B. G蛋白偶联受体","C. 核受体","D. 离子通道"],"a":"A","e":"胰岛素受体是RTK。","kp":"","kpId":"bc14_s0_98","oe":["正确：胰岛素受体是RTK。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq10","modI":0,"q":"胰岛素促进GLUT4？","o":["A. 转位到膜","B. 降解","C. 入核","D. 合成DNA"],"a":"A","e":"胰岛素促GLUT4转位，增加葡萄糖摄取。","kp":"","kpId":"bc14_s0_98","oe":["正确：胰岛素促GLUT4转位，增加葡萄糖摄取。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq11","modI":0,"q":"胰高血糖素作用？","o":["A. 升血糖","B. 降血糖","C. 降血钙","D. 促睡眠"],"a":"A","e":"胰高血糖素促糖原分解/糖异生，升血糖。","kp":"","kpId":"bc14_s0_98","oe":["正确：胰高血糖素促糖原分解/糖异生，升血糖。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq12","modI":0,"q":"PTH对血钙？","o":["A. 升高","B. 降低","C. 不变","D. 先降后升"],"a":"A","e":"PTH升血钙、降血磷。","kp":"","kpId":"bc14_s0_98","oe":["正确：PTH升血钙、降血磷。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq13","modI":0,"q":"降钙素对血钙？","o":["A. 降低","B. 升高","C. 不变","D. 先升后降"],"a":"A","e":"CT抑制骨吸收，降血钙。","kp":"","kpId":"bc14_s0_98","oe":["正确：CT抑制骨吸收，降血钙。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq14","modI":0,"q":"甲状腺激素含？","o":["A. 碘","B. 铁","C. 铜","D. 锌"],"a":"A","e":"T3/T4为含碘酪氨酸衍生物。","kp":"","kpId":"bc14_s0_98","oe":["正确：T3/T4为含碘酪氨酸衍生物。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq15","modI":0,"q":"肾上腺素来自？","o":["A. 酪氨酸","B. 胆固醇","C. 色氨酸","D. 葡萄糖"],"a":"A","e":"儿茶酚胺由Tyr衍生。","kp":"","kpId":"bc14_s0_98","oe":["正确：儿茶酚胺由Tyr衍生。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq16","modI":0,"q":"类固醇激素由谁合成？","o":["A. 胆固醇","B. 葡萄糖","C. 脂肪酸","D. 氨基酸"],"a":"A","e":"类固醇激素以胆固醇为前体。","kp":"","kpId":"bc14_s0_98","oe":["正确：类固醇激素以胆固醇为前体。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq17","modI":0,"q":"Gs激活？","o":["A. 腺苷酸环化酶","B. PLC","C. RTK","D. 核受体"],"a":"A","e":"Gs激活AC，增加cAMP。","kp":"","kpId":"bc14_s0_98","oe":["正确：Gs激活AC，增加cAMP。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq18","modI":0,"q":"Gq激活？","o":["A. PLC","B. AC","C. RTK","D. PKA"],"a":"A","e":"Gq激活PLC，生成IP3/DAG。","kp":"","kpId":"bc14_s0_98","oe":["正确：Gq激活PLC，生成IP3/DAG。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq19","modI":0,"q":"核受体反应特点？","o":["A. 慢","B. 快","C. 立即","D. 无基因调控"],"a":"A","e":"核受体调控转录，反应慢。","kp":"","kpId":"bc14_s0_98","oe":["正确：核受体调控转录，反应慢。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]},{"id":"bc14_mcq20","modI":0,"q":"下丘脑-垂体-靶腺轴有？","o":["A. 负反馈","B. 正反馈为主","C. 无反馈","D. 只神经调节"],"a":"A","e":"靶腺激素负反馈抑制上位激素。","kp":"","kpId":"bc14_s0_98","oe":["正确：靶腺激素负反馈抑制上位激素。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"]}],"judge":[{"id":"bc14_judge1","modI":0,"q":"水溶性激素通常作用于膜受体。","a":"对","e":"不能自由入细胞。"},{"id":"bc14_judge2","modI":0,"q":"cAMP由PLC生成。","a":"错","e":"cAMP由腺苷酸环化酶生成。"},{"id":"bc14_judge3","modI":0,"q":"胰岛素受体是酪氨酸激酶受体。","a":"对","e":"RTK自磷酸化。"},{"id":"bc14_judge4","modI":0,"q":"PTH降低血钙。","a":"错","e":"PTH升血钙。"},{"id":"bc14_judge5","modI":0,"q":"类固醇激素通过核受体慢反应。","a":"对","e":"调控基因转录。"}],"fill":[{"id":"bc14_fill1","modI":0,"q":"cAMP由______生成。","a":"腺苷酸环化酶","e":"AC。"},{"id":"bc14_fill2","modI":0,"q":"IP3促______释放。","a":"Ca2+","e":"内质网钙。"},{"id":"bc14_fill3","modI":0,"q":"胰岛素促______转位。","a":"GLUT4","e":"葡萄糖摄取。"},{"id":"bc14_fill4","modI":0,"q":"PTH使血钙______。","a":"升高","e":"骨吸收/肾重吸收。"},{"id":"bc14_fill5","modI":0,"q":"类固醇激素由______合成。","a":"胆固醇","e":"前体。"}],"term":[{"id":"bc14_term1","modI":0,"term":"激素","def":"内分泌细胞分泌、经体液运输、作用于靶细胞受体的微量高效信息分子。","e":"不供能，调节代谢。"},{"id":"bc14_term2","modI":0,"term":"第二信使","def":"激素与膜受体结合后在细胞内生成的小分子信号物质，如cAMP、IP3、DAG、Ca2+。","e":"放大信号。"},{"id":"bc14_term3","modI":0,"term":"G蛋白","def":"与GPCR偶联、可结合GTP/GDP的膜蛋白，激活或抑制效应酶。","e":"Gs/Gi/Gq。"},{"id":"bc14_term4","modI":0,"term":"RTK","def":"受体酪氨酸激酶，配体结合后自磷酸化并激活下游通路。","e":"胰岛素受体。"},{"id":"bc14_term5","modI":0,"term":"核受体","def":"位于细胞核/胞质的受体，结合脂溶性激素后调控基因转录。","e":"类固醇/甲状腺激素。"},{"id":"bc14_term6","modI":0,"term":"PTH","def":"甲状旁腺激素，升血钙、降血磷。","e":"骨/肾/肠。"},{"id":"bc14_term7","modI":0,"term":"降钙素","def":"甲状腺C细胞分泌，抑制骨吸收、降血钙。","e":"CT。"},{"id":"bc14_term8","modI":0,"term":"胰岛素","def":"胰岛β细胞分泌的蛋白激素，A/B链二硫键，降血糖。","e":"GLUT4。"}],"short":[{"id":"bc14_short_1","modI":0,"q":"何谓激素? 按化学本质可将激素分哪几类? 举例说明。","a":"(1) 激素是生物体内产生的，通过体液或细胞外液运送到作用部位，产生特殊的生理效应，调节控制各 种物质代谢的生理功能，有利于多细胞的有机体统一成整体的一类微量的有机化合物。 (2) 激素按其化学成分主要分为三大类: OFRBR: 氨基酸衍生物类激素、多肽及蛋白质类激素; 名固醇类激素:肾上腺皮质激素、雌性性激素及雄性性激素; @@脂肪酸衍生物激素: 如二十碳四烯酸。 3，人和痛椎动物有哪些主要的内分泌腺? 它们各分泌哪些主要激素? 答: CL) 人体的内分泌腺主要要有下匡脑、垂体、甲状腺、肾上腺、胰岛、胸腺、性腺等。 (2) 下丘脑主要分泌促垂体分泌激素和抑制垂体分泌激素;垂体生长激素和各种促激素如促甲状腺激素、 促肾上腺皮质激素还有抗利尿激素等; 甲状腺分泌甲状腺激素; 肾上腺艇质分泌肾上腺素; 肾上腺皮质分泌皮质 醇、醛固醇等，胰岛分泌胰岛素、胰高血糖素、去甲硼上腺素等;胸腺分泌胸腺素; 性腺中举丸分泌雄激素，卵 巢分泌雌激素、孕酮、松弛素等。","kps":"激素定义；三类：氨基酸衍生物/肽蛋白/固醇/脂肪酸衍生物；举例","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"激素是内分泌细胞产生、经体液运输、微量高效调节代谢和生理功能的化学信使。按化学本质分：①氨基酸衍生物（甲状腺素、肾上腺素）；②多肽/蛋白质（胰岛素、生长激素）；③类固醇（皮质醇、睾酮、雌二醇）；④脂肪酸衍生物（前列腺素）。"},{"id":"bc14_short_2","modI":0,"q":"垂体激素中哪些是直接作用于机体外周组织的靶细胞的，它们各自的功能是什么?","a":"生长激素是作用于全身细胞组织的，主要是促进生长发育和代谢; 催乳激素作用于乳房，促进乳汁分泌; 促 肾上腺皮质激素作用于肾上腺，刺激肯上腺皮质分泌多种类固醇皮质激素; 促甲状腺激素作用于甲状腺,促进甲 状腺的发育和分泥，从而影响全身代谢; 众产素作用于子宫，促进妊娠子宫收缩; 加压素作用于血管，可以升高 血压并抗利尿。","kps":"生长激素/催乳素/ACTH/TSH/缩宫素/加压素；靶组织+功能","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"直接作用于外周靶细胞的垂体激素：生长激素→全身细胞，促生长和代谢；催乳素→乳腺，促泌乳；ACTH→肾上腺皮质，促皮质激素分泌；TSH→甲状腺，促甲状腺激素分泌；缩宫素→子宫，促收缩；加压素→血管/肾，升压抗利尿。"},{"id":"bc14_short_3","modI":0,"q":"试述 (1) 类固醇激素和 (2) 肽《和蛋白质) 激素的作用机制。","a":"CL) 类固醇激素作用机制: 类固醇激素分子质量较小，且是脂溶性的，可通过扩散或载体转运进入训细 胞，可以进行激素进入细胞后先与胞浆内的受体结合。这类激素的受体通常是结合 DNA 的蛋白质，一旦激素结 合到受体上，受体就转变成一种转录的增强子而特定的基因就得到扩增表达，这种作用是通过基因转录形成 mRNA 而实现的，过程较慢。这些激素的原发效应反映在基因表达上，而不表现在酶的激活或转运过程的变化 上。由于这种作用是通过基因转录形成 mRNA 而实现的，因此作用过程较慢。 (2) 肽和蛋白质) 激素作用机制: 肽《和和蛋白质) 激素为水溶性，分子质量大，不能进入细胞膜，激素 到达竹细胞后，首先和驾细胞膜上的特异性受体相结合，活化的受体刺激与之偶联的蛋白活化,刺激细胞内第二 信使产生。第二信使上调蛋白激酶活性，进一步催化下游靶蛋白磷酸化，发挥生物学作用。还有一种机制是激素 与受体酷氨酸激酶 (TPK) 结合后，使原来无活性的 TPK 变为有活性的 TPK，TPK 众化受体分子自身 Tyr 残基 磷酸化，并进一步提高 TPK 的活性，使其他底物蛋白磷酸化，通过一系列的反应产生相应的生理效应。","kps":"类固醇：胞内受体→基因转录；肽类：膜受体→第二信使/TPK","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"类固醇激素脂溶性，进入细胞与胞内/核受体结合，受体-激素复合物作为转录因子调控基因表达，起效慢。肽/蛋白激素水溶性，不能入胞，与膜受体结合；通过G蛋白-第二信使（cAMP等）激活蛋白激酶，或受体酪氨酸激酶自身磷酸化，级联放大，起效快。"},{"id":"bc14_short_4","modI":0,"q":"胰岛素是怎样调节糖代谢的?","a":"进食富糖食品后葡萄糖从小肠进入血流，血糖升高导致胰腺分泌胰岛素增加《而胰高血糖素降低)。具 体过程如下: C1) 当血糖升高时,， 葡萄糖转运蛋白运载葡萄糖进入 B-细胞, 在这里葡萄糖立即被已糖激酶IV(葡糖激酶) 转化为 6-磷酸葡糖，并进入糖酵解; (2) 随着葡萄糖分解代谢速率的增加，ATP 升高，导致质膜中 ATP-门控 K \"通道关闭; (3) K 的外向流量减少造成膜去极化; (4) 膜的去极化打开电位门控 Ca通道，使细胞溶胶中[Ca2]增加; (5) Ca的增加触发胰岛素通过胞吐释放。 大脑整合有关能量供需方面的信号和来自副交感和交感神经系统的信号也影响胰岛素的释放。 在整个过程中有一个反馈环限制激素释放: 胰岛素通过刺激组织摄取和葡萄糖使血糖降低; B-细胞根据通向已 糖激酶反应的葡萄糖流量减小检测出血糖下降; 这就减慢或停止胰岛素的释放。 这一反馈调节保持血糖浓度基本 稳定，尽管进食有很大的变动。","kps":"血糖↑→GLUT2→葡糖激酶→ATP↑→KATP关闭→去极化→Ca2+内流→胰岛素胞吐","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"血糖升高，葡萄糖经GLUT2进入β细胞，葡糖激酶磷酸化，糖酵解使ATP/ADP升高；ATP敏感K+通道关闭，膜去极化，电压门控Ca2+通道开放，Ca2+内流触发胰岛素囊泡胞吐。胰岛素促组织摄取葡萄糖，血糖下降后又抑制分泌，形成反馈环。"},{"id":"bc14_short_5","modI":0,"q":"CL) 皮质激素主要包括哪些激素? 〈2) 骨上腺素和去甲肯上腺素在功能上有何异同?","a":"CL) 皮质激素可以分为糖皮质激素和盐皮质激素。糖皮质激素主要有皮质醇、可的松和皮质酮;! 盐皮质 激素主要有醛固酮、11-脱氧皮质酮。 (2) 上肾上腺素和去甲皮上腺素功能上的异同如表 14-8 所示。 表 14-8 ”肾上腺素和去甲肯上腺素功能上的异同 引起血压升高、心跳加快、血管紧张、 = = me 心肌血流量加大等 原分解作用〈升高血糖 比肾上腺素强 20 信 8，甲状腺激素在体内过多或不足对机体有何影响? 答: 甲状腺激素包括甲状腺素和三碘甲状原氮酸，其功能是促进组织特别是肝和肌肉组织的产能代谢，加强 线粒体中的氧化磷酸化，增加 ATP 的生成量，而 ATP 的增加亦为核酸和蛋白质等的合成提供了能量，总的结果 促进机体的生长和发育。甲状腺机能亢进也就是甲状腺激素分泌过多，基础代谢率高，身体消瘦、神经紧张、心 跳加快、出汗、颤拌，并有眼球突出的症状。甲状腺机能减退也就是甲状腺激素分泌过多分泌不足，基础代谢率 下降，产能减小，患者不能正常生长、发育、精神和智力以及生殖器官的发育也都受到影响。小儿时期因甲状腺 机能不全或因缺碘甲状腺激素合成受阻，则出现呆小症: 体形小、智力低和性功能不成熟等。成人缺碘则出现面 部和手肿大的症状，是皮下结缔组织增厚的缘故，还有阻力、有呆滞、记忆力减退等。","kps":"糖皮质激素/盐皮质激素；肾上腺素vs去甲肾上腺素","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"皮质激素分糖皮质激素（皮质醇、可的松、皮质酮）和盐皮质激素（醛固酮、11-脱氧皮质酮）。肾上腺素和去甲肾上腺素都升血压、加快心率、促糖原分解；肾上腺素对心率和代谢作用更强，去甲肾上腺素缩血管/升压更明显。"},{"id":"bc14_short_6","modI":0,"q":"C1) 试述符酮和肉二醇的生理功能。(2) 性激素分沁率乱会造成机体形态和功能上的什么变化?","a":"〈1) 举酮的主要生理功能是促进男性性器官发育，刺激男性副性征的出现，维持精子产生和正常性欲， 同时还可以促进骨骼生长、促进代谢作用; 雌二醇的生理功能是促进女性生殖器官的发育及功能形成，第二性征 的出现和维持，并与孕激素协同合作，形成月经周期。 (2) 性激素分泌率乱会影响机体性器官的发育成熟，影响第二性征及性行为。男性雄激素水平低下，身体 会发生女性化,女性雄激素分泌过多会发生多毛证的症状; 峻激素紊乱会导致月经不调或停经，妊垦异常或不孕 不育，子宫或卵巢发育不良，发生肿瘤等。","kps":"睾酮：男性性器官/副性征/精子/骨骼代谢；雌二醇：女性生殖/第二性征/月经；紊乱影响发育和生育","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"睾酮促男性性器官发育、副性征、精子发生、骨骼和代谢；雌二醇促女性生殖器官发育、第二性征、与孕激素协同形成月经周期。性激素紊乱可致性器官发育异常、第二性征改变、月经紊乱、不孕、肿瘤等。"},{"id":"bc14_short_7","modI":0,"q":"避孕药的设计原理是什么?","a":"避孕药一般是人工合成的肉激素和雄激素，有女性避孕药和男性避孕药。避孕原理是代替性激素，反馈 抑制下匡脑-垂体-性腺，特别是抑制垂体分泌促性腺激素，从而抑制性腺功能。以卵巢为例，避孕药代替肉激素 抑制垂体产生促性腺激素，从而抑制了卵梨排卵，并改变子宫颈黏液，使精子不宜穿透，或使子宫腺体减少肝糖 的制造，让宫胚不易存活，或是改变子宫和输卵管的活动方式，阻碍受精卵的运送。最终使精卵无法结合形成受 精卵，从而达到避孕的效果。 11， 何谓信号转导? 信号转导的基本过程是怎样的? 答:〈1) 信号转导是指细胞外的信号〈包括机械、化学和电信号等) 被放大并转化为细胞内的化学变化〈细 胞应答) 的过程。 (2) 信号转导的基本过程; 包一个信号跟受体发生相互作用; 名被活化了的受体跟细胞机器相互作用，产生第二信使或细胞蛋白质活性发生变化; 鲜靶细胞的代谢活动发生改变， 多阻断受体或把它从细胞表面除去，转导过程结束。","kps":"负反馈抑制下丘脑-垂体-性腺轴；抑制排卵/精子；改变宫颈黏液/内膜","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"避孕药多用合成雌激素/孕激素，负反馈抑制下丘脑GnRH和垂体FSH/LH，抑制排卵；同时改变宫颈黏液（精子难穿透）、子宫内膜（不利于着床）和输卵管活动。男性避孕药抑制精子发生。"},{"id":"bc14_short_8","modI":0,"q":"信号转导有哪些共同特点?","a":"信号转导有以下共同特点: C1) 信号转导的专一性 专一性是通过信号和受体之间的精确互补实现的。一个给定信号的受体或一个给定信号途径的胞内靶只在某 些类型的细胞中存在。 (2) 信号转导的敏感性 在三个方面可以说明信号转导的敏感性: 中受体对信号分子有高度亲和力; @@受体-配体〈信号分子) 相互 作用经常具有协同性: 配体浓度的小变化则引起受体活性的大变化; @@酶级联对信号具有放大作用，酶级联是指 一个跟信号受体结合的酶被连续激活的反应链，即酶催化酶的生化序列。 (3) 信号转导分子的模块性 模块性是指一个细胞能组合和匹配一套信号转导分子，以创建具有不同功能和细胞定位的复合体。 许多信和号 转导蛋白质具有多结构域，能识别其他蛋白质中或细胞骨架或质膜中的专一特点。因此，单个的模块是多价的， 允许这些模块组装成各种各样的多酶复合体 (4) 受体系统的脱敏作用 当一个信号连续出现时，受体的活化触发了反馈循环，阻断受体把它从细胞表面除去; 当刺激降到某一闪值 时，系统重新变得敏感。 (5) 转导系统的整合作用 整合是指系统接受多信号并产生适合细胞或生物体需要的统一应答能力。不同的信号途径在几个水平上可以 互相转换，以维持细胞和生物体的内稳态。","kps":"信号→受体→第二信使/蛋白活性→细胞应答→脱敏/终止","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"信号转导：胞外信号（化学/机械/电）与受体结合→受体活化→激活G蛋白/酶/第二信使→下游蛋白磷酸化→代谢或基因表达改变→受体脱敏/内吞，信号终止。特点：专一、敏感、放大、模块化、整合、脱敏。"},{"id":"bc14_short_9","modI":0,"q":"试述友上腺素受体、胰岛素受体的结构特点。","a":"(1) 肾上腺素受体是一个跨膜的受体蛋白，横路在靶细胞的细胞膜上，像其他一些与 G 蛋白偶联的受 体，如视紫质-光受体以及重毒碱的乙酰胆碱受体等一样，都是含有具 7 个螺旋区的受体。 (2) 胰岛素受体的相对分子量为 300000，它与胰岛素结合非常紧密，所形成的复合物的解离常数很低。是 整合在细胞膜上的一种糖蛋白，由两个 o-链和两个 B-链通过 3 个二硫键联结而组成，o-链处于细胞膜外侧，B- 链则穿过细胞膜。从纵训图可以看到，此受体由左右各 1 个 oP 单位组成，每一个 中 单位都从一个具有 1382 个 氨基酸残基的单链前体衍生而成。这个前体由一段信号肽为起始端，后面接着 w-亚基的序列，再接着高度碱性 的四肽，最后为B 亚基的序列。","kps":"肾上腺素受体=7次跨膜/G蛋白偶联；胰岛素受体=α2β2酪氨酸激酶","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"肾上腺素受体是7次跨膜、与G蛋白偶联的受体。胰岛素受体是膜糖蛋白，α2β2，由二硫键连接；α亚基在膜外结合胰岛素，β亚基跨膜、含酪氨酸激酶结构域，配体结合后自磷酸化并磷酸化底物。"},{"id":"bc14_short_10","modI":0,"q":"GR G 蛋白和和钙调蛋白的结构和功能特点。","a":"G 蛋白是一个界面蛋白，处于细胞膜内侧，由 w、B、Y 三个亚基组成。它变动于它的 GDP 形式〈对环 化酶无活性) 及它的 GTP 形式 (有活性) 之间。无激素时，几乎所有的 G 蛋白都处于无活性的 GDP 形式。当 激素结合到受体上时，触发 GTP 将结合态的 GDP 取代下来: 激素-受体复合物结合到 G 蛋白上，使得结合态的 GDP MG 蛋白上释放，GTP 进入 G 和蛋白。接着，负载着 GTP 的 w亚基从B、y 亚基上解离下来，然后 G-GTP 活化环化酶。每一个被激素结合的受体又促使形成分子 G-GTP，由此给出“放大”的效应。此后，结合着 u 亚 基的 GTP 又在适当的条件下水解， 最终关闭这个由激素所触发的循环。结合态 GTP 缓慢的水解表明 G 蛋白是一 个 GTPase。也就是说这个调节蛋白具有一种内藏式的脱活化作用的设计。当缺乏激素时，GTP-GDP 交换反应的 速度大大地降低。最后，几乎所有的 G 蛋白均以结合着 GDP 的无活性形式存在，接着，几乎所有的环化酶都转 变成为无活性状态。 UR (CaM) 是钙传感器家族一 -结合钙蛋白质中的一种，存在于几乎所有的真核细胞中，对于任何微 量的钙都能敏感地捕获。状椎动物的钙调蛋白在 115 位都含有一个三甲基赖氨酸，这是翻译后的修饰产物，它可 能起着增加 CaM 与壮酶亲和力的作用。钙调和蛋白的一级结构在进化上呈现很强的保守性。钙调蛋白结构上若发 生突变是很容易致死的。另外，还有许多生理活动受它的协调，有人称它为细胞代谢调控的综合剂。特别是它作 为细胞内钙离子的受体，既调节细胞内钙离子的浓度，又媒介钙离子的功能，同时还调节第二信使 CAMP 的合 成与分解。","kps":"G蛋白：αβγ，GDP/GTP开关，放大；CaM：钙传感器，调节激酶/磷酸酶","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"G蛋白位于膜内侧，αβγ三聚体；GDP结合为关闭，GTP结合α亚基活化并解离，调节腺苷酸环化酶等，GTP水解终止，具放大作用。钙调蛋白CaM是钙传感器，结合Ca²⁺后构象改变，调节CaM激酶、磷酸二酯酶等，参与钙信号。"},{"id":"bc14_short_11","modI":0,"q":"试述明上腺素在促进糖原降解中的级联放大。","a":"肾上腺素是一种含氨激素，当肾上腺素到达邯细胞后通过与受体结合，激活环化酶，生成cAMP，这是 一次信号放大过程; cAMP 别构刺激蛋白激酶活性，蛋白激酶糖原合成酶磷酸化，而后失活，这又是一次信号放 大反应; 蛋白激酶还可以磷酸化，磷酸化激酶使其激活，激活的磷酸化激酶使糖原磷酸化激活，成为有活性的磷 酸化酶 a，磷酸化酶 a 催化糖原转化为 1-磷酸葡萄糖，进而转变成葡萄糖，这也是一次信号放大反应，经过这些 步骤，在极短时间内可以提高血糖含量，产生大量的 ArTP，提供能量。","kps":"肾上腺素→受体→cAMP→PKA→磷酸化酶b→a→糖原分解；级联放大","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"肾上腺素结合β受体→激活腺苷酸环化酶→cAMP↑→PKA活化→磷酸化酶b激酶活化→糖原磷酸化酶b→a→糖原分解为1-磷酸葡萄糖→葡萄糖。每步放大，少量激素迅速升高血糖。"},{"id":"bc14_short_12","modI":0,"q":"举出真核生物中 6 个普通类型的蛋白激酶和激活每个类型的直接因子。","a":"巴蛋白激酶 A，需要 cAMP 激活; 包和蛋白激酶 C，需要二酰甘油 (DG) 激活: @MAPK 激酶需要 Raf 蛋白激活; 外钙调蛋白，需要钙离子和钙调蛋白激活; OR ABA G. HI cGMP 激活; @酷氨酸激酶，需要胰 Ly GE","kps":"PKA-cAMP；PKC-DAG/Ca2+；MAPK-Raf；CaM激酶-Ca2+/CaM；PKG-cGMP；RTK-配体","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第14章笔记","e":"常见蛋白激酶及直接激活因子：PKA—cAMP；PKC—二酰甘油（DAG）和Ca²⁺；MAPK—Raf/MAPKKK级联；CaM激酶—Ca²⁺/钙调蛋白；PKG—cGMP；受体酪氨酸激酶—生长因子配体。"}],"calc":[{"id":"bc14_calc1","modI":0,"q":"1 mg胰岛素约多少IU？","a":"约25.7 IU","e":"1 mg≈25.7 IU。"},{"id":"bc14_calc2","modI":0,"q":"10 IU胰岛素约多少mg？","a":"约0.389 mg","e":"1 IU≈0.0389 mg。"},{"id":"bc14_calc3","modI":0,"q":"激素浓度10 ng/mL等于多少μg/L？","a":"10 μg/L","e":"1 ng/mL=1 μg/L。"},{"id":"bc14_calc4","modI":0,"q":"cAMP由ATP经哪种酶生成？","a":"腺苷酸环化酶","e":"AC。"},{"id":"bc14_calc5","modI":0,"q":"IP3促哪个离子释放？","a":"Ca2+","e":"内质网。"},{"id":"bc14_calc6","modI":0,"q":"PTH对血钙和血磷分别？","a":"血钙↑、血磷↓","e":"PTH。"}],"preview":{"main":"bc14共135页。先AI主讲10页，再看通路图卡，最后做题。","questions":["激素分类？","cAMP/IP3通路？","胰岛素受体？"]},"toc":[{"title":"一、激素总论","pages":"22页","start":0,"end":22},{"title":"二、重要激素","pages":"44页","start":22,"end":66},{"title":"三、作用机制","pages":"28页","start":66,"end":94},{"title":"四、调节/昆虫激素","pages":"4页","start":94,"end":98},{"title":"AI主讲/精读/过程/变式/图卡/支持/计算","pages":"37页","start":98,"end":135}],"exerciseTitle":"📝 第14章激素和信号转导 · 网页题","exercises":[{"id":"bc14_ex1","no":1,"type":"选择","q":"下列对激素的性质和特征描述错误的是〈 )。[云南大学 2005 WH; 江西师范大学 2013 研] A. ，作用力强 B. 作用有特异性 C. 可以积累 D. 特定细胞合成","analysis":"解析：见激素/受体通路。","answer":"C","oe":["解析：见激素/受体通路。","错误项不符合题意。","错误项不符合题意。","错误项不符合题意。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex2","no":2,"type":"选择","q":"生长激素能促进个体生长，成年后该激素过多所产生的疾病为〈 )。[浙江师范大学 2012 研] A. 侏儒症 B. ，肢端肥大症 C. 巨人症 D. HI","analysis":"解析：见激素/受体通路。","answer":"B","oe":["解析：见激素/受体通路。","错误项不符合题意。","错误项不符合题意。","错误项不符合题意。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex3","no":3,"type":"选择","q":"饮用一杯浓咖啡将引起下列哪种反应? 《 ) [中国科学技术大学 2002 研] A. 于扰前列腺素的合成 B. 减弱胰高血糖素的作用 C. 增强肾上腺素的作用 D. 提供尼克酰胺维生素","analysis":"解析：见激素/受体通路。","answer":"C","oe":["解析：见激素/受体通路。","错误项不符合题意。","错误项不符合题意。","错误项不符合题意。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex4","no":4,"type":"选择","q":"水溶性激素通常作用于？ A. 膜受体 B. 核受体 C. 线粒体DNA D. 核糖体","analysis":"水溶性激素不能自由入细胞，作用于膜受体。","answer":"A","oe":["正确：水溶性激素不能自由入细胞，作用于膜受体。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex5","no":5,"type":"选择","q":"脂溶性激素通常作用于？ A. 核受体 B. 膜受体 C. G蛋白 D. 离子通道","analysis":"脂溶性激素可入细胞，结合核受体调控转录。","answer":"A","oe":["正确：脂溶性激素可入细胞，结合核受体调控转录。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex6","no":6,"type":"选择","q":"cAMP由谁生成？ A. 腺苷酸环化酶 B. PLC C. PKC D. RTK","analysis":"AC将ATP转化为cAMP。","answer":"A","oe":["正确：AC将ATP转化为cAMP。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex7","no":7,"type":"选择","q":"IP3的主要作用？ A. 促Ca2+释放 B. 生成cAMP C. 激活RTK D. 降解DNA","analysis":"IP3作用于内质网促Ca2+释放。","answer":"A","oe":["正确：IP3作用于内质网促Ca2+释放。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex8","no":8,"type":"选择","q":"DAG激活？ A. PKC B. PKA C. AC D. PLC","analysis":"DAG与Ca2+共同激活PKC。","answer":"A","oe":["正确：DAG与Ca2+共同激活PKC。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex9","no":9,"type":"选择","q":"胰岛素受体属于？ A. 酪氨酸激酶受体 B. G蛋白偶联受体 C. 核受体 D. 离子通道","analysis":"胰岛素受体是RTK。","answer":"A","oe":["正确：胰岛素受体是RTK。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex10","no":10,"type":"选择","q":"胰岛素促进GLUT4？ A. 转位到膜 B. 降解 C. 入核 D. 合成DNA","analysis":"胰岛素促GLUT4转位，增加葡萄糖摄取。","answer":"A","oe":["正确：胰岛素促GLUT4转位，增加葡萄糖摄取。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex11","no":11,"type":"选择","q":"胰高血糖素作用？ A. 升血糖 B. 降血糖 C. 降血钙 D. 促睡眠","analysis":"胰高血糖素促糖原分解/糖异生，升血糖。","answer":"A","oe":["正确：胰高血糖素促糖原分解/糖异生，升血糖。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex12","no":12,"type":"选择","q":"PTH对血钙？ A. 升高 B. 降低 C. 不变 D. 先降后升","analysis":"PTH升血钙、降血磷。","answer":"A","oe":["正确：PTH升血钙、降血磷。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex13","no":13,"type":"选择","q":"降钙素对血钙？ A. 降低 B. 升高 C. 不变 D. 先升后降","analysis":"CT抑制骨吸收，降血钙。","answer":"A","oe":["正确：CT抑制骨吸收，降血钙。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex14","no":14,"type":"选择","q":"甲状腺激素含？ A. 碘 B. 铁 C. 铜 D. 锌","analysis":"T3/T4为含碘酪氨酸衍生物。","answer":"A","oe":["正确：T3/T4为含碘酪氨酸衍生物。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex15","no":15,"type":"选择","q":"肾上腺素来自？ A. 酪氨酸 B. 胆固醇 C. 色氨酸 D. 葡萄糖","analysis":"儿茶酚胺由Tyr衍生。","answer":"A","oe":["正确：儿茶酚胺由Tyr衍生。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex16","no":16,"type":"选择","q":"类固醇激素由谁合成？ A. 胆固醇 B. 葡萄糖 C. 脂肪酸 D. 氨基酸","analysis":"类固醇激素以胆固醇为前体。","answer":"A","oe":["正确：类固醇激素以胆固醇为前体。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex17","no":17,"type":"选择","q":"Gs激活？ A. 腺苷酸环化酶 B. PLC C. RTK D. 核受体","analysis":"Gs激活AC，增加cAMP。","answer":"A","oe":["正确：Gs激活AC，增加cAMP。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex18","no":18,"type":"选择","q":"Gq激活？ A. PLC B. AC C. RTK D. PKA","analysis":"Gq激活PLC，生成IP3/DAG。","answer":"A","oe":["正确：Gq激活PLC，生成IP3/DAG。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex19","no":19,"type":"选择","q":"核受体反应特点？ A. 慢 B. 快 C. 立即 D. 无基因调控","analysis":"核受体调控转录，反应慢。","answer":"A","oe":["正确：核受体调控转录，反应慢。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex20","no":20,"type":"选择","q":"下丘脑-垂体-靶腺轴有？ A. 负反馈 B. 正反馈为主 C. 无反馈 D. 只神经调节","analysis":"靶腺激素负反馈抑制上位激素。","answer":"A","oe":["正确：靶腺激素负反馈抑制上位激素。","错误：不是最佳答案。","错误：不是最佳答案。","错误：不是最佳答案。"],"slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex21","no":21,"type":"简答","q":"何谓激素? 按化学本质可将激素分哪几类? 举例说明。","analysis":"激素是内分泌细胞产生、经体液运输、微量高效调节代谢和生理功能的化学信使。按化学本质分：①氨基酸衍生物（甲状腺素、肾上腺素）；②多肽/蛋白质（胰岛素、生长激素）；③类固醇（皮质醇、睾酮、雌二醇）；④脂肪酸衍生物（前列腺素）。","answer":"(1) 激素是生物体内产生的，通过体液或细胞外液运送到作用部位，产生特殊的生理效应，调节控制各 种物质代谢的生理功能，有利于多细胞的有机体统一成整体的一类微量的有机化合物。 (2) 激素按其化学成分主要分为三大类: OFRBR: 氨基酸衍生物类激素、多肽及蛋白质类激素; 名固醇类激素:肾上腺皮质激素、雌性性激素及雄性性激素; @@脂肪酸衍生物激素: 如二十碳四烯酸。 3，人和痛椎动物有哪些主要的内分泌腺? 它们各分泌哪些主要激素? 答: CL) 人体的内分泌腺主要要有下匡脑、垂体、甲状腺、肾上腺、胰岛、胸腺、性腺等。 (2) 下丘脑主要分泌促垂体分泌激素和抑制垂体分泌激素;垂体生长激素和各种促激素如促甲状腺激素、 促肾上腺皮质激素还有抗利尿激素等; 甲状腺分泌甲状腺激素; 肾上腺艇质分泌肾上腺素; 肾上腺皮质分泌皮质 醇、醛固醇等，胰岛分泌胰岛素、胰高血糖素、去甲硼上腺素等;胸腺分泌胸腺素; 性腺中举丸分泌雄激素，卵 巢分泌雌激素、孕酮、松弛素等。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex22","no":22,"type":"简答","q":"垂体激素中哪些是直接作用于机体外周组织的靶细胞的，它们各自的功能是什么?","analysis":"直接作用于外周靶细胞的垂体激素：生长激素→全身细胞，促生长和代谢；催乳素→乳腺，促泌乳；ACTH→肾上腺皮质，促皮质激素分泌；TSH→甲状腺，促甲状腺激素分泌；缩宫素→子宫，促收缩；加压素→血管/肾，升压抗利尿。","answer":"生长激素是作用于全身细胞组织的，主要是促进生长发育和代谢; 催乳激素作用于乳房，促进乳汁分泌; 促 肾上腺皮质激素作用于肾上腺，刺激肯上腺皮质分泌多种类固醇皮质激素; 促甲状腺激素作用于甲状腺,促进甲 状腺的发育和分泥，从而影响全身代谢; 众产素作用于子宫，促进妊娠子宫收缩; 加压素作用于血管，可以升高 血压并抗利尿。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex23","no":23,"type":"简答","q":"试述 (1) 类固醇激素和 (2) 肽《和蛋白质) 激素的作用机制。","analysis":"类固醇激素脂溶性，进入细胞与胞内/核受体结合，受体-激素复合物作为转录因子调控基因表达，起效慢。肽/蛋白激素水溶性，不能入胞，与膜受体结合；通过G蛋白-第二信使（cAMP等）激活蛋白激酶，或受体酪氨酸激酶自身磷酸化，级联放大，起效快。","answer":"CL) 类固醇激素作用机制: 类固醇激素分子质量较小，且是脂溶性的，可通过扩散或载体转运进入训细 胞，可以进行激素进入细胞后先与胞浆内的受体结合。这类激素的受体通常是结合 DNA 的蛋白质，一旦激素结 合到受体上，受体就转变成一种转录的增强子而特定的基因就得到扩增表达，这种作用是通过基因转录形成 mRNA 而实现的，过程较慢。这些激素的原发效应反映在基因表达上，而不表现在酶的激活或转运过程的变化 上。由于这种作用是通过基因转录形成 mRNA 而实现的，因此作用过程较慢。 (2) 肽和蛋白质) 激素作用机制: 肽《和和蛋白质) 激素为水溶性，分子质量大，不能进入细胞膜，激素 到达竹细胞后，首先和驾细胞膜上的特异性受体相结合，活化的受体刺激与之偶联的蛋白活化,刺激细胞内第二 信使产生。第二信使上调蛋白激酶活性，进一步催化下游靶蛋白磷酸化，发挥生物学作用。还有一种机制是激素 与受体酷氨酸激酶 (TPK) 结合后，使原来无活性的 TPK 变为有活性的 TPK，TPK 众化受体分子自身 Tyr 残基 磷酸化，并进一步提高 TPK 的活性，使其他底物蛋白磷酸化，通过一系列的反应产生相应的生理效应。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex24","no":24,"type":"简答","q":"胰岛素是怎样调节糖代谢的?","analysis":"血糖升高，葡萄糖经GLUT2进入β细胞，葡糖激酶磷酸化，糖酵解使ATP/ADP升高；ATP敏感K+通道关闭，膜去极化，电压门控Ca2+通道开放，Ca2+内流触发胰岛素囊泡胞吐。胰岛素促组织摄取葡萄糖，血糖下降后又抑制分泌，形成反馈环。","answer":"进食富糖食品后葡萄糖从小肠进入血流，血糖升高导致胰腺分泌胰岛素增加《而胰高血糖素降低)。具 体过程如下: C1) 当血糖升高时,， 葡萄糖转运蛋白运载葡萄糖进入 B-细胞, 在这里葡萄糖立即被已糖激酶IV(葡糖激酶) 转化为 6-磷酸葡糖，并进入糖酵解; (2) 随着葡萄糖分解代谢速率的增加，ATP 升高，导致质膜中 ATP-门控 K \"通道关闭; (3) K 的外向流量减少造成膜去极化; (4) 膜的去极化打开电位门控 Ca通道，使细胞溶胶中[Ca2]增加; (5) Ca的增加触发胰岛素通过胞吐释放。 大脑整合有关能量供需方面的信号和来自副交感和交感神经系统的信号也影响胰岛素的释放。 在整个过程中有一个反馈环限制激素释放: 胰岛素通过刺激组织摄取和葡萄糖使血糖降低; B-细胞根据通向已 糖激酶反应的葡萄糖流量减小检测出血糖下降; 这就减慢或停止胰岛素的释放。 这一反馈调节保持血糖浓度基本 稳定，尽管进食有很大的变动。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex25","no":25,"type":"简答","q":"CL) 皮质激素主要包括哪些激素? 〈2) 骨上腺素和去甲肯上腺素在功能上有何异同?","analysis":"皮质激素分糖皮质激素（皮质醇、可的松、皮质酮）和盐皮质激素（醛固酮、11-脱氧皮质酮）。肾上腺素和去甲肾上腺素都升血压、加快心率、促糖原分解；肾上腺素对心率和代谢作用更强，去甲肾上腺素缩血管/升压更明显。","answer":"CL) 皮质激素可以分为糖皮质激素和盐皮质激素。糖皮质激素主要有皮质醇、可的松和皮质酮;! 盐皮质 激素主要有醛固酮、11-脱氧皮质酮。 (2) 上肾上腺素和去甲皮上腺素功能上的异同如表 14-8 所示。 表 14-8 ”肾上腺素和去甲肯上腺素功能上的异同 引起血压升高、心跳加快、血管紧张、 = = me 心肌血流量加大等 原分解作用〈升高血糖 比肾上腺素强 20 信 8，甲状腺激素在体内过多或不足对机体有何影响? 答: 甲状腺激素包括甲状腺素和三碘甲状原氮酸，其功能是促进组织特别是肝和肌肉组织的产能代谢，加强 线粒体中的氧化磷酸化，增加 ATP 的生成量，而 ATP 的增加亦为核酸和蛋白质等的合成提供了能量，总的结果 促进机体的生长和发育。甲状腺机能亢进也就是甲状腺激素分泌过多，基础代谢率高，身体消瘦、神经紧张、心 跳加快、出汗、颤拌，并有眼球突出的症状。甲状腺机能减退也就是甲状腺激素分泌过多分泌不足，基础代谢率 下降，产能减小，患者不能正常生长、发育、精神和智力以及生殖器官的发育也都受到影响。小儿时期因甲状腺 机能不全或因缺碘甲状腺激素合成受阻，则出现呆小症: 体形小、智力低和性功能不成熟等。成人缺碘则出现面 部和手肿大的症状，是皮下结缔组织增厚的缘故，还有阻力、有呆滞、记忆力减退等。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex26","no":26,"type":"简答","q":"C1) 试述符酮和肉二醇的生理功能。(2) 性激素分沁率乱会造成机体形态和功能上的什么变化?","analysis":"睾酮促男性性器官发育、副性征、精子发生、骨骼和代谢；雌二醇促女性生殖器官发育、第二性征、与孕激素协同形成月经周期。性激素紊乱可致性器官发育异常、第二性征改变、月经紊乱、不孕、肿瘤等。","answer":"〈1) 举酮的主要生理功能是促进男性性器官发育，刺激男性副性征的出现，维持精子产生和正常性欲， 同时还可以促进骨骼生长、促进代谢作用; 雌二醇的生理功能是促进女性生殖器官的发育及功能形成，第二性征 的出现和维持，并与孕激素协同合作，形成月经周期。 (2) 性激素分泌率乱会影响机体性器官的发育成熟，影响第二性征及性行为。男性雄激素水平低下，身体 会发生女性化,女性雄激素分泌过多会发生多毛证的症状; 峻激素紊乱会导致月经不调或停经，妊垦异常或不孕 不育，子宫或卵巢发育不良，发生肿瘤等。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex27","no":27,"type":"简答","q":"避孕药的设计原理是什么?","analysis":"避孕药多用合成雌激素/孕激素，负反馈抑制下丘脑GnRH和垂体FSH/LH，抑制排卵；同时改变宫颈黏液（精子难穿透）、子宫内膜（不利于着床）和输卵管活动。男性避孕药抑制精子发生。","answer":"避孕药一般是人工合成的肉激素和雄激素，有女性避孕药和男性避孕药。避孕原理是代替性激素，反馈 抑制下匡脑-垂体-性腺，特别是抑制垂体分泌促性腺激素，从而抑制性腺功能。以卵巢为例，避孕药代替肉激素 抑制垂体产生促性腺激素，从而抑制了卵梨排卵，并改变子宫颈黏液，使精子不宜穿透，或使子宫腺体减少肝糖 的制造，让宫胚不易存活，或是改变子宫和输卵管的活动方式，阻碍受精卵的运送。最终使精卵无法结合形成受 精卵，从而达到避孕的效果。 11， 何谓信号转导? 信号转导的基本过程是怎样的? 答:〈1) 信号转导是指细胞外的信号〈包括机械、化学和电信号等) 被放大并转化为细胞内的化学变化〈细 胞应答) 的过程。 (2) 信号转导的基本过程; 包一个信号跟受体发生相互作用; 名被活化了的受体跟细胞机器相互作用，产生第二信使或细胞蛋白质活性发生变化; 鲜靶细胞的代谢活动发生改变， 多阻断受体或把它从细胞表面除去，转导过程结束。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex28","no":28,"type":"简答","q":"信号转导有哪些共同特点?","analysis":"信号转导：胞外信号（化学/机械/电）与受体结合→受体活化→激活G蛋白/酶/第二信使→下游蛋白磷酸化→代谢或基因表达改变→受体脱敏/内吞，信号终止。特点：专一、敏感、放大、模块化、整合、脱敏。","answer":"信号转导有以下共同特点: C1) 信号转导的专一性 专一性是通过信号和受体之间的精确互补实现的。一个给定信号的受体或一个给定信号途径的胞内靶只在某 些类型的细胞中存在。 (2) 信号转导的敏感性 在三个方面可以说明信号转导的敏感性: 中受体对信号分子有高度亲和力; @@受体-配体〈信号分子) 相互 作用经常具有协同性: 配体浓度的小变化则引起受体活性的大变化; @@酶级联对信号具有放大作用，酶级联是指 一个跟信号受体结合的酶被连续激活的反应链，即酶催化酶的生化序列。 (3) 信号转导分子的模块性 模块性是指一个细胞能组合和匹配一套信号转导分子，以创建具有不同功能和细胞定位的复合体。 许多信和号 转导蛋白质具有多结构域，能识别其他蛋白质中或细胞骨架或质膜中的专一特点。因此，单个的模块是多价的， 允许这些模块组装成各种各样的多酶复合体 (4) 受体系统的脱敏作用 当一个信号连续出现时，受体的活化触发了反馈循环，阻断受体把它从细胞表面除去; 当刺激降到某一闪值 时，系统重新变得敏感。 (5) 转导系统的整合作用 整合是指系统接受多信号并产生适合细胞或生物体需要的统一应答能力。不同的信号途径在几个水平上可以 互相转换，以维持细胞和生物体的内稳态。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex29","no":29,"type":"简答","q":"试述友上腺素受体、胰岛素受体的结构特点。","analysis":"肾上腺素受体是7次跨膜、与G蛋白偶联的受体。胰岛素受体是膜糖蛋白，α2β2，由二硫键连接；α亚基在膜外结合胰岛素，β亚基跨膜、含酪氨酸激酶结构域，配体结合后自磷酸化并磷酸化底物。","answer":"(1) 肾上腺素受体是一个跨膜的受体蛋白，横路在靶细胞的细胞膜上，像其他一些与 G 蛋白偶联的受 体，如视紫质-光受体以及重毒碱的乙酰胆碱受体等一样，都是含有具 7 个螺旋区的受体。 (2) 胰岛素受体的相对分子量为 300000，它与胰岛素结合非常紧密，所形成的复合物的解离常数很低。是 整合在细胞膜上的一种糖蛋白，由两个 o-链和两个 B-链通过 3 个二硫键联结而组成，o-链处于细胞膜外侧，B- 链则穿过细胞膜。从纵训图可以看到，此受体由左右各 1 个 oP 单位组成，每一个 中 单位都从一个具有 1382 个 氨基酸残基的单链前体衍生而成。这个前体由一段信号肽为起始端，后面接着 w-亚基的序列，再接着高度碱性 的四肽，最后为B 亚基的序列。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex30","no":30,"type":"简答","q":"GR G 蛋白和和钙调蛋白的结构和功能特点。","analysis":"G蛋白位于膜内侧，αβγ三聚体；GDP结合为关闭，GTP结合α亚基活化并解离，调节腺苷酸环化酶等，GTP水解终止，具放大作用。钙调蛋白CaM是钙传感器，结合Ca²⁺后构象改变，调节CaM激酶、磷酸二酯酶等，参与钙信号。","answer":"G 蛋白是一个界面蛋白，处于细胞膜内侧，由 w、B、Y 三个亚基组成。它变动于它的 GDP 形式〈对环 化酶无活性) 及它的 GTP 形式 (有活性) 之间。无激素时，几乎所有的 G 蛋白都处于无活性的 GDP 形式。当 激素结合到受体上时，触发 GTP 将结合态的 GDP 取代下来: 激素-受体复合物结合到 G 蛋白上，使得结合态的 GDP MG 蛋白上释放，GTP 进入 G 和蛋白。接着，负载着 GTP 的 w亚基从B、y 亚基上解离下来，然后 G-GTP 活化环化酶。每一个被激素结合的受体又促使形成分子 G-GTP，由此给出“放大”的效应。此后，结合着 u 亚 基的 GTP 又在适当的条件下水解， 最终关闭这个由激素所触发的循环。结合态 GTP 缓慢的水解表明 G 蛋白是一 个 GTPase。也就是说这个调节蛋白具有一种内藏式的脱活化作用的设计。当缺乏激素时，GTP-GDP 交换反应的 速度大大地降低。最后，几乎所有的 G 蛋白均以结合着 GDP 的无活性形式存在，接着，几乎所有的环化酶都转 变成为无活性状态。 UR (CaM) 是钙传感器家族一 -结合钙蛋白质中的一种，存在于几乎所有的真核细胞中，对于任何微 量的钙都能敏感地捕获。状椎动物的钙调蛋白在 115 位都含有一个三甲基赖氨酸，这是翻译后的修饰产物，它可 能起着增加 CaM 与壮酶亲和力的作用。钙调和蛋白的一级结构在进化上呈现很强的保守性。钙调蛋白结构上若发 生突变是很容易致死的。另外，还有许多生理活动受它的协调，有人称它为细胞代谢调控的综合剂。特别是它作 为细胞内钙离子的受体，既调节细胞内钙离子的浓度，又媒介钙离子的功能，同时还调节第二信使 CAMP 的合 成与分解。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex31","no":31,"type":"简答","q":"试述明上腺素在促进糖原降解中的级联放大。","analysis":"肾上腺素结合β受体→激活腺苷酸环化酶→cAMP↑→PKA活化→磷酸化酶b激酶活化→糖原磷酸化酶b→a→糖原分解为1-磷酸葡萄糖→葡萄糖。每步放大，少量激素迅速升高血糖。","answer":"肾上腺素是一种含氨激素，当肾上腺素到达邯细胞后通过与受体结合，激活环化酶，生成cAMP，这是 一次信号放大过程; cAMP 别构刺激蛋白激酶活性，蛋白激酶糖原合成酶磷酸化，而后失活，这又是一次信号放 大反应; 蛋白激酶还可以磷酸化，磷酸化激酶使其激活，激活的磷酸化激酶使糖原磷酸化激活，成为有活性的磷 酸化酶 a，磷酸化酶 a 催化糖原转化为 1-磷酸葡萄糖，进而转变成葡萄糖，这也是一次信号放大反应，经过这些 步骤，在极短时间内可以提高血糖含量，产生大量的 ArTP，提供能量。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex32","no":32,"type":"简答","q":"举出真核生物中 6 个普通类型的蛋白激酶和激活每个类型的直接因子。","analysis":"常见蛋白激酶及直接激活因子：PKA—cAMP；PKC—二酰甘油（DAG）和Ca²⁺；MAPK—Raf/MAPKKK级联；CaM激酶—Ca²⁺/钙调蛋白；PKG—cGMP；受体酪氨酸激酶—生长因子配体。","answer":"巴蛋白激酶 A，需要 cAMP 激活; 包和蛋白激酶 C，需要二酰甘油 (DG) 激活: @MAPK 激酶需要 Raf 蛋白激活; 外钙调蛋白，需要钙离子和钙调蛋白激活; OR ABA G. HI cGMP 激活; @酷氨酸激酶，需要胰 Ly GE","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex33","no":33,"type":"计算","q":"1 mg胰岛素约多少IU？","analysis":"1 mg≈25.7 IU。","answer":"约25.7 IU","slide":133,"slideTitle":"计算2：激素浓度","kp":"","kpId":"bc14_s0_133"},{"id":"bc14_ex34","no":34,"type":"计算","q":"10 IU胰岛素约多少mg？","analysis":"1 IU≈0.0389 mg。","answer":"约0.389 mg","slide":133,"slideTitle":"计算2：激素浓度","kp":"","kpId":"bc14_s0_133"},{"id":"bc14_ex35","no":35,"type":"计算","q":"激素浓度10 ng/mL等于多少μg/L？","analysis":"1 ng/mL=1 μg/L。","answer":"10 μg/L","slide":133,"slideTitle":"计算2：激素浓度","kp":"","kpId":"bc14_s0_133"},{"id":"bc14_ex36","no":36,"type":"计算","q":"cAMP由ATP经哪种酶生成？","analysis":"AC。","answer":"腺苷酸环化酶","slide":133,"slideTitle":"计算2：激素浓度","kp":"","kpId":"bc14_s0_133"},{"id":"bc14_ex37","no":37,"type":"计算","q":"IP3促哪个离子释放？","analysis":"内质网。","answer":"Ca2+","slide":133,"slideTitle":"计算2：激素浓度","kp":"","kpId":"bc14_s0_133"},{"id":"bc14_ex38","no":38,"type":"计算","q":"PTH对血钙和血磷分别？","analysis":"PTH。","answer":"血钙↑、血磷↓","slide":133,"slideTitle":"计算2：激素浓度","kp":"","kpId":"bc14_s0_133"},{"id":"bc14_ex39","no":39,"type":"名词","q":"解释名词：激素","analysis":"不供能，调节代谢。","answer":"内分泌细胞分泌、经体液运输、作用于靶细胞受体的微量高效信息分子。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex40","no":40,"type":"名词","q":"解释名词：第二信使","analysis":"放大信号。","answer":"激素与膜受体结合后在细胞内生成的小分子信号物质，如cAMP、IP3、DAG、Ca2+。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex41","no":41,"type":"名词","q":"解释名词：G蛋白","analysis":"Gs/Gi/Gq。","answer":"与GPCR偶联、可结合GTP/GDP的膜蛋白，激活或抑制效应酶。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex42","no":42,"type":"名词","q":"解释名词：RTK","analysis":"胰岛素受体。","answer":"受体酪氨酸激酶，配体结合后自磷酸化并激活下游通路。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex43","no":43,"type":"名词","q":"解释名词：核受体","analysis":"类固醇/甲状腺激素。","answer":"位于细胞核/胞质的受体，结合脂溶性激素后调控基因转录。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex44","no":44,"type":"名词","q":"解释名词：PTH","analysis":"骨/肾/肠。","answer":"甲状旁腺激素，升血钙、降血磷。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex45","no":45,"type":"名词","q":"解释名词：降钙素","analysis":"CT。","answer":"甲状腺C细胞分泌，抑制骨吸收、降血钙。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex46","no":46,"type":"名词","q":"解释名词：胰岛素","analysis":"GLUT4。","answer":"胰岛β细胞分泌的蛋白激素，A/B链二硫键，降血糖。","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex47","no":47,"type":"判断","q":"水溶性激素通常作用于膜受体。","analysis":"不能自由入细胞。","answer":"对","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex48","no":48,"type":"判断","q":"cAMP由PLC生成。","analysis":"cAMP由腺苷酸环化酶生成。","answer":"错","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex49","no":49,"type":"判断","q":"胰岛素受体是酪氨酸激酶受体。","analysis":"RTK自磷酸化。","answer":"对","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"},{"id":"bc14_ex50","no":50,"type":"判断","q":"PTH降低血钙。","analysis":"PTH升血钙。","answer":"错","slide":98,"slideTitle":"AI主讲1：激素总览","kp":"","kpId":"bc14_s0_98"}]};